import type { BankQuestion } from "@/lib/bank";

/** Supreme Court, High Courts and Judicial Review (Indian Polity): 222 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"polity-judiciary-1","question":"The Supreme Court of India is established under which Article?","options":["Article 129","Article 214","Article 124","Article 32"],"answer":2,"explanation":"Article 124 establishes the Supreme Court and covers the appointment of its judges. Article 214 provides for the High Courts.","difficulty":"easy","source":"SSC CGL · RRB NTPC · State PSCs","questionHi":"भारत का सर्वोच्च न्यायालय किस अनुच्छेद के अंतर्गत स्थापित किया गया है?","optionsHi":["अनुच्छेद 129","अनुच्छेद 214","अनुच्छेद 124","अनुच्छेद 32"],"explanationHi":"अनुच्छेद 124 सर्वोच्च न्यायालय की स्थापना और उसके न्यायाधीशों की नियुक्ति का प्रावधान करता है। अनुच्छेद 214 उच्च न्यायालयों का प्रावधान करता है।"},
  {"id":"polity-judiciary-2","question":"The Supreme Court of India was inaugurated on:","options":["26 January 1950","28 January 1950","15 August 1947","26 November 1949"],"answer":1,"explanation":"The Supreme Court was inaugurated on 28 January 1950, two days after the Constitution came into force. It replaced the Federal Court of India.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भारत के सर्वोच्च न्यायालय का उद्घाटन किस तिथि को हुआ था?","optionsHi":["26 जनवरी 1950","28 जनवरी 1950","15 अगस्त 1947","26 नवंबर 1949"],"explanationHi":"सर्वोच्च न्यायालय का उद्घाटन 28 जनवरी 1950 को हुआ, यानी संविधान लागू होने के दो दिन बाद। इसने भारत के संघीय न्यायालय का स्थान लिया।"},
  {"id":"polity-judiciary-3","question":"A judge of the Supreme Court retires at the age of:","options":["62 years","60 years","65 years","70 years"],"answer":2,"explanation":"Supreme Court judges hold office until 65 (Article 124(2)). High Court judges retire at 62.","difficulty":"easy","source":"SSC CGL · RRB NTPC · State PSCs","questionHi":"सर्वोच्च न्यायालय का न्यायाधीश किस आयु में सेवानिवृत्त होता है?","optionsHi":["62 वर्ष","60 वर्ष","65 वर्ष","70 वर्ष"],"explanationHi":"सर्वोच्च न्यायालय के न्यायाधीश 65 वर्ष की आयु तक पद पर रहते हैं (अनुच्छेद 124(2))। उच्च न्यायालय के न्यायाधीश 62 वर्ष की आयु में सेवानिवृत्त होते हैं।"},
  {"id":"polity-judiciary-4","question":"A judge of a High Court retires at the age of:","options":["62 years","65 years","60 years","58 years"],"answer":0,"explanation":"Article 217(1) sets 62 as the retirement age for High Court judges. It was raised from 60 by the 15th Amendment (1963).","difficulty":"easy","source":"SSC CGL · RRB NTPC · State PSCs","questionHi":"उच्च न्यायालय का न्यायाधीश किस आयु में सेवानिवृत्त होता है?","optionsHi":["62 वर्ष","65 वर्ष","60 वर्ष","58 वर्ष"],"explanationHi":"अनुच्छेद 217(1) उच्च न्यायालय के न्यायाधीशों की सेवानिवृत्ति की आयु 62 वर्ष निर्धारित करता है। इसे 15वें संशोधन (1963) द्वारा 60 से बढ़ाकर 62 किया गया था।"},
  {"id":"polity-judiciary-5","question":"High Courts get the power to issue writs from:","options":["Article 227","Article 226","Article 136","Article 32"],"answer":1,"explanation":"Article 226 lets High Courts issue writs. Article 32 is the Supreme Court's writ power, and Article 227 gives High Courts superintendence over the courts below them.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · State PSCs","questionHi":"उच्च न्यायालयों को रिट जारी करने की शक्ति किससे प्राप्त होती है?","optionsHi":["अनुच्छेद 227","अनुच्छेद 226","अनुच्छेद 136","अनुच्छेद 32"],"explanationHi":"अनुच्छेद 226 उच्च न्यायालयों को रिट जारी करने की शक्ति देता है। अनुच्छेद 32 सर्वोच्च न्यायालय की रिट शक्ति है, जबकि अनुच्छेद 227 उच्च न्यायालयों को अपने अधीनस्थ न्यायालयों पर अधीक्षण की शक्ति देता है।"},
  {"id":"polity-judiciary-6","question":"The collegium system for appointing judges came from which case?","options":["Kesavananda Bharati case (1973)","Minerva Mills case (1980)","S. P. Gupta case (1981)","Second Judges case (1993)"],"answer":3,"explanation":"In the Second Judges case (1993), SC Advocates-on-Record Association, the Court read “consultation” with the Chief Justice as “concurrence” and created the collegium. The First Judges case (S. P. Gupta, 1981) had given the executive primacy.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · UPSC Prelims","questionHi":"न्यायाधीशों की नियुक्ति के लिए कॉलेजियम प्रणाली किस मामले से उत्पन्न हुई?","optionsHi":["केशवानंद भारती मामला (1973)","मिनर्वा मिल्स मामला (1980)","एस. पी. गुप्ता मामला (1981)","द्वितीय न्यायाधीश मामला (1993)"],"explanationHi":"द्वितीय न्यायाधीश मामले (1993), सुप्रीम कोर्ट एडवोकेट्स-ऑन-रिकॉर्ड एसोसिएशन में, न्यायालय ने मुख्य न्यायाधीश के साथ ‘परामर्श’ का अर्थ ‘सहमति’ माना और कॉलेजियम की रचना की। प्रथम न्यायाधीश मामले (एस. पी. गुप्ता, 1981) में कार्यपालिका को प्राथमिकता मिली थी।"},
  {"id":"polity-judiciary-7","question":"The President can seek the Supreme Court's advisory opinion under:","options":["Article 131","Article 148","Article 143","Article 136"],"answer":2,"explanation":"Article 143 gives the Supreme Court advisory jurisdiction on references from the President. Article 131 is its original jurisdiction, and Article 136 covers special leave to appeal.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · State PSCs","questionHi":"राष्ट्रपति सर्वोच्च न्यायालय से परामर्शी राय किस अनुच्छेद के अंतर्गत मांग सकता है?","optionsHi":["अनुच्छेद 131","अनुच्छेद 148","अनुच्छेद 143","अनुच्छेद 136"],"explanationHi":"अनुच्छेद 143 राष्ट्रपति द्वारा भेजे गए संदर्भों पर सर्वोच्च न्यायालय को परामर्शी क्षेत्राधिकार देता है। अनुच्छेद 131 उसका मूल क्षेत्राधिकार है और अनुच्छेद 136 विशेष अनुमति याचिका से संबंधित है।"},
  {"id":"polity-judiciary-8","question":"Which Article makes the Supreme Court a “court of record”?","options":["Article 215","Article 131","Article 129","Article 137"],"answer":2,"explanation":"Article 129 makes the Supreme Court a court of record with power to punish for contempt of itself. Article 215 does the same for the High Courts.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कौन-सा अनुच्छेद सर्वोच्च न्यायालय को ‘अभिलेख न्यायालय’ बनाता है?","optionsHi":["अनुच्छेद 215","अनुच्छेद 131","अनुच्छेद 129","अनुच्छेद 137"],"explanationHi":"अनुच्छेद 129 सर्वोच्च न्यायालय को अभिलेख न्यायालय बनाता है और उसे अपनी अवमानना के लिए दंड देने की शक्ति देता है। अनुच्छेद 215 उच्च न्यायालयों के लिए यही प्रावधान करता है।"},
  {"id":"polity-judiciary-9","question":"Public Interest Litigation in India is mainly credited to which judges?","options":["P. N. Bhagwati and V. R. Krishna Iyer","Koka Subba Rao and M. Hidayatullah","Y. V. Chandrachud and P. B. Gajendragadkar","A. N. Ray and Y. K. Sabharwal"],"answer":0,"explanation":"Justices P. N. Bhagwati and V. R. Krishna Iyer relaxed the rule on who may sue (locus standi) in the late 1970s and early 1980s, which opened the door to PIL.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · State PSCs","questionHi":"भारत में जनहित याचिका (PIL) का श्रेय मुख्य रूप से किन न्यायाधीशों को दिया जाता है?","optionsHi":["पी. एन. भगवती और वी. आर. कृष्णा अय्यर","कोका सुब्बा राव और एम. हिदायतुल्लाह","वाई. वी. चंद्रचूड़ और पी. बी. गजेंद्रगडकर","ए. एन. रे और वाई. के. सभरवाल"],"explanationHi":"न्यायमूर्ति पी. एन. भगवती और वी. आर. कृष्णा अय्यर ने 1970 के दशक के उत्तरार्ध और 1980 के दशक की शुरुआत में वाद दायर करने के अधिकार (locus standi) के नियम को सरल किया, जिससे जनहित याचिका का मार्ग खुला।"},
  {"id":"polity-judiciary-10","question":"A dispute between the Government of India and a State goes to the Supreme Court under its:","options":["Writ jurisdiction under Article 32","Original jurisdiction under Article 131","Appellate jurisdiction under Article 133","Advisory jurisdiction under Article 143"],"answer":1,"explanation":"Article 131 gives the Supreme Court exclusive original jurisdiction over disputes between the Centre and States, or between States.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · State PSCs","questionHi":"भारत सरकार और किसी राज्य के बीच विवाद सर्वोच्च न्यायालय के किस क्षेत्राधिकार में आता है?","optionsHi":["अनुच्छेद 32 के अंतर्गत रिट क्षेत्राधिकार","अनुच्छेद 131 के अंतर्गत मूल क्षेत्राधिकार","अनुच्छेद 133 के अंतर्गत अपीलीय क्षेत्राधिकार","अनुच्छेद 143 के अंतर्गत परामर्शी क्षेत्राधिकार"],"explanationHi":"अनुच्छेद 131 सर्वोच्च न्यायालय को केंद्र और राज्यों के बीच, या राज्यों के बीच विवादों पर अनन्य मूल क्षेत्राधिकार देता है।"},
  {"id":"polity-judiciary-11","question":"On which grounds can a Supreme Court judge be removed?","options":["Proved misbehaviour or incapacity","Any ground the President thinks fit","Violation of the Constitution","Loss of confidence of Parliament"],"answer":0,"explanation":"Article 124(4) allows removal only for proved misbehaviour or incapacity, by an order of the President after an address by both Houses passed by a special majority. “Violation of the Constitution” is the ground for impeaching the President.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · UPSC Prelims","questionHi":"सर्वोच्च न्यायालय के न्यायाधीश को किन आधारों पर हटाया जा सकता है?","optionsHi":["सिद्ध कदाचार या अक्षमता","कोई भी आधार जिसे राष्ट्रपति उचित समझे","संविधान का उल्लंघन","संसद का विश्वास खो देना"],"explanationHi":"अनुच्छेद 124(4) केवल सिद्ध कदाचार या अक्षमता के आधार पर हटाने की अनुमति देता है। यह राष्ट्रपति के आदेश से होता है, जो संसद के दोनों सदनों द्वारा विशेष बहुमत से पारित समावेदन के बाद दिया जाता है। ‘संविधान का उल्लंघन’ राष्ट्रपति पर महाभियोग का आधार है।"},
  {"id":"polity-judiciary-12","question":"How many judges, including the Chief Justice, can the Supreme Court have at present?","options":["36","26","31","34"],"answer":3,"explanation":"The Supreme Court (Number of Judges) Amendment Act, 2019 raised the strength to 33 judges plus the Chief Justice, a total of 34. The original Constitution provided for 7 judges plus the CJI.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"वर्तमान में सर्वोच्च न्यायालय में मुख्य न्यायाधीश सहित अधिकतम कितने न्यायाधीश हो सकते हैं?","optionsHi":["36","26","31","34"],"explanationHi":"सर्वोच्च न्यायालय (न्यायाधीशों की संख्या) संशोधन अधिनियम, 2019 ने संख्या बढ़ाकर 33 न्यायाधीश और मुख्य न्यायाधीश, यानी कुल 34 कर दी। मूल संविधान में 7 न्यायाधीश और भारत के मुख्य न्यायाधीश का प्रावधान था।"},
  {"id":"polity-judiciary-13","question":"The 99th Amendment and the NJAC Act it supported were struck down by the Supreme Court in:","options":["1998","2014","2015","1993"],"answer":2,"explanation":"In the Fourth Judges case (October 2015) the Court struck down the 99th Amendment and the NJAC Act as violating judicial independence, a basic feature, and revived the collegium. The trap is 2014, when the Amendment and the Act were passed; 1993 and 1998 are the Second and Third Judges cases that created the collegium.","difficulty":"hard","source":"UPSC Prelims","questionHi":"99वें संशोधन और उसके समर्थन में बने NJAC अधिनियम को सर्वोच्च न्यायालय ने किस वर्ष रद्द किया?","optionsHi":["1998","2014","2015","1993"],"explanationHi":"चतुर्थ न्यायाधीश मामले (अक्टूबर 2015) में न्यायालय ने 99वें संशोधन और NJAC अधिनियम को न्यायपालिका की स्वतंत्रता, जो मूल ढांचे का हिस्सा है, का उल्लंघन मानकर रद्द कर दिया और कॉलेजियम प्रणाली को पुनर्जीवित किया। भ्रम का कारण 2014 है, जब संशोधन और अधिनियम पारित हुए थे; 1993 और 1998 द्वितीय और तृतीय न्यायाधीश मामले हैं जिन्होंने कॉलेजियम बनाया।"},
  {"id":"polity-judiciary-14","question":"The “curative petition” was created by the Supreme Court in:","options":["S. R. Bommai v. Union of India","Rupa Ashok Hurra v. Ashok Hurra","Maneka Gandhi v. Union of India","Vishaka v. State of Rajasthan"],"answer":1,"explanation":"In Rupa Ashok Hurra (2002) the Court allowed a curative petition to correct a gross miscarriage of justice even after a review petition has been dismissed.","difficulty":"hard","source":"UPSC Prelims","questionHi":"‘उपचारात्मक याचिका’ (curative petition) की रचना सर्वोच्च न्यायालय ने किस मामले में की?","optionsHi":["एस. आर. बोम्मई बनाम भारत संघ","रूपा अशोक हुरा बनाम अशोक हुरा","मेनका गांधी बनाम भारत संघ","विशाखा बनाम राजस्थान राज्य"],"explanationHi":"रूपा अशोक हुरा (2002) में न्यायालय ने पुनर्विचार याचिका खारिज होने के बाद भी घोर अन्याय को सुधारने के लिए उपचारात्मक याचिका की अनुमति दी।"},
  {"id":"polity-judiciary-15","question":"Under which Article does a law declared by the Supreme Court bind all courts in India?","options":["Article 144","Article 137","Article 141","Article 142"],"answer":2,"explanation":"Article 141 makes Supreme Court rulings binding on all courts in India. Article 142 lets the Court pass orders for “complete justice”, and Article 144 requires all authorities to act in aid of the Supreme Court.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस अनुच्छेद के अंतर्गत सर्वोच्च न्यायालय द्वारा घोषित कानून भारत के सभी न्यायालयों पर बाध्यकारी होता है?","optionsHi":["अनुच्छेद 144","अनुच्छेद 137","अनुच्छेद 141","अनुच्छेद 142"],"explanationHi":"अनुच्छेद 141 सर्वोच्च न्यायालय के निर्णयों को भारत के सभी न्यायालयों पर बाध्यकारी बनाता है। अनुच्छेद 142 न्यायालय को ‘पूर्ण न्याय’ के लिए आदेश देने की शक्ति देता है और अनुच्छेद 144 सभी प्राधिकारियों को सर्वोच्च न्यायालय की सहायता में कार्य करने का निर्देश देता है।"},
  {"id":"polity-judiciary-16","question":"Which Article lets the Supreme Court pass any decree or order needed to do “complete justice” in a case before it?","options":["Article 142","Article 136","Article 145","Article 139A"],"answer":0,"explanation":"Article 142 is the source of the Court's “complete justice” powers, used for example in the Bhopal gas settlement and the Ayodhya judgment.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कौन-सा अनुच्छेद सर्वोच्च न्यायालय को अपने समक्ष किसी मामले में ‘पूर्ण न्याय’ करने के लिए आवश्यक कोई भी डिक्री या आदेश पारित करने देता है?","optionsHi":["अनुच्छेद 142","अनुच्छेद 136","अनुच्छेद 145","अनुच्छेद 139A"],"explanationHi":"अनुच्छेद 142 न्यायालय की ‘पूर्ण न्याय’ की शक्तियों का स्रोत है, जिसका उपयोग उदाहरण के लिए भोपाल गैस समझौते और अयोध्या निर्णय में किया गया।"},
  {"id":"polity-judiciary-17","question":"Who appoints ad hoc judges to the Supreme Court when there is no quorum of permanent judges?","options":["The CJI, with the previous consent of the President","The Union Law Minister, in consultation with the CJI","The SC collegium, with the approval of Parliament","The President, on the advice of the Prime Minister"],"answer":0,"explanation":"Under Article 127 the Chief Justice of India, with the previous consent of the President and after consulting the Chief Justice of the High Court concerned, can ask a qualified High Court judge to sit as an ad hoc judge.","difficulty":"hard","source":"UPSC Prelims","questionHi":"स्थायी न्यायाधीशों की गणपूर्ति (कोरम) न होने पर सर्वोच्च न्यायालय में तदर्थ न्यायाधीशों की नियुक्ति कौन करता है?","optionsHi":["CJI, राष्ट्रपति की पूर्व सहमति से","केंद्रीय विधि मंत्री, CJI के परामर्श से","सर्वोच्च न्यायालय का कॉलेजियम, संसद की स्वीकृति से","राष्ट्रपति, प्रधानमंत्री की सलाह पर"],"explanationHi":"अनुच्छेद 127 के अंतर्गत भारत के मुख्य न्यायाधीश, राष्ट्रपति की पूर्व सहमति से और संबंधित उच्च न्यायालय के मुख्य न्यायाधीश से परामर्श के बाद, किसी योग्य उच्च न्यायालय के न्यायाधीश से तदर्थ न्यायाधीश के रूप में बैठने का अनुरोध कर सकते हैं।"},
  {"id":"polity-judiciary-18","question":"Special leave to appeal against any judgment of any court or tribunal (except military tribunals) is granted under:","options":["Article 139","Article 132","Article 136","Article 134"],"answer":2,"explanation":"Article 136 gives the Supreme Court discretion to grant special leave to appeal from any court or tribunal except those under the armed forces. Articles 132–134 cover regular appeals in constitutional, civil and criminal cases.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"किसी भी न्यायालय या अधिकरण (सैन्य अधिकरणों को छोड़कर) के किसी भी निर्णय के विरुद्ध अपील की विशेष अनुमति किसके अंतर्गत दी जाती है?","optionsHi":["अनुच्छेद 139","अनुच्छेद 132","अनुच्छेद 136","अनुच्छेद 134"],"explanationHi":"अनुच्छेद 136 सर्वोच्च न्यायालय को सशस्त्र बलों से संबंधित न्यायालयों या अधिकरणों को छोड़कर किसी भी न्यायालय या अधिकरण से अपील की विशेष अनुमति देने का विवेकाधिकार देता है। अनुच्छेद 132–134 संवैधानिक, दीवानी और आपराधिक मामलों में सामान्य अपील से संबंधित हैं।"},
  {"id":"polity-judiciary-19","question":"A High Court judge is transferred from one High Court to another by the:","options":["President, after consulting the Chief Justice of India","Chief Justice of India alone, on the collegium's advice","Governor of the receiving State, on the CJI's advice","Collegium of the High Court from which he is moved"],"answer":0,"explanation":"Article 222 lets the President transfer a High Court judge after consulting the Chief Justice of India. Since the Third Judges case, the CJI's opinion is formed with a collegium of senior judges.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालय के न्यायाधीश का एक उच्च न्यायालय से दूसरे में स्थानांतरण कौन करता है?","optionsHi":["राष्ट्रपति, भारत के मुख्य न्यायाधीश से परामर्श के बाद","केवल भारत के मुख्य न्यायाधीश, कॉलेजियम की सलाह पर","प्राप्तकर्ता राज्य का राज्यपाल, CJI की सलाह पर","जिस उच्च न्यायालय से उन्हें हटाया जा रहा है उसका कॉलेजियम"],"explanationHi":"अनुच्छेद 222 राष्ट्रपति को भारत के मुख्य न्यायाधीश से परामर्श के बाद उच्च न्यायालय के न्यायाधीश का स्थानांतरण करने देता है। तृतीय न्यायाधीश मामले के बाद से CJI की राय वरिष्ठ न्यायाधीशों के कॉलेजियम के साथ बनाई जाती है।"},
  {"id":"polity-judiciary-20","question":"According to the Third Judges case (1998), the collegium that recommends Supreme Court appointments consists of the CJI and:","options":["the four senior-most judges","all judges of the Supreme Court","the three senior-most judges","the two senior-most judges"],"answer":0,"explanation":"The 1998 Presidential reference expanded the collegium to the CJI and the four senior-most puisne judges for Supreme Court appointments. For High Court appointments it is the CJI and the two senior-most judges.","difficulty":"hard","source":"UPSC Prelims","questionHi":"तृतीय न्यायाधीश मामले (1998) के अनुसार, सर्वोच्च न्यायालय में नियुक्तियों की सिफारिश करने वाले कॉलेजियम में CJI और कौन होते हैं?","optionsHi":["चार वरिष्ठतम न्यायाधीश","सर्वोच्च न्यायालय के सभी न्यायाधीश","तीन वरिष्ठतम न्यायाधीश","दो वरिष्ठतम न्यायाधीश"],"explanationHi":"1998 के राष्ट्रपति संदर्भ ने कॉलेजियम का विस्तार कर उसमें CJI और चार वरिष्ठतम अन्य न्यायाधीशों को रखा, जो सर्वोच्च न्यायालय में नियुक्तियों के लिए है। उच्च न्यायालयों में नियुक्ति के लिए यह CJI और दो वरिष्ठतम न्यायाधीश होते हैं।"},
  {"id":"polity-judiciary-21","question":"Part XIV-A, which allows administrative tribunals (Article 323A), was added by the:","options":["24th Amendment","42nd Amendment","44th Amendment","52nd Amendment"],"answer":1,"explanation":"The 42nd Amendment (1976) inserted Part XIV-A with Articles 323A and 323B. The Administrative Tribunals Act followed in 1985.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"भाग XIV-A, जो प्रशासनिक अधिकरणों (अनुच्छेद 323A) की अनुमति देता है, किस संशोधन द्वारा जोड़ा गया?","optionsHi":["24वां संशोधन","42वां संशोधन","44वां संशोधन","52वां संशोधन"],"explanationHi":"42वें संशोधन (1976) ने अनुच्छेद 323A और 323B सहित भाग XIV-A जोड़ा। प्रशासनिक अधिकरण अधिनियम 1985 में बना।"},
  {"id":"polity-judiciary-22","question":"Which case held that the High Courts' power of judicial review under Articles 226 and 227 is part of the basic structure, so tribunals cannot fully replace it?","options":["S. P. Sampath Kumar (1987)","Indra Sawhney (1992)","L. Chandra Kumar (1997)","Golaknath (1967)"],"answer":2,"explanation":"L. Chandra Kumar (1997) held that tribunal decisions can be challenged before a division bench of the High Court. This overruled the opposite view taken in S. P. Sampath Kumar (1987).","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में यह माना गया कि अनुच्छेद 226 और 227 के अंतर्गत उच्च न्यायालयों की न्यायिक पुनरावलोकन की शक्ति मूल ढांचे का हिस्सा है, इसलिए अधिकरण उसे पूरी तरह प्रतिस्थापित नहीं कर सकते?","optionsHi":["एस. पी. संपत कुमार (1987)","इंदिरा साहनी (1992)","एल. चंद्र कुमार (1997)","गोलकनाथ (1967)"],"explanationHi":"एल. चंद्र कुमार (1997) में माना गया कि अधिकरणों के निर्णयों को उच्च न्यायालय की खंडपीठ के समक्ष चुनौती दी जा सकती है। इसने एस. पी. संपत कुमार (1987) में अपनाए गए विपरीत मत को पलट दिया।"},
  {"id":"polity-judiciary-23","question":"Which Article allows Parliament to set up a common High Court for two or more States?","options":["Article 222","Article 231","Article 241","Article 214"],"answer":1,"explanation":"Article 231, put in its present form by the 7th Amendment (1956), allows a common High Court. An example is the Gauhati High Court for Assam, Nagaland, Mizoram and Arunachal Pradesh.","difficulty":"hard","source":"SSC CGL · SSC CHSL · State PSCs","questionHi":"कौन-सा अनुच्छेद संसद को दो या अधिक राज्यों के लिए एक सामान्य उच्च न्यायालय स्थापित करने की अनुमति देता है?","optionsHi":["अनुच्छेद 222","अनुच्छेद 231","अनुच्छेद 241","अनुच्छेद 214"],"explanationHi":"अनुच्छेद 231, जिसे 7वें संशोधन (1956) द्वारा वर्तमान रूप दिया गया, सामान्य उच्च न्यायालय की अनुमति देता है। इसका उदाहरण असम, नागालैंड, मिजोरम और अरुणाचल प्रदेश के लिए गुवाहाटी उच्च न्यायालय है।"},
  {"id":"polity-judiciary-24","question":"Which of these is NOT a qualification for appointment as a judge of the Supreme Court?","options":["Ten years as an advocate of a High Court","Five years as a judge of a High Court","Being a distinguished jurist in the opinion of the President","Seven years as an advocate of the Supreme Court only"],"answer":3,"explanation":"Article 124(3) lists three routes: five years as a High Court judge, ten years as a High Court advocate, or being a distinguished jurist in the President's opinion. There is no seven-year Supreme Court advocate route.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सी सर्वोच्च न्यायालय के न्यायाधीश की नियुक्ति की योग्यता नहीं है?","optionsHi":["उच्च न्यायालय में अधिवक्ता के रूप में दस वर्ष","उच्च न्यायालय के न्यायाधीश के रूप में पांच वर्ष","राष्ट्रपति की राय में एक प्रतिष्ठित विधिवेत्ता होना","केवल सर्वोच्च न्यायालय में अधिवक्ता के रूप में सात वर्ष"],"explanationHi":"अनुच्छेद 124(3) तीन मार्ग बताता है: उच्च न्यायालय के न्यायाधीश के रूप में पांच वर्ष, उच्च न्यायालय में अधिवक्ता के रूप में दस वर्ष, या राष्ट्रपति की राय में प्रतिष्ठित विधिवेत्ता होना। सर्वोच्च न्यायालय में सात वर्ष के अधिवक्ता का कोई मार्ग नहीं है।"},
  {"id":"polity-judiciary-25","question":"How many of these statements are correct? I. Article 32 is itself a Fundamental Right, but Article 226 is not. II. The writ jurisdiction of a High Court is wider than that of the Supreme Court. III. The right under Article 32 can be suspended only by a constitutional amendment. IV. Certiorari can be issued against a legislative body.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. The right to move the Supreme Court can be suspended during an emergency under Article 359, without any amendment. Certiorari lies against judicial and quasi-judicial bodies (and administrative authorities affecting rights), not legislatures.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. अनुच्छेद 32 स्वयं एक मौलिक अधिकार है, किंतु अनुच्छेद 226 नहीं है। II. उच्च न्यायालय का रिट क्षेत्राधिकार सर्वोच्च न्यायालय से व्यापक है। III. अनुच्छेद 32 के अधिकार को केवल संवैधानिक संशोधन द्वारा निलंबित किया जा सकता है। IV. उत्प्रेषण (certiorari) विधायी निकाय के विरुद्ध जारी किया जा सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। सर्वोच्च न्यायालय में जाने का अधिकार आपातकाल के दौरान अनुच्छेद 359 के अंतर्गत बिना किसी संशोधन के निलंबित किया जा सकता है। उत्प्रेषण न्यायिक और अर्ध-न्यायिक निकायों (तथा अधिकारों को प्रभावित करने वाले प्रशासनिक प्राधिकारियों) के विरुद्ध जारी होता है, विधायिकाओं के विरुद्ध नहीं।"},
  {"id":"polity-judiciary-26","question":"Match the cases with what they held: A. S. P. Gupta (1981) B. Vishaka (1997) C. Hussainara Khatoon (1979) D. Indra Sawhney (1992) — 1. Guidelines against sexual harassment at the workplace 2. Executive primacy in appointing judges 3. A cap of 50% on reservations 4. Speedy trial for undertrial prisoners","options":["A-1, B-2, C-4, D-3","A-2, B-4, C-1, D-3","A-3, B-1, C-4, D-2","A-2, B-1, C-4, D-3"],"answer":3,"explanation":"S. P. Gupta (First Judges case) gave the executive primacy in appointments. Vishaka laid down the workplace harassment guidelines. Hussainara Khatoon, an early PIL, read speedy trial into Article 21. Indra Sawhney fixed the 50% ceiling.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"मामलों का मिलान उनके निर्णय से कीजिए: A. एस. पी. गुप्ता (1981) B. विशाखा (1997) C. हुसैनारा खातून (1979) D. इंदिरा साहनी (1992) — 1. कार्यस्थल पर यौन उत्पीड़न के विरुद्ध दिशानिर्देश 2. न्यायाधीशों की नियुक्ति में कार्यपालिका की प्राथमिकता 3. आरक्षण की 50% की सीमा 4. विचाराधीन कैदियों के लिए शीघ्र सुनवाई","optionsHi":["A-1, B-2, C-4, D-3","A-2, B-4, C-1, D-3","A-3, B-1, C-4, D-2","A-2, B-1, C-4, D-3"],"explanationHi":"एस. पी. गुप्ता (प्रथम न्यायाधीश मामला) ने नियुक्तियों में कार्यपालिका को प्राथमिकता दी। विशाखा ने कार्यस्थल पर उत्पीड़न के दिशानिर्देश तय किए। हुसैनारा खातून, एक प्रारंभिक जनहित याचिका, ने शीघ्र सुनवाई को अनुच्छेद 21 में शामिल माना। इंदिरा साहनी ने 50% की सीमा तय की।"},
  {"id":"polity-judiciary-27","question":"Assertion (A): The writ jurisdiction of a High Court is wider than that of the Supreme Court. Reason (R): A High Court can issue writs both to enforce Fundamental Rights and “for any other purpose”.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true, and R explains A. Article 226 covers ordinary legal rights as well, while Article 32 is limited to Fundamental Rights.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उच्च न्यायालय का रिट क्षेत्राधिकार सर्वोच्च न्यायालय से व्यापक है। कारण (R): उच्च न्यायालय मौलिक अधिकारों के प्रवर्तन के लिए तथा ‘किसी अन्य प्रयोजन’ के लिए भी रिट जारी कर सकता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं किंतु R, A की सही व्याख्या नहीं है","A सही है किंतु R गलत है","A गलत है किंतु R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है। अनुच्छेद 226 सामान्य कानूनी अधिकारों को भी शामिल करता है, जबकि अनुच्छेद 32 केवल मौलिक अधिकारों तक सीमित है।"},
  {"id":"polity-judiciary-28","question":"How many of these statements about removing a Supreme Court judge are correct? I. The motion must be passed in each House by a majority of its total membership and two-thirds of the members present and voting. II. The notice must be signed by 100 Lok Sabha members or 50 Rajya Sabha members. III. The inquiry committee has a Supreme Court judge, a High Court Chief Justice and a distinguished jurist. IV. No Supreme Court judge has been removed so far.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct under Article 124(4) and the Judges (Inquiry) Act, 1968. The motion against Justice V. Ramaswami (1993) failed in the Lok Sabha, so no judge has actually been removed.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय के न्यायाधीश को हटाने के संबंध में इनमें से कितने कथन सही हैं? I. प्रस्ताव प्रत्येक सदन में उसकी कुल सदस्य संख्या के बहुमत और उपस्थित तथा मतदान करने वाले सदस्यों के दो-तिहाई बहुमत से पारित होना चाहिए। II. नोटिस पर लोकसभा के 100 या राज्यसभा के 50 सदस्यों के हस्ताक्षर होने चाहिए। III. जांच समिति में सर्वोच्च न्यायालय का एक न्यायाधीश, एक उच्च न्यायालय का मुख्य न्यायाधीश और एक प्रतिष्ठित विधिवेत्ता होता है। IV. आज तक सर्वोच्च न्यायालय के किसी न्यायाधीश को हटाया नहीं गया है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"अनुच्छेद 124(4) और न्यायाधीश (जांच) अधिनियम, 1968 के अंतर्गत सभी चार कथन सही हैं। न्यायमूर्ति वी. रामास्वामी (1993) के विरुद्ध प्रस्ताव लोकसभा में विफल रहा, इसलिए वास्तव में किसी न्यायाधीश को हटाया नहीं गया है।"},
  {"id":"polity-judiciary-29","question":"Which of these disputes is NOT within the Supreme Court's original jurisdiction under Article 131?","options":["Between two or more States","Between the Government of India and one or more States","Between the Centre and some States on one side and other States on the other","An inter-State river water dispute that Parliament has excluded by law"],"answer":3,"explanation":"Under Article 262 Parliament can exclude the jurisdiction of all courts over inter-State river water disputes, and it did so in the Inter-State River Water Disputes Act, 1956. Such disputes go to tribunals instead.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सा विवाद अनुच्छेद 131 के अंतर्गत सर्वोच्च न्यायालय के मूल क्षेत्राधिकार में नहीं आता?","optionsHi":["दो या अधिक राज्यों के बीच","भारत सरकार और एक या अधिक राज्यों के बीच","केंद्र और कुछ राज्यों के एक ओर तथा अन्य राज्यों के दूसरी ओर होने वाला","अंतर-राज्यीय नदी जल विवाद जिसे संसद ने कानून द्वारा अपवर्जित कर दिया हो"],"explanationHi":"अनुच्छेद 262 के अंतर्गत संसद अंतर-राज्यीय नदी जल विवादों पर सभी न्यायालयों का क्षेत्राधिकार अपवर्जित कर सकती है, और उसने अंतर-राज्यीय नदी जल विवाद अधिनियम, 1956 में ऐसा किया। ऐसे विवाद अधिकरणों के पास जाते हैं।"},
  {"id":"polity-judiciary-30","question":"How many of these statements about the advisory jurisdiction are correct? I. Under Article 143(1) the Supreme Court may decline to give an opinion. II. Under Article 143(2), on pre-Constitution treaties, the Court may decline to give its opinion. III. The opinion binds the President. IV. A reference must be heard by a bench of at least seven judges.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct; the Court declined the Ayodhya reference in 1994. Under Article 143(2) the Court must give its opinion, the opinion does not bind the President, and Article 145(3) requires at least five judges, not seven.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"परामर्शी क्षेत्राधिकार के संबंध में इनमें से कितने कथन सही हैं? I. अनुच्छेद 143(1) के अंतर्गत सर्वोच्च न्यायालय राय देने से इनकार कर सकता है। II. अनुच्छेद 143(2) के अंतर्गत, संविधान-पूर्व संधियों के मामले में, न्यायालय अपनी राय देने से इनकार कर सकता है। III. राय राष्ट्रपति पर बाध्यकारी होती है। IV. संदर्भ की सुनवाई कम से कम सात न्यायाधीशों की पीठ द्वारा होनी चाहिए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है; न्यायालय ने 1994 में अयोध्या संदर्भ पर राय देने से इनकार कर दिया था। अनुच्छेद 143(2) के अंतर्गत न्यायालय को राय देनी ही होती है, राय राष्ट्रपति पर बाध्यकारी नहीं होती, और अनुच्छेद 145(3) में कम से कम पांच न्यायाधीश चाहिए, सात नहीं।"},
  {"id":"polity-judiciary-31","question":"Arrange these in time order: 1. The collegium is widened to the CJI plus four senior-most judges. 2. “Consultation” is held not to mean “concurrence”, giving the executive primacy. 3. The 99th Amendment is struck down. 4. Primacy of the judiciary, with a collegium of the CJI and two senior-most judges.","options":["2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1","2, 4, 1, 3"],"answer":3,"explanation":"First Judges case 1981 (2), Second Judges case 1993 (4), Third Judges case 1998 (1), NJAC judgment 2015 (3).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन्हें कालक्रम में व्यवस्थित कीजिए: 1. कॉलेजियम का विस्तार कर उसमें CJI और चार वरिष्ठतम न्यायाधीश रखे गए। 2. ‘परामर्श’ का अर्थ ‘सहमति’ नहीं माना गया, जिससे कार्यपालिका को प्राथमिकता मिली। 3. 99वां संशोधन रद्द किया गया। 4. न्यायपालिका की प्राथमिकता, जिसमें कॉलेजियम में CJI और दो वरिष्ठतम न्यायाधीश थे।","optionsHi":["2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1","2, 4, 1, 3"],"explanationHi":"प्रथम न्यायाधीश मामला 1981 (2), द्वितीय न्यायाधीश मामला 1993 (4), तृतीय न्यायाधीश मामला 1998 (1), NJAC निर्णय 2015 (3)।"},
  {"id":"polity-judiciary-32","question":"How many of these statements about High Courts are correct? I. A High Court judge is appointed by the President after consulting the CJI, the Governor and the Chief Justice of that High Court. II. A High Court judge resigns by writing to the Governor. III. A retired permanent High Court judge cannot plead before the High Court where they served, but can plead in the Supreme Court and other High Courts. IV. The Constitution fixes the number of judges of each High Court.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I (Article 217) and III (Article 220) are correct. A High Court judge resigns to the President. The President fixes each High Court's strength; the Constitution does not.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालयों के संबंध में इनमें से कितने कथन सही हैं? I. उच्च न्यायालय के न्यायाधीश की नियुक्ति राष्ट्रपति, CJI, राज्यपाल और उस उच्च न्यायालय के मुख्य न्यायाधीश से परामर्श के बाद करता है। II. उच्च न्यायालय का न्यायाधीश राज्यपाल को लिखकर त्यागपत्र देता है। III. उच्च न्यायालय का सेवानिवृत्त स्थायी न्यायाधीश जिस उच्च न्यायालय में सेवा दी हो उसमें वकालत नहीं कर सकता, किंतु सर्वोच्च न्यायालय और अन्य उच्च न्यायालयों में कर सकता है। IV. संविधान प्रत्येक उच्च न्यायालय के न्यायाधीशों की संख्या तय करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I (अनुच्छेद 217) और III (अनुच्छेद 220) सही हैं। उच्च न्यायालय का न्यायाधीश राष्ट्रपति को त्यागपत्र देता है। प्रत्येक उच्च न्यायालय की संख्या राष्ट्रपति तय करता है; संविधान नहीं।"},
  {"id":"polity-judiciary-33","question":"How many of these statements about Public Interest Litigation are correct? I. PIL relaxes the traditional rule that only an affected person can approach the court. II. PIL can be filed only in the Supreme Court. III. A PIL can be filed only by a person whose own right has been violated.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I is correct. PILs can be filed in High Courts under Article 226 as well. Any public-spirited person can file one, and courts have even treated letters as petitions.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जनहित याचिका के संबंध में इनमें से कितने कथन सही हैं? I. जनहित याचिका इस पारंपरिक नियम को शिथिल करती है कि केवल प्रभावित व्यक्ति ही न्यायालय जा सकता है। II. जनहित याचिका केवल सर्वोच्च न्यायालय में दायर की जा सकती है। III. जनहित याचिका केवल वही व्यक्ति दायर कर सकता है जिसके अपने अधिकार का उल्लंघन हुआ हो।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I सही है। जनहित याचिकाएं अनुच्छेद 226 के अंतर्गत उच्च न्यायालयों में भी दायर की जा सकती हैं। कोई भी जनहितैषी व्यक्ति इसे दायर कर सकता है, और न्यायालयों ने पत्रों को भी याचिका माना है।"},
  {"id":"polity-judiciary-34","question":"Which pair of Article and subject is NOT correctly matched?","options":["Article 227 — Appointment of district judges","Article 215 — High Court as a court of record","Article 129 — Supreme Court as a court of record","Article 235 — High Court's control over subordinate courts"],"answer":0,"explanation":"Article 227 gives High Courts superintendence over all courts and tribunals in their territory. District judges are appointed under Article 233.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद और विषय का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["अनुच्छेद 227 — जिला न्यायाधीशों की नियुक्ति","अनुच्छेद 215 — अभिलेख न्यायालय के रूप में उच्च न्यायालय","अनुच्छेद 129 — अभिलेख न्यायालय के रूप में सर्वोच्च न्यायालय","अनुच्छेद 235 — अधीनस्थ न्यायालयों पर उच्च न्यायालय का नियंत्रण"],"explanationHi":"अनुच्छेद 227 उच्च न्यायालयों को अपने क्षेत्र के सभी न्यायालयों और अधिकरणों पर अधीक्षण की शक्ति देता है। जिला न्यायाधीशों की नियुक्ति अनुच्छेद 233 के अंतर्गत होती है।"},
  {"id":"polity-judiciary-35","question":"Under the collegium system set out in 1998, appointments to the High Courts are recommended (on the Supreme Court side) by the CJI and:","options":["the four senior-most Supreme Court judges","the Law Minister","the two senior-most Supreme Court judges","the Chief Justice of that High Court alone"],"answer":2,"explanation":"For High Court judges, the Supreme Court collegium is the CJI and the two senior-most puisne judges. The High Court's own collegium starts the proposal. The CJI plus four is the collegium for Supreme Court appointments.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1998 में निर्धारित कॉलेजियम प्रणाली के अंतर्गत, उच्च न्यायालयों में नियुक्तियों की सिफारिश (सर्वोच्च न्यायालय की ओर से) CJI और कौन करते हैं?","optionsHi":["सर्वोच्च न्यायालय के चार वरिष्ठतम न्यायाधीश","विधि मंत्री","सर्वोच्च न्यायालय के दो वरिष्ठतम न्यायाधीश","केवल उस उच्च न्यायालय के मुख्य न्यायाधीश"],"explanationHi":"उच्च न्यायालय के न्यायाधीशों के लिए सर्वोच्च न्यायालय का कॉलेजियम CJI और दो वरिष्ठतम अन्य न्यायाधीश होते हैं। प्रस्ताव उच्च न्यायालय का अपना कॉलेजियम शुरू करता है। CJI और चार न्यायाधीश सर्वोच्च न्यायालय में नियुक्तियों के लिए कॉलेजियम हैं।"},
  {"id":"polity-judiciary-36","question":"How many of these statements about judicial review are correct? I. The words “judicial review” do not appear in the Constitution. II. Articles 13, 32 and 226 are among its sources. III. Laws placed in the Ninth Schedule after 24 April 1973 can be tested against the basic structure. IV. Judicial review is part of the basic structure.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. I. R. Coelho (2007) used the Kesavananda date of 24 April 1973 for Ninth Schedule laws. Minerva Mills and L. Chandra Kumar treated judicial review as part of the basic structure.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"न्यायिक पुनरावलोकन के संबंध में इनमें से कितने कथन सही हैं? I. ‘न्यायिक पुनरावलोकन’ शब्द संविधान में नहीं आते। II. अनुच्छेद 13, 32 और 226 इसके स्रोतों में हैं। III. 24 अप्रैल 1973 के बाद नौवीं अनुसूची में रखे गए कानूनों की जांच मूल ढांचे के आधार पर की जा सकती है। IV. न्यायिक पुनरावलोकन मूल ढांचे का हिस्सा है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। आई. आर. कोएल्हो (2007) में नौवीं अनुसूची के कानूनों के लिए केशवानंद की तिथि 24 अप्रैल 1973 अपनाई गई। मिनर्वा मिल्स और एल. चंद्र कुमार में न्यायिक पुनरावलोकन को मूल ढांचे का हिस्सा माना गया।"},
  {"id":"polity-judiciary-37","question":"Assertion (A): A curative petition can be filed even after a review petition has been dismissed. Reason (R): Article 141 gives the Supreme Court power to pass any order needed for complete justice.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true (Rupa Ashok Hurra, 2002, relying on Articles 129 and 142). R is false: the “complete justice” power is in Article 142, while Article 141 makes the Court's rulings binding.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उपचारात्मक याचिका पुनर्विचार याचिका खारिज होने के बाद भी दायर की जा सकती है। कारण (R): अनुच्छेद 141 सर्वोच्च न्यायालय को पूर्ण न्याय के लिए आवश्यक कोई भी आदेश पारित करने की शक्ति देता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं किंतु R, A की सही व्याख्या नहीं है","A सही है किंतु R गलत है","A गलत है किंतु R सही है"],"explanationHi":"A सही है (रूपा अशोक हुरा, 2002, जो अनुच्छेद 129 और 142 पर आधारित है)। R गलत है: ‘पूर्ण न्याय’ की शक्ति अनुच्छेद 142 में है, जबकि अनुच्छेद 141 न्यायालय के निर्णयों को बाध्यकारी बनाता है।"},
  {"id":"polity-judiciary-38","question":"How many of these statements about tribunals are correct? I. Under Article 323A, only Parliament can set up administrative tribunals. II. Under Article 323B, both Parliament and State legislatures can set up tribunals for listed matters such as taxation and land reforms. III. A tribunal under Article 323A can completely shut out the High Courts. IV. The Central Administrative Tribunal was set up under a 1985 Act.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong since L. Chandra Kumar (1997): tribunal decisions remain open to challenge before a High Court division bench.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अधिकरणों के संबंध में इनमें से कितने कथन सही हैं? I. अनुच्छेद 323A के अंतर्गत केवल संसद प्रशासनिक अधिकरण स्थापित कर सकती है। II. अनुच्छेद 323B के अंतर्गत संसद और राज्य विधानमंडल दोनों कराधान और भूमि सुधार जैसे सूचीबद्ध विषयों के लिए अधिकरण स्थापित कर सकते हैं। III. अनुच्छेद 323A के अंतर्गत बना अधिकरण उच्च न्यायालयों को पूरी तरह बाहर कर सकता है। IV. केंद्रीय प्रशासनिक अधिकरण की स्थापना 1985 के अधिनियम के अंतर्गत हुई।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। III एल. चंद्र कुमार (1997) के बाद गलत है: अधिकरण के निर्णयों को उच्च न्यायालय की खंडपीठ के समक्ष चुनौती दी जा सकती है।"},
  {"id":"polity-judiciary-39","question":"Under Article 130, the Supreme Court may sit at a place other than Delhi if this is decided by:","options":["The President, on the advice of the Union Cabinet","The full court of the Supreme Court by majority","Parliament, by a law made for the purpose","The CJI, with the approval of the President"],"answer":3,"explanation":"Article 130 says the Supreme Court sits in Delhi or anywhere else the Chief Justice of India appoints with the President's approval. Parliament plays no part in this.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 130 के अंतर्गत, सर्वोच्च न्यायालय दिल्ली के अतिरिक्त किसी अन्य स्थान पर बैठ सकता है यदि यह निर्णय किसके द्वारा लिया जाए?","optionsHi":["राष्ट्रपति, केंद्रीय मंत्रिमंडल की सलाह पर","सर्वोच्च न्यायालय की पूर्ण पीठ, बहुमत से","संसद, इस प्रयोजन के लिए बनाए गए कानून द्वारा","CJI, राष्ट्रपति की स्वीकृति से"],"explanationHi":"अनुच्छेद 130 के अनुसार सर्वोच्च न्यायालय दिल्ली में या किसी अन्य स्थान पर बैठता है जिसे भारत का मुख्य न्यायाधीश राष्ट्रपति की स्वीकृति से नियुक्त करे। इसमें संसद की कोई भूमिका नहीं है।"},
  {"id":"polity-judiciary-40","question":"How many of these statements are correct? I. An acting Chief Justice of India is appointed by the President. II. A retired Supreme Court judge can be asked to sit by the CJI with the previous consent of the President. III. A retired High Court judge can be asked to sit in that High Court by its Chief Justice with the previous consent of the Governor. IV. Additional judges of a High Court can be appointed for up to five years.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I (Article 126) and II (Article 128) are correct. III is wrong: Article 224A needs the previous consent of the President, not the Governor. IV is wrong: additional judges are appointed for up to two years.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. कार्यवाहक भारत के मुख्य न्यायाधीश की नियुक्ति राष्ट्रपति करता है। II. सर्वोच्च न्यायालय के सेवानिवृत्त न्यायाधीश को CJI राष्ट्रपति की पूर्व सहमति से बैठने के लिए कह सकता है। III. उच्च न्यायालय के सेवानिवृत्त न्यायाधीश को उस उच्च न्यायालय का मुख्य न्यायाधीश राज्यपाल की पूर्व सहमति से बैठने के लिए कह सकता है। IV. उच्च न्यायालय के अतिरिक्त न्यायाधीशों की नियुक्ति अधिकतम पांच वर्ष के लिए की जा सकती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I (अनुच्छेद 126) और II (अनुच्छेद 128) सही हैं। III गलत है: अनुच्छेद 224A में राज्यपाल की नहीं, राष्ट्रपति की पूर्व सहमति चाहिए। IV गलत है: अतिरिक्त न्यायाधीशों की नियुक्ति अधिकतम दो वर्ष के लिए होती है।"},
  {"id":"polity-judiciary-41","question":"Judges of the Supreme Court of India are appointed by the:","options":["Chief Justice of India","President","Prime Minister","Parliament"],"answer":1,"explanation":"Under Article 124(2) every Supreme Court judge is appointed by the President by warrant under his hand and seal; the collegium only recommends.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"भारत के सर्वोच्च न्यायालय के न्यायाधीशों की नियुक्ति कौन करता है?","optionsHi":["भारत के मुख्य न्यायाधीश","राष्ट्रपति","प्रधानमंत्री","संसद"],"explanationHi":"अनुच्छेद 124(2) के अंतर्गत सर्वोच्च न्यायालय के प्रत्येक न्यायाधीश की नियुक्ति राष्ट्रपति अपने हस्ताक्षर और मुहर सहित अधिपत्र द्वारा करता है; कॉलेजियम केवल सिफारिश करता है।"},
  {"id":"polity-judiciary-42","question":"The Chief Justice of a High Court is appointed by the:","options":["Governor of the State","Chief Minister","Chief Justice of India","President"],"answer":3,"explanation":"Article 217(1) says High Court judges, including the Chief Justice, are appointed by the President after consulting the CJI and the Governor. The Governor only administers the oath.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"उच्च न्यायालय के मुख्य न्यायाधीश की नियुक्ति कौन करता है?","optionsHi":["राज्य का राज्यपाल","मुख्यमंत्री","भारत के मुख्य न्यायाधीश","राष्ट्रपति"],"explanationHi":"अनुच्छेद 217(1) के अनुसार मुख्य न्यायाधीश सहित उच्च न्यायालय के न्यायाधीशों की नियुक्ति राष्ट्रपति, CJI और राज्यपाल से परामर्श के बाद करता है। राज्यपाल केवल शपथ दिलाता है।"},
  {"id":"polity-judiciary-43","question":"Who was the first Chief Justice of India?","options":["H. J. Kania","M. Patanjali Sastri","Mehr Chand Mahajan","B. K. Mukherjea"],"answer":0,"explanation":"Harilal J. Kania was the first CJI (1950–51). Patanjali Sastri, Mahajan and Mukherjea were the second, third and fourth.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भारत के प्रथम मुख्य न्यायाधीश कौन थे?","optionsHi":["एच. जे. कानिया","एम. पतंजलि शास्त्री","मेहरचंद महाजन","बी. के. मुखर्जी"],"explanationHi":"हरिलाल जे. कानिया भारत के प्रथम CJI (1950–51) थे। पतंजलि शास्त्री, महाजन और मुखर्जी क्रमशः दूसरे, तीसरे और चौथे CJI थे।"},
  {"id":"polity-judiciary-44","question":"District judges in a State are appointed by the:","options":["Chief Justice of the High Court acting alone","President, on the advice of the State Government","Governor, in consultation with the High Court","State Public Service Commission, after an exam"],"answer":2,"explanation":"Article 233 says appointments, postings and promotions of district judges are made by the Governor in consultation with the High Court of that State.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"किसी राज्य में जिला न्यायाधीशों की नियुक्ति कौन करता है?","optionsHi":["उच्च न्यायालय के मुख्य न्यायाधीश अकेले","राष्ट्रपति, राज्य सरकार की सलाह पर","राज्यपाल, उच्च न्यायालय के परामर्श से","राज्य लोक सेवा आयोग, परीक्षा के बाद"],"explanationHi":"अनुच्छेद 233 के अनुसार जिला न्यायाधीशों की नियुक्ति, पदस्थापना और पदोन्नति राज्यपाल उस राज्य के उच्च न्यायालय के परामर्श से करता है।"},
  {"id":"polity-judiciary-45","question":"Which is the oldest High Court in India, established in July 1862?","options":["Bombay High Court","Madras High Court","Allahabad High Court","Calcutta High Court"],"answer":3,"explanation":"The Calcutta High Court, set up under the Indian High Courts Act, 1861, began on 1 July 1862, slightly ahead of Bombay and Madras (August 1862). Allahabad came in 1866.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"जुलाई 1862 में स्थापित भारत का सबसे पुराना उच्च न्यायालय कौन-सा है?","optionsHi":["बंबई उच्च न्यायालय","मद्रास उच्च न्यायालय","इलाहाबाद उच्च न्यायालय","कलकत्ता उच्च न्यायालय"],"explanationHi":"भारतीय उच्च न्यायालय अधिनियम, 1861 के अंतर्गत स्थापित कलकत्ता उच्च न्यायालय ने 1 जुलाई 1862 को कार्य शुरू किया, जो बंबई और मद्रास (अगस्त 1862) से थोड़ा पहले था। इलाहाबाद 1866 में आया।"},
  {"id":"polity-judiciary-46","question":"Which writ is issued by a higher court to stop a lower court or tribunal from going beyond its jurisdiction in a case still pending before it?","options":["Certiorari","Prohibition","Mandamus","Quo warranto"],"answer":1,"explanation":"Prohibition is preventive and issued while proceedings are pending. Certiorari is curative, quashing an order already passed.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL · State PSC","questionHi":"कौन-सी रिट उच्च न्यायालय द्वारा किसी अधीनस्थ न्यायालय या अधिकरण को, उसके समक्ष लंबित मामले में, अपने क्षेत्राधिकार से बाहर जाने से रोकने के लिए जारी की जाती है?","optionsHi":["उत्प्रेषण","प्रतिषेध","परमादेश","अधिकार पृच्छा"],"explanationHi":"प्रतिषेध निवारक है और कार्यवाही लंबित रहते हुए जारी होती है। उत्प्रेषण सुधारात्मक है, जो पहले ही पारित आदेश को रद्द करता है।"},
  {"id":"polity-judiciary-47","question":"Which writ is used to quash an order already passed by a lower court or tribunal acting without or in excess of jurisdiction?","options":["Prohibition","Habeas corpus","Certiorari","Mandamus"],"answer":2,"explanation":"Certiorari (‘to be certified’) brings up the record and quashes the order once it is passed, while prohibition acts before the decision.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL · State PSC","questionHi":"किसी अधीनस्थ न्यायालय या अधिकरण द्वारा क्षेत्राधिकार के बिना या उससे अधिक जाकर पारित आदेश को रद्द करने के लिए कौन-सी रिट प्रयुक्त होती है?","optionsHi":["प्रतिषेध","बंदी प्रत्यक्षीकरण","उत्प्रेषण","परमादेश"],"explanationHi":"उत्प्रेषण (‘प्रमाणित किया जाना’) अभिलेख मंगवाता है और आदेश पारित होने के बाद उसे रद्द करता है, जबकि प्रतिषेध निर्णय से पहले कार्य करता है।"},
  {"id":"polity-judiciary-48","question":"Which Article says that there shall be a High Court for each State?","options":["Article 124","Article 214","Article 226","Article 231"],"answer":1,"explanation":"Article 214 provides a High Court for each State. Article 231 lets Parliament set up a common High Court for two or more States; Article 226 is writ jurisdiction.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कौन-सा अनुच्छेद कहता है कि प्रत्येक राज्य के लिए एक उच्च न्यायालय होगा?","optionsHi":["अनुच्छेद 124","अनुच्छेद 214","अनुच्छेद 226","अनुच्छेद 231"],"explanationHi":"अनुच्छेद 214 प्रत्येक राज्य के लिए एक उच्च न्यायालय का प्रावधान करता है। अनुच्छेद 231 संसद को दो या अधिक राज्यों के लिए सामान्य उच्च न्यायालय बनाने देता है; अनुच्छेद 226 रिट क्षेत्राधिकार है।"},
  {"id":"polity-judiciary-49","question":"Lok Adalats were given statutory status by the:","options":["Legal Services Authorities Act, 1987","Code of Civil Procedure (Amendment) Act, 1999","Gram Nyayalayas Act, 2008","Arbitration and Conciliation Act, 1996"],"answer":0,"explanation":"The Legal Services Authorities Act, 1987 (in force from 1995) gave Lok Adalats statutory backing and made their awards final and binding.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"लोक अदालतों को वैधानिक दर्जा किसके द्वारा दिया गया?","optionsHi":["विधिक सेवा प्राधिकरण अधिनियम, 1987","सिविल प्रक्रिया संहिता (संशोधन) अधिनियम, 1999","ग्राम न्यायालय अधिनियम, 2008","मध्यस्थता और सुलह अधिनियम, 1996"],"explanationHi":"विधिक सेवा प्राधिकरण अधिनियम, 1987 (1995 से लागू) ने लोक अदालतों को वैधानिक आधार दिया और उनके अधिनिर्णयों को अंतिम और बाध्यकारी बनाया।"},
  {"id":"polity-judiciary-50","question":"Equal justice and free legal aid were added as a Directive Principle in Article 39A by the:","options":["24th Amendment","42nd Amendment","44th Amendment","73rd Amendment"],"answer":1,"explanation":"Article 39A was inserted by the 42nd Amendment (1976). It underpins the legal aid system under the 1987 Act.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"समान न्याय और निःशुल्क विधिक सहायता को अनुच्छेद 39A में नीति निदेशक तत्व के रूप में किस संशोधन द्वारा जोड़ा गया?","optionsHi":["24वां संशोधन","42वां संशोधन","44वां संशोधन","73वां संशोधन"],"explanationHi":"अनुच्छेद 39A 42वें संशोधन (1976) द्वारा जोड़ा गया। यह 1987 के अधिनियम के अंतर्गत विधिक सहायता प्रणाली का आधार है।"},
  {"id":"polity-judiciary-51","question":"The Supreme Court's power to review any judgment or order made by it comes from:","options":["Article 136","Article 137","Article 141","Article 143"],"answer":1,"explanation":"Article 137 lets the Supreme Court review its own judgments, subject to law and its rules. Article 136 is special leave and Article 141 makes its law binding on other courts.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"सर्वोच्च न्यायालय को अपने किसी भी निर्णय या आदेश का पुनर्विलोकन करने की शक्ति किससे मिलती है?","optionsHi":["अनुच्छेद 136","अनुच्छेद 137","अनुच्छेद 141","अनुच्छेद 143"],"explanationHi":"अनुच्छेद 137 सर्वोच्च न्यायालय को कानून और अपने नियमों के अधीन रहते हुए अपने निर्णयों का पुनर्विलोकन करने देता है। अनुच्छेद 136 विशेष अनुमति है और अनुच्छेद 141 उसके कानून को अन्य न्यायालयों पर बाध्यकारी बनाता है।"},
  {"id":"polity-judiciary-52","question":"An appeal lies to the Supreme Court as of right in a criminal case where a High Court has reversed an acquittal and sentenced the accused to death, under:","options":["Article 132","Article 133","Article 134","Article 136"],"answer":2,"explanation":"Article 134(1)(a) gives a right of appeal in such cases. Article 132 is constitutional questions and Article 133 civil appeals.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"किसी आपराधिक मामले में जहां उच्च न्यायालय ने दोषमुक्ति को पलटकर अभियुक्त को मृत्युदंड दिया हो, वहां सर्वोच्च न्यायालय में अपील अधिकार के रूप में किसके अंतर्गत होती है?","optionsHi":["अनुच्छेद 132","अनुच्छेद 133","अनुच्छेद 134","अनुच्छेद 136"],"explanationHi":"अनुच्छेद 134(1)(a) ऐसे मामलों में अपील का अधिकार देता है। अनुच्छेद 132 संवैधानिक प्रश्नों से और अनुच्छेद 133 दीवानी अपीलों से संबंधित है।"},
  {"id":"polity-judiciary-53","question":"Who is the Patron-in-Chief of the National Legal Services Authority (NALSA)?","options":["The President of India","The Union Law Minister","The Chief Justice of India","The Attorney General for India"],"answer":2,"explanation":"Under the 1987 Act the CJI is Patron-in-Chief of NALSA and the senior-most Supreme Court judge after him is its Executive Chairman.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"राष्ट्रीय विधिक सेवा प्राधिकरण (NALSA) का मुख्य संरक्षक कौन होता है?","optionsHi":["भारत का राष्ट्रपति","केंद्रीय विधि मंत्री","भारत का मुख्य न्यायाधीश","भारत का महान्यायवादी"],"explanationHi":"1987 के अधिनियम के अंतर्गत CJI NALSA के मुख्य संरक्षक होते हैं और उनके बाद सर्वोच्च न्यायालय के वरिष्ठतम न्यायाधीश उसके कार्यकारी अध्यक्ष होते हैं।"},
  {"id":"polity-judiciary-54","question":"Gram Nyayalayas, village-level courts for quick and cheap justice, were provided for by an Act passed in:","options":["1987","1996","2008","2013"],"answer":2,"explanation":"The Gram Nyayalayas Act, 2008 (in force from October 2009) provides for these mobile courts at the intermediate panchayat level.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"त्वरित और सस्ते न्याय के लिए ग्राम स्तर के न्यायालय, ग्राम न्यायालय, का प्रावधान किस वर्ष पारित अधिनियम में किया गया?","optionsHi":["1987","1996","2008","2013"],"explanationHi":"ग्राम न्यायालय अधिनियम, 2008 (अक्टूबर 2009 से लागू) मध्यवर्ती पंचायत स्तर पर इन चलित न्यायालयों का प्रावधान करता है।"},
  {"id":"polity-judiciary-55","question":"The pension of a retired High Court judge is charged on the:","options":["Consolidated Fund of the State","Contingency Fund of the State","Consolidated Fund of India","Public Account of India"],"answer":2,"explanation":"A High Court judge's salary is charged on the Consolidated Fund of the State (Article 202), but the pension is charged on the Consolidated Fund of India (Article 112(3)(d)(iii)).","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"उच्च न्यायालय के सेवानिवृत्त न्यायाधीश की पेंशन किस पर भारित होती है?","optionsHi":["राज्य की संचित निधि","राज्य की आकस्मिकता निधि","भारत की संचित निधि","भारत का लोक लेखा"],"explanationHi":"उच्च न्यायालय के न्यायाधीश का वेतन राज्य की संचित निधि पर भारित है (अनुच्छेद 202), किंतु पेंशन भारत की संचित निधि पर भारित है (अनुच्छेद 112(3)(d)(iii))।"},
  {"id":"polity-judiciary-56","question":"For criminal contempt of the Supreme Court, a private person can move the Court only with the consent of the:","options":["Registrar General of the Supreme Court","Union Law Minister or Law Secretary","Attorney General or Solicitor General","President, on the Cabinet's advice"],"answer":2,"explanation":"Section 15 of the Contempt of Courts Act, 1971 requires the written consent of the Attorney General or Solicitor General (for a High Court, the Advocate General), unless the Court acts on its own motion.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"सर्वोच्च न्यायालय की आपराधिक अवमानना के लिए कोई निजी व्यक्ति न्यायालय में केवल किसकी सहमति से जा सकता है?","optionsHi":["सर्वोच्च न्यायालय के रजिस्ट्रार जनरल","केंद्रीय विधि मंत्री या विधि सचिव","महान्यायवादी या सॉलिसिटर जनरल","राष्ट्रपति, मंत्रिमंडल की सलाह पर"],"explanationHi":"न्यायालय अवमान अधिनियम, 1971 की धारा 15 के अनुसार महान्यायवादी या सॉलिसिटर जनरल (उच्च न्यायालय के लिए महाधिवक्ता) की लिखित सहमति आवश्यक है, जब तक कि न्यायालय स्वयं संज्ञान न ले।"},
  {"id":"polity-judiciary-57","question":"Which Article says that all civil and judicial authorities in India shall act in aid of the Supreme Court?","options":["Article 141","Article 142","Article 144","Article 145"],"answer":2,"explanation":"Article 144 obliges all authorities to act in aid of the Supreme Court. Article 142 is its power to do complete justice, and Article 145 its rule-making power.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कौन-सा अनुच्छेद कहता है कि भारत के सभी सिविल और न्यायिक प्राधिकारी सर्वोच्च न्यायालय की सहायता में कार्य करेंगे?","optionsHi":["अनुच्छेद 141","अनुच्छेद 142","अनुच्छेद 144","अनुच्छेद 145"],"explanationHi":"अनुच्छेद 144 सभी प्राधिकारियों को सर्वोच्च न्यायालय की सहायता में कार्य करने के लिए बाध्य करता है। अनुच्छेद 142 उसकी पूर्ण न्याय करने की शक्ति है और अनुच्छेद 145 उसकी नियम बनाने की शक्ति है।"},
  {"id":"polity-judiciary-58","question":"The Punjab and Haryana High Court at Chandigarh has jurisdiction over:","options":["Punjab and Haryana, but not Chandigarh","Punjab, Haryana and Himachal Pradesh","Punjab, Haryana and Chandigarh","Punjab, Haryana, Chandigarh and Jammu and Kashmir"],"answer":2,"explanation":"It is a common High Court for two States and one UT. Himachal Pradesh has had its own High Court since 1971.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"चंडीगढ़ स्थित पंजाब और हरियाणा उच्च न्यायालय का क्षेत्राधिकार किन पर है?","optionsHi":["पंजाब और हरियाणा, किंतु चंडीगढ़ पर नहीं","पंजाब, हरियाणा और हिमाचल प्रदेश","पंजाब, हरियाणा और चंडीगढ़","पंजाब, हरियाणा, चंडीगढ़ और जम्मू और कश्मीर"],"explanationHi":"यह दो राज्यों और एक केंद्र शासित प्रदेश का सामान्य उच्च न्यायालय है। हिमाचल प्रदेश का अपना उच्च न्यायालय 1971 से है।"},
  {"id":"polity-judiciary-59","question":"Which High Court has the largest number of States under its jurisdiction?","options":["Bombay High Court","Calcutta High Court","Gauhati High Court","Punjab and Haryana High Court"],"answer":2,"explanation":"The Gauhati High Court covers four States: Assam, Nagaland, Mizoram and Arunachal Pradesh. Bombay covers two States (Maharashtra, Goa) and a UT.","difficulty":"hard","source":"UPSC Prelims · SSC CGL · State PSC","questionHi":"किस उच्च न्यायालय के क्षेत्राधिकार में सबसे अधिक राज्य आते हैं?","optionsHi":["बंबई उच्च न्यायालय","कलकत्ता उच्च न्यायालय","गुवाहाटी उच्च न्यायालय","पंजाब और हरियाणा उच्च न्यायालय"],"explanationHi":"गुवाहाटी उच्च न्यायालय चार राज्यों को कवर करता है: असम, नागालैंड, मिजोरम और अरुणाचल प्रदेश। बंबई दो राज्यों (महाराष्ट्र, गोवा) और एक केंद्र शासित प्रदेश को कवर करता है।"},
  {"id":"polity-judiciary-60","question":"How many High Courts are there in India in 2026?","options":["21","24","25","28"],"answer":2,"explanation":"There are 25 High Courts. Some serve more than one State or UT (Gauhati, Punjab and Haryana, Bombay, and Jammu and Kashmir and Ladakh), so the number is less than the number of States.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"2026 में भारत में कितने उच्च न्यायालय हैं?","optionsHi":["21","24","25","28"],"explanationHi":"25 उच्च न्यायालय हैं। कुछ एक से अधिक राज्य या केंद्र शासित प्रदेश की सेवा करते हैं (गुवाहाटी, पंजाब और हरियाणा, बंबई, तथा जम्मू और कश्मीर और लद्दाख), इसलिए संख्या राज्यों की संख्या से कम है।"},
  {"id":"polity-judiciary-61","question":"An election petition challenging the election of a member of the Lok Sabha is filed, in the first instance, in the:","options":["Supreme Court","Election Commission","High Court","Election tribunal set up by Parliament"],"answer":2,"explanation":"Section 80A of the Representation of the People Act, 1951 gives jurisdiction to the High Court, with appeal to the Supreme Court. Presidential and Vice-Presidential disputes go straight to the Supreme Court.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"लोकसभा के किसी सदस्य के निर्वाचन को चुनौती देने वाली चुनाव याचिका सर्वप्रथम कहां दायर की जाती है?","optionsHi":["सर्वोच्च न्यायालय","निर्वाचन आयोग","उच्च न्यायालय","संसद द्वारा गठित चुनाव अधिकरण"],"explanationHi":"लोक प्रतिनिधित्व अधिनियम, 1951 की धारा 80A उच्च न्यायालय को क्षेत्राधिकार देती है, जिसकी अपील सर्वोच्च न्यायालय में होती है। राष्ट्रपति और उपराष्ट्रपति के विवाद सीधे सर्वोच्च न्यायालय में जाते हैं।"},
  {"id":"polity-judiciary-62","question":"When the office of Chief Justice of a High Court falls vacant, an acting Chief Justice is appointed by the:","options":["Governor","Chief Justice of India","President","Senior-most judge of that High Court, by rotation"],"answer":2,"explanation":"Article 223 lets the President appoint one of the judges of that High Court to perform the duties of Chief Justice.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"जब उच्च न्यायालय के मुख्य न्यायाधीश का पद रिक्त हो, तो कार्यवाहक मुख्य न्यायाधीश की नियुक्ति कौन करता है?","optionsHi":["राज्यपाल","भारत के मुख्य न्यायाधीश","राष्ट्रपति","उस उच्च न्यायालय के वरिष्ठतम न्यायाधीश, बारी-बारी से"],"explanationHi":"अनुच्छेद 223 राष्ट्रपति को उस उच्च न्यायालय के किसी एक न्यायाधीश को मुख्य न्यायाधीश के कर्तव्य निभाने के लिए नियुक्त करने देता है।"},
  {"id":"polity-judiciary-63","question":"A High Court's power of superintendence over all courts and tribunals within its territory (except military tribunals) is given by:","options":["Article 226","Article 227","Article 228","Article 235"],"answer":1,"explanation":"Article 227 confers superintendence. Article 228 is withdrawal of cases involving constitutional questions, and Article 235 is control over subordinate courts.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"उच्च न्यायालय को अपने क्षेत्र के सभी न्यायालयों और अधिकरणों (सैन्य अधिकरणों को छोड़कर) पर अधीक्षण की शक्ति किससे मिलती है?","optionsHi":["अनुच्छेद 226","अनुच्छेद 227","अनुच्छेद 228","अनुच्छेद 235"],"explanationHi":"अनुच्छेद 227 अधीक्षण की शक्ति देता है। अनुच्छेद 228 संवैधानिक प्रश्नों वाले मामलों को अपने पास मंगवाने से और अनुच्छेद 235 अधीनस्थ न्यायालयों पर नियंत्रण से संबंधित है।"},
  {"id":"polity-judiciary-64","question":"Under which Article may Parliament by law give the Supreme Court power to issue writs for purposes other than the enforcement of Fundamental Rights?","options":["Article 32(3)","Article 138","Article 139","Article 226"],"answer":2,"explanation":"Article 139 allows Parliament to widen the Supreme Court's writ power beyond Fundamental Rights. Article 32(3) lets Parliament give other courts power to issue writs within their limits.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किस अनुच्छेद के अंतर्गत संसद कानून द्वारा सर्वोच्च न्यायालय को मौलिक अधिकारों के प्रवर्तन के अतिरिक्त अन्य प्रयोजनों के लिए रिट जारी करने की शक्ति दे सकती है?","optionsHi":["अनुच्छेद 32(3)","अनुच्छेद 138","अनुच्छेद 139","अनुच्छेद 226"],"explanationHi":"अनुच्छेद 139 संसद को सर्वोच्च न्यायालय की रिट शक्ति मौलिक अधिकारों से आगे बढ़ाने देता है। अनुच्छेद 32(3) संसद को अन्य न्यायालयों को उनकी सीमाओं के भीतर रिट जारी करने की शक्ति देने देता है।"},
  {"id":"polity-judiciary-65","question":"Which Article bars courts from questioning the validity of laws on the delimitation of constituencies and says an election can be challenged only by an election petition?","options":["Article 324","Article 326","Article 327","Article 329"],"answer":3,"explanation":"Article 329 bars courts in electoral matters. Article 324 sets up the Election Commission, 326 is adult suffrage and 327 lets Parliament legislate on elections.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कौन-सा अनुच्छेद निर्वाचन क्षेत्रों के परिसीमन संबंधी कानूनों की वैधता पर न्यायालयों को प्रश्न उठाने से रोकता है और कहता है कि चुनाव को केवल चुनाव याचिका द्वारा चुनौती दी जा सकती है?","optionsHi":["अनुच्छेद 324","अनुच्छेद 326","अनुच्छेद 327","अनुच्छेद 329"],"explanationHi":"अनुच्छेद 329 निर्वाचन संबंधी मामलों में न्यायालयों को रोकता है। अनुच्छेद 324 निर्वाचन आयोग की स्थापना करता है, 326 वयस्क मताधिकार है और 327 संसद को चुनावों पर कानून बनाने देता है।"},
  {"id":"polity-judiciary-66","question":"Under Article 139A, the Supreme Court may:","options":["Hear appeals against the orders of courts-martial and military tribunals","Withdraw cases on the same question of law from High Courts to itself","Issue advisory opinions on disputes arising from pre-Constitution treaties","Review the decisions of State Public Service Commissions on recruitment"],"answer":1,"explanation":"Article 139A, added by the 42nd Amendment, lets the Supreme Court withdraw such cases and decide them, and transfer cases between High Courts.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 139A के अंतर्गत सर्वोच्च न्यायालय क्या कर सकता है?","optionsHi":["कोर्ट-मार्शल और सैन्य अधिकरणों के आदेशों के विरुद्ध अपीलें सुनना","एक ही विधि-प्रश्न वाले मामलों को उच्च न्यायालयों से अपने पास मंगवाना","संविधान-पूर्व संधियों से उत्पन्न विवादों पर परामर्शी राय देना","राज्य लोक सेवा आयोगों के भर्ती संबंधी निर्णयों का पुनर्विलोकन करना"],"explanationHi":"42वें संशोधन द्वारा जोड़ा गया अनुच्छेद 139A सर्वोच्च न्यायालय को ऐसे मामले अपने पास मंगवाकर तय करने और उच्च न्यायालयों के बीच मामले स्थानांतरित करने देता है।"},
  {"id":"polity-judiciary-67","question":"The doctrine of ‘prospective overruling’ was first applied by the Supreme Court in:","options":["A. K. Gopalan case","Golaknath case","Kesavananda Bharati case","Minerva Mills case"],"answer":1,"explanation":"In Golaknath (1967) the Court held that Parliament could not amend Fundamental Rights but applied the ruling only to the future, so earlier amendments stood.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"‘भावी विनिर्णय’ (prospective overruling) का सिद्धांत सर्वोच्च न्यायालय ने सबसे पहले किस मामले में लागू किया?","optionsHi":["ए. के. गोपालन मामला","गोलकनाथ मामला","केशवानंद भारती मामला","मिनर्वा मिल्स मामला"],"explanationHi":"गोलकनाथ (1967) में न्यायालय ने माना कि संसद मौलिक अधिकारों में संशोधन नहीं कर सकती, किंतु इस निर्णय को केवल भविष्य के लिए लागू किया, इसलिए पहले के संशोधन बने रहे।"},
  {"id":"polity-judiciary-68","question":"Match the Union Territory with the High Court that has jurisdiction over it: A. Lakshadweep B. Andaman and Nicobar Islands C. Puducherry D. Dadra and Nagar Haveli and Daman and Diu — 1. Bombay 2. Madras 3. Calcutta 4. Kerala","options":["A-3, B-4, C-2, D-1","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Lakshadweep falls under the Kerala High Court, Andaman and Nicobar under Calcutta, Puducherry under Madras, and Dadra and Nagar Haveli and Daman and Diu under Bombay.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL · State PSC","questionHi":"केंद्र शासित प्रदेश का मिलान उस उच्च न्यायालय से कीजिए जिसका उस पर क्षेत्राधिकार है: A. लक्षद्वीप B. अंडमान और निकोबार द्वीप समूह C. पुदुचेरी D. दादरा और नगर हवेली तथा दमन और दीव — 1. बंबई 2. मद्रास 3. कलकत्ता 4. केरल","optionsHi":["A-3, B-4, C-2, D-1","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"लक्षद्वीप केरल उच्च न्यायालय के अंतर्गत, अंडमान और निकोबार कलकत्ता के अंतर्गत, पुदुचेरी मद्रास के अंतर्गत, तथा दादरा और नगर हवेली और दमन और दीव बंबई के अंतर्गत आते हैं।"},
  {"id":"polity-judiciary-69","question":"How many of these statements about writs are correct? I. Habeas corpus can be issued against a private individual. II. Mandamus can be issued against the President or a Governor. III. Quo warranto can be sought by any person, not only an aggrieved one. IV. Prohibition can be issued against purely administrative authorities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: mandamus cannot issue against the President or a Governor (Article 361). IV is wrong: prohibition lies only against judicial and quasi-judicial bodies.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"रिटों के संबंध में इनमें से कितने कथन सही हैं? I. बंदी प्रत्यक्षीकरण किसी निजी व्यक्ति के विरुद्ध जारी किया जा सकता है। II. परमादेश राष्ट्रपति या राज्यपाल के विरुद्ध जारी किया जा सकता है। III. अधिकार पृच्छा की मांग कोई भी व्यक्ति कर सकता है, केवल पीड़ित नहीं। IV. प्रतिषेध विशुद्ध प्रशासनिक प्राधिकारियों के विरुद्ध जारी किया जा सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: परमादेश राष्ट्रपति या राज्यपाल के विरुद्ध जारी नहीं हो सकता (अनुच्छेद 361)। IV गलत है: प्रतिषेध केवल न्यायिक और अर्ध-न्यायिक निकायों के विरुद्ध जारी होता है।"},
  {"id":"polity-judiciary-70","question":"Assertion (A): The salaries of Supreme Court judges cannot be reduced to their disadvantage after appointment, except during a Financial Emergency. Reason (R): Article 125 provides that the salaries of Supreme Court judges are determined by Parliament by law.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true. A rests on the proviso to Article 125(2) and on Article 360(4), which allows reduction during a Financial Emergency; R (Parliament fixes salaries) does not explain the protection.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): सर्वोच्च न्यायालय के न्यायाधीशों के वेतन में नियुक्ति के बाद उनके प्रतिकूल कमी नहीं की जा सकती, वित्तीय आपातकाल को छोड़कर। कारण (R): अनुच्छेद 125 के अनुसार सर्वोच्च न्यायालय के न्यायाधीशों का वेतन संसद कानून द्वारा निर्धारित करती है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"दोनों सही हैं। A अनुच्छेद 125(2) के परंतुक और अनुच्छेद 360(4) पर आधारित है, जो वित्तीय आपातकाल में कटौती की अनुमति देता है; R (संसद वेतन तय करती है) इस संरक्षण की व्याख्या नहीं करता।"},
  {"id":"polity-judiciary-71","question":"Arrange these Chief Justices of India in the order in which they held office: 1. J. S. Verma 2. Y. V. Chandrachud 3. K. G. Balakrishnan 4. P. N. Bhagwati","options":["2-4-1-3","2-1-4-3","2-4-3-1","4-2-1-3"],"answer":0,"explanation":"Y. V. Chandrachud (1978–85), P. N. Bhagwati (1985–86), J. S. Verma (1997–98), K. G. Balakrishnan (2007–10).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन भारत के मुख्य न्यायाधीशों को उनके कार्यकाल के क्रम में व्यवस्थित कीजिए: 1. जे. एस. वर्मा 2. वाई. वी. चंद्रचूड़ 3. के. जी. बालकृष्णन 4. पी. एन. भगवती","optionsHi":["2-4-1-3","2-1-4-3","2-4-3-1","4-2-1-3"],"explanationHi":"वाई. वी. चंद्रचूड़ (1978–85), पी. एन. भगवती (1985–86), जे. एस. वर्मा (1997–98), के. जी. बालकृष्णन (2007–10)।"},
  {"id":"polity-judiciary-72","question":"Match the writ with the literal meaning of its name: A. Habeas corpus B. Mandamus C. Quo warranto D. Certiorari — 1. By what authority 2. To be certified 3. We command 4. To have the body","options":["A-4, B-3, C-1, D-2","A-4, B-1, C-3, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":0,"explanation":"Habeas corpus means ‘to have the body’, mandamus ‘we command’, quo warranto ‘by what authority’ and certiorari ‘to be certified’ or ‘to be informed’.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"रिट का मिलान उसके नाम के शाब्दिक अर्थ से कीजिए: A. बंदी प्रत्यक्षीकरण B. परमादेश C. अधिकार पृच्छा D. उत्प्रेषण — 1. किस अधिकार से 2. प्रमाणित किया जाना 3. हम आदेश देते हैं 4. शरीर को प्रस्तुत करना","optionsHi":["A-4, B-3, C-1, D-2","A-4, B-1, C-3, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"explanationHi":"बंदी प्रत्यक्षीकरण (Habeas corpus) का अर्थ ‘शरीर को प्रस्तुत करना’, परमादेश (Mandamus) ‘हम आदेश देते हैं’, अधिकार पृच्छा (Quo warranto) ‘किस अधिकार से’ और उत्प्रेषण (Certiorari) ‘प्रमाणित किया जाना’ या ‘सूचित किया जाना’ है।"},
  {"id":"polity-judiciary-73","question":"How many of these statements about the Supreme Court's original jurisdiction are correct? I. A dispute under Article 131 must involve a question on which the existence or extent of a legal right depends. II. Disputes about the election of the President lie in its original jurisdiction. III. Parliament can by law exclude inter-State river water disputes from its jurisdiction. IV. A private citizen can file a suit against a State under Article 131.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I (Article 131), II (Article 71) and III (Article 262(2)) are correct. IV is wrong: Article 131 covers disputes only between the Union and States or between States.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"सर्वोच्च न्यायालय के मूल क्षेत्राधिकार के संबंध में इनमें से कितने कथन सही हैं? I. अनुच्छेद 131 के अंतर्गत विवाद में ऐसा प्रश्न होना चाहिए जिस पर किसी विधिक अधिकार का अस्तित्व या विस्तार निर्भर हो। II. राष्ट्रपति के निर्वाचन संबंधी विवाद उसके मूल क्षेत्राधिकार में आते हैं। III. संसद कानून द्वारा अंतर-राज्यीय नदी जल विवादों को उसके क्षेत्राधिकार से बाहर कर सकती है। IV. कोई निजी नागरिक अनुच्छेद 131 के अंतर्गत किसी राज्य के विरुद्ध वाद दायर कर सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I (अनुच्छेद 131), II (अनुच्छेद 71) और III (अनुच्छेद 262(2)) सही हैं। IV गलत है: अनुच्छेद 131 केवल संघ और राज्यों के बीच या राज्यों के बीच विवादों को कवर करता है।"},
  {"id":"polity-judiciary-74","question":"Which of these is NOT a qualification or condition for appointment as a High Court judge?","options":["Being a citizen of India","Having held judicial office in India for ten years","Having been an advocate of a High Court for ten years","Having reached the age of 35 years"],"answer":3,"explanation":"Article 217(2) asks for citizenship and either ten years in judicial office or ten years as an advocate of a High Court. The Constitution sets no minimum age for judges, only a retirement age of 62.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सी उच्च न्यायालय के न्यायाधीश की नियुक्ति की योग्यता या शर्त नहीं है?","optionsHi":["भारत का नागरिक होना","भारत में दस वर्ष तक न्यायिक पद धारण किया होना","उच्च न्यायालय में दस वर्ष तक अधिवक्ता रहा होना","35 वर्ष की आयु पूरी कर चुका होना"],"explanationHi":"अनुच्छेद 217(2) में नागरिकता और या तो दस वर्ष का न्यायिक पद या उच्च न्यायालय में दस वर्ष की वकालत की अपेक्षा है। संविधान न्यायाधीशों के लिए कोई न्यूनतम आयु तय नहीं करता, केवल सेवानिवृत्ति की आयु 62 वर्ष है।"},
  {"id":"polity-judiciary-75","question":"How many of these statements about Lok Adalats are correct? I. An award of a Lok Adalat is deemed to be a decree of a civil court. II. No appeal lies to any court against such an award. III. Court fee paid in a pending case is refunded when it is settled in a Lok Adalat. IV. Permanent Lok Adalats for public utility services were provided by a 2002 amendment to the 1987 Act.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Section 21 makes the award a decree and final; the court fee is refunded under the Court Fees Act; Chapter VI-A (2002) created Permanent Lok Adalats for public utility services.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"लोक अदालतों के संबंध में इनमें से कितने कथन सही हैं? I. लोक अदालत का अधिनिर्णय सिविल न्यायालय की डिक्री माना जाता है। II. ऐसे अधिनिर्णय के विरुद्ध किसी न्यायालय में अपील नहीं होती। III. लंबित मामले में दिया गया न्यायालय शुल्क लोक अदालत में समझौता होने पर वापस किया जाता है। IV. सार्वजनिक उपयोगिता सेवाओं के लिए स्थायी लोक अदालतों का प्रावधान 1987 के अधिनियम में 2002 के संशोधन द्वारा किया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। धारा 21 अधिनिर्णय को डिक्री और अंतिम बनाती है; न्यायालय शुल्क अधिनियम के अंतर्गत शुल्क वापस किया जाता है; अध्याय VI-A (2002) ने सार्वजनिक उपयोगिता सेवाओं के लिए स्थायी लोक अदालतें बनाईं।"},
  {"id":"polity-judiciary-76","question":"Arrange these Supreme Court judgments in time order: 1. Maneka Gandhi 2. K. S. Puttaswamy (privacy) 3. A. K. Gopalan 4. Minerva Mills","options":["1-3-4-2","3-4-1-2","3-1-4-2","3-1-2-4"],"answer":2,"explanation":"A. K. Gopalan (1950), Maneka Gandhi (1978), Minerva Mills (1980), K. S. Puttaswamy (2017).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"सर्वोच्च न्यायालय के इन निर्णयों को कालक्रम में व्यवस्थित कीजिए: 1. मेनका गांधी 2. के. एस. पुट्टास्वामी (निजता) 3. ए. के. गोपालन 4. मिनर्वा मिल्स","optionsHi":["1-3-4-2","3-4-1-2","3-1-4-2","3-1-2-4"],"explanationHi":"ए. के. गोपालन (1950), मेनका गांधी (1978), मिनर्वा मिल्स (1980), के. एस. पुट्टास्वामी (2017)।"},
  {"id":"polity-judiciary-77","question":"How many of these statements about contempt of court are correct? I. Articles 129 and 215 make the Supreme Court and High Courts courts of record with power to punish contempt of themselves. II. The Contempt of Courts Act, 1971 defines only criminal contempt. III. The Act allows simple imprisonment of up to six months, or a fine of up to ₹2,000, or both. IV. Truth can never be pleaded as a defence in contempt proceedings.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: the Act defines both civil and criminal contempt. IV is wrong: a 2006 amendment allows truth as a defence if it is in the public interest and the plea is bona fide.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"न्यायालय की अवमानना के संबंध में इनमें से कितने कथन सही हैं? I. अनुच्छेद 129 और 215 सर्वोच्च न्यायालय और उच्च न्यायालयों को अभिलेख न्यायालय बनाते हैं, जिन्हें अपनी अवमानना के लिए दंड देने की शक्ति है। II. न्यायालय अवमान अधिनियम, 1971 केवल आपराधिक अवमानना को परिभाषित करता है। III. अधिनियम में अधिकतम छह माह का साधारण कारावास, या ₹2,000 तक का जुर्माना, या दोनों की अनुमति है। IV. अवमानना की कार्यवाही में सत्य को बचाव के रूप में कभी प्रस्तुत नहीं किया जा सकता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: अधिनियम सिविल और आपराधिक दोनों अवमानना को परिभाषित करता है। IV गलत है: 2006 का संशोधन सत्य को बचाव के रूप में अनुमति देता है, यदि वह जनहित में हो और दलील सद्भावपूर्ण हो।"},
  {"id":"polity-judiciary-78","question":"Assertion (A): The Supreme Court is bound by its own earlier decisions. Reason (R): Under Article 141, the law declared by the Supreme Court is binding on all courts within India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: the Supreme Court can depart from its earlier rulings (Bengal Immunity, 1955); a smaller bench is bound by a larger one, but the Court as a whole is not bound. R is true, but ‘all courts’ means courts other than the Supreme Court itself.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): सर्वोच्च न्यायालय अपने पूर्व निर्णयों से बाध्य है। कारण (R): अनुच्छेद 141 के अंतर्गत सर्वोच्च न्यायालय द्वारा घोषित कानून भारत के भीतर सभी न्यायालयों पर बाध्यकारी है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"A गलत है: सर्वोच्च न्यायालय अपने पूर्व निर्णयों से हट सकता है (बंगाल इम्युनिटी, 1955); छोटी पीठ बड़ी पीठ से बाध्य होती है, किंतु पूरा न्यायालय नहीं। R सही है, किंतु ‘सभी न्यायालय’ का अर्थ स्वयं सर्वोच्च न्यायालय के अतिरिक्त अन्य न्यायालय है।"},
  {"id":"polity-judiciary-79","question":"Match the Article with its subject: A. Article 214 B. Article 217 C. Article 222 D. Article 224 — 1. Transfer of a judge from one High Court to another 2. Additional and acting judges 3. Appointment and conditions of office of a High Court judge 4. High Courts for States","options":["A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2"],"answer":3,"explanation":"Article 214 provides High Courts for States, 217 governs appointment, 222 transfers, and 224 additional and acting judges.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद का मिलान उसके विषय से कीजिए: A. अनुच्छेद 214 B. अनुच्छेद 217 C. अनुच्छेद 222 D. अनुच्छेद 224 — 1. न्यायाधीश का एक उच्च न्यायालय से दूसरे में स्थानांतरण 2. अतिरिक्त और कार्यकारी न्यायाधीश 3. उच्च न्यायालय के न्यायाधीश की नियुक्ति और पद की शर्तें 4. राज्यों के लिए उच्च न्यायालय","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2"],"explanationHi":"अनुच्छेद 214 राज्यों के लिए उच्च न्यायालयों का, 217 नियुक्ति का, 222 स्थानांतरण का, और 224 अतिरिक्त और कार्यकारी न्यायाधीशों का प्रावधान करता है।"},
  {"id":"polity-judiciary-80","question":"How many of these statements about the National Judicial Appointments Commission are correct? I. The 99th Amendment inserted Article 124A to create it. II. It was to have six members: the CJI, two senior-most Supreme Court judges, the Union Law Minister and two eminent persons. III. The Supreme Court struck it down in 2015 by a 4:1 majority. IV. Justice J. Chelameswar was the dissenting judge.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. In the Fourth Judges case (2015) the majority held that the NJAC compromised judicial independence; Justice Chelameswar upheld it.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"राष्ट्रीय न्यायिक नियुक्ति आयोग के संबंध में इनमें से कितने कथन सही हैं? I. 99वें संशोधन ने इसे बनाने के लिए अनुच्छेद 124A जोड़ा। II. इसमें छह सदस्य होने थे: CJI, सर्वोच्च न्यायालय के दो वरिष्ठतम न्यायाधीश, केंद्रीय विधि मंत्री और दो प्रतिष्ठित व्यक्ति। III. सर्वोच्च न्यायालय ने 2015 में इसे 4:1 बहुमत से रद्द किया। IV. न्यायमूर्ति जे. चेलमेश्वर असहमत न्यायाधीश थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। चतुर्थ न्यायाधीश मामले (2015) में बहुमत ने माना कि NJAC न्यायिक स्वतंत्रता से समझौता करता है; न्यायमूर्ति चेलमेश्वर ने इसे वैध ठहराया।"},
  {"id":"polity-judiciary-81","question":"How many of these statements about Article 145 are correct? I. A substantial question of law on the interpretation of the Constitution must be heard by at least five judges. II. A reference under Article 143 must also be heard by at least five judges. III. Every judgment must be delivered in open court. IV. A judge who does not agree with the majority may deliver a dissenting judgment or opinion.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: Article 145(3) needs at least five judges for a substantial question on interpretation and for an Article 143 reference, Article 145(4) requires judgment in open court, and Article 145(5) allows dissent.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 145 के संबंध में इनमें से कितने कथन सही हैं? I. संविधान की व्याख्या से संबंधित सारवान विधि-प्रश्न की सुनवाई कम से कम पांच न्यायाधीशों द्वारा होनी चाहिए। II. अनुच्छेद 143 के अंतर्गत संदर्भ की सुनवाई भी कम से कम पांच न्यायाधीशों द्वारा होनी चाहिए। III. प्रत्येक निर्णय खुले न्यायालय में सुनाया जाना चाहिए। IV. बहुमत से असहमत न्यायाधीश असहमति का निर्णय या राय दे सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं: अनुच्छेद 145(3) में व्याख्या के सारवान प्रश्न और अनुच्छेद 143 के संदर्भ के लिए कम से कम पांच न्यायाधीश चाहिए, अनुच्छेद 145(4) खुले न्यायालय में निर्णय की अपेक्षा करता है, और अनुच्छेद 145(5) असहमति की अनुमति देता है।"},
  {"id":"polity-judiciary-82","question":"How many of these statements are correct? I. M. Fathima Beevi was the first woman judge of the Supreme Court. II. Leila Seth was the first woman to become Chief Justice of a High Court. III. Indira Banerjee was the first woman appointed to the Supreme Court directly from the Bar. IV. Anna Chandy was the first woman judge of the Supreme Court.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I (1989) and II (Himachal Pradesh, 1991) are correct. III is wrong: Indu Malhotra (2018) was the first woman elevated directly from the Bar. IV is wrong: Anna Chandy was the first woman High Court judge (Kerala, 1959).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से कितने कथन सही हैं? I. एम. फातिमा बीवी सर्वोच्च न्यायालय की प्रथम महिला न्यायाधीश थीं। II. लीला सेठ किसी उच्च न्यायालय की मुख्य न्यायाधीश बनने वाली प्रथम महिला थीं। III. इंदिरा बनर्जी बार से सीधे सर्वोच्च न्यायालय में नियुक्त होने वाली प्रथम महिला थीं। IV. अन्ना चांडी सर्वोच्च न्यायालय की प्रथम महिला न्यायाधीश थीं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I (1989) और II (हिमाचल प्रदेश, 1991) सही हैं। III गलत है: इंदु मल्होत्रा (2018) बार से सीधे पदोन्नत होने वाली प्रथम महिला थीं। IV गलत है: अन्ना चांडी प्रथम महिला उच्च न्यायालय न्यायाधीश (केरल, 1959) थीं।"},
  {"id":"polity-judiciary-83","question":"Assertion (A): Parliament can raise the number of Supreme Court judges by an ordinary law. Reason (R): Article 124(1) leaves the number of judges, other than the Chief Justice, to be prescribed by Parliament by law.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: Parliament has raised the strength several times through the Supreme Court (Number of Judges) Act, 1956, without a constitutional amendment.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): संसद साधारण कानून द्वारा सर्वोच्च न्यायालय के न्यायाधीशों की संख्या बढ़ा सकती है। कारण (R): अनुच्छेद 124(1) मुख्य न्यायाधीश के अतिरिक्त न्यायाधीशों की संख्या संसद द्वारा कानून से निर्धारित करने के लिए छोड़ता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है: संसद ने सर्वोच्च न्यायालय (न्यायाधीशों की संख्या) अधिनियम, 1956 के माध्यम से संवैधानिक संशोधन के बिना कई बार संख्या बढ़ाई है।"},
  {"id":"polity-judiciary-84","question":"Which pair of State and principal seat of its High Court is NOT correctly matched?","options":["Madhya Pradesh – Jabalpur","Rajasthan – Jaipur","Chhattisgarh – Bilaspur","Odisha – Cuttack"],"answer":1,"explanation":"The Rajasthan High Court's principal seat is at Jodhpur; Jaipur has a bench. The other three are principal seats.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"राज्य और उसके उच्च न्यायालय की प्रधान पीठ का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["मध्य प्रदेश – जबलपुर","राजस्थान – जयपुर","छत्तीसगढ़ – बिलासपुर","ओडिशा – कटक"],"explanationHi":"राजस्थान उच्च न्यायालय की प्रधान पीठ जोधपुर में है; जयपुर में उसकी एक पीठ है। अन्य तीन प्रधान पीठें हैं।"},
  {"id":"polity-judiciary-85","question":"How many of these statements about the 42nd and 43rd Amendments are correct? I. The 42nd Amendment inserted Article 32A, barring the Supreme Court from considering the validity of State laws in Article 32 proceedings. II. It inserted Article 131A, giving the Supreme Court exclusive jurisdiction over the validity of Central laws. III. Article 144A required at least seven judges and a two-thirds majority to strike down a law. IV. The 43rd Amendment (1977) omitted these provisions.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 42nd Amendment curtailed judicial review in 1976, and the 43rd Amendment restored the courts' earlier powers by omitting Articles 32A, 131A, 144A, 226A and 228A.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"42वें और 43वें संशोधन के संबंध में इनमें से कितने कथन सही हैं? I. 42वें संशोधन ने अनुच्छेद 32A जोड़ा, जो सर्वोच्च न्यायालय को अनुच्छेद 32 की कार्यवाही में राज्य कानूनों की वैधता पर विचार करने से रोकता था। II. इसने अनुच्छेद 131A जोड़ा, जो केंद्रीय कानूनों की वैधता पर सर्वोच्च न्यायालय को अनन्य क्षेत्राधिकार देता था। III. अनुच्छेद 144A के अनुसार किसी कानून को रद्द करने के लिए कम से कम सात न्यायाधीश और दो-तिहाई बहुमत आवश्यक था। IV. 43वें संशोधन (1977) ने इन प्रावधानों को हटा दिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। 42वें संशोधन ने 1976 में न्यायिक पुनरावलोकन को सीमित किया, और 43वें संशोधन ने अनुच्छेद 32A, 131A, 144A, 226A और 228A को हटाकर न्यायालयों की पूर्व शक्तियां बहाल कीं।"},
  {"id":"polity-judiciary-86","question":"Before entering office, a judge of the Supreme Court makes the oath or affirmation before:","options":["The Chief Justice of India, in open court","The President, or a person appointed by him","The Vice-President, as Chairman of the Rajya Sabha","The Speaker, in a joint sitting of Parliament"],"answer":1,"explanation":"Article 124(6) requires the oath before the President or a person he appoints; in practice the CJI administers it to other judges. The form is in the Third Schedule.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"पद ग्रहण करने से पहले सर्वोच्च न्यायालय का न्यायाधीश किसके समक्ष शपथ या प्रतिज्ञान लेता है?","optionsHi":["भारत के मुख्य न्यायाधीश, खुले न्यायालय में","राष्ट्रपति, या उसके द्वारा नियुक्त व्यक्ति","उपराष्ट्रपति, राज्यसभा के सभापति के रूप में","अध्यक्ष, संसद की संयुक्त बैठक में"],"explanationHi":"अनुच्छेद 124(6) के अनुसार शपथ राष्ट्रपति या उसके द्वारा नियुक्त व्यक्ति के समक्ष लेनी होती है; व्यवहार में CJI अन्य न्यायाधीशों को शपथ दिलाते हैं। इसका प्रारूप तीसरी अनुसूची में है।"},
  {"id":"polity-judiciary-87","question":"Which court is at the head of the judicial system within a district?","options":["Court of the Senior Civil Judge","Court of the Chief Judicial Magistrate","Court of the District and Sessions Judge","Court of the District Collector and Magistrate"],"answer":2,"explanation":"The District Judge (called Sessions Judge on the criminal side) heads the district judiciary. Munsiffs and magistrates are subordinate to him; the Collector's court is a revenue court.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"जिले के भीतर न्यायिक प्रणाली का शीर्ष न्यायालय कौन-सा है?","optionsHi":["वरिष्ठ सिविल न्यायाधीश का न्यायालय","मुख्य न्यायिक मजिस्ट्रेट का न्यायालय","जिला एवं सत्र न्यायाधीश का न्यायालय","जिला कलेक्टर एवं मजिस्ट्रेट का न्यायालय"],"explanationHi":"जिला न्यायाधीश (आपराधिक पक्ष पर सत्र न्यायाधीश) जिला न्यायपालिका का प्रमुख होता है। मुंसिफ और मजिस्ट्रेट उसके अधीनस्थ होते हैं; कलेक्टर का न्यायालय राजस्व न्यायालय है।"},
  {"id":"polity-judiciary-88","question":"Which institution is called the guardian of the Constitution and protector of Fundamental Rights in India?","options":["Parliament","The President","The Election Commission","The Supreme Court"],"answer":3,"explanation":"The Supreme Court interprets the Constitution and enforces Fundamental Rights through Article 32, which makes it the guardian of the Constitution.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"भारत में किस संस्था को संविधान का संरक्षक और मौलिक अधिकारों का रक्षक कहा जाता है?","optionsHi":["संसद","राष्ट्रपति","निर्वाचन आयोग","सर्वोच्च न्यायालय"],"explanationHi":"सर्वोच्च न्यायालय संविधान की व्याख्या करता है और अनुच्छेद 32 के माध्यम से मौलिक अधिकारों को लागू करता है, जो उसे संविधान का संरक्षक बनाता है।"},
  {"id":"polity-judiciary-89","question":"The National Green Tribunal was set up under an Act passed in:","options":["2005","2010","2013","2002"],"answer":1,"explanation":"The National Green Tribunal Act, 2010 created a specialised body for environmental cases, drawing on Article 21 and Article 48A. Its principal bench is in New Delhi.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"राष्ट्रीय हरित अधिकरण की स्थापना किस वर्ष पारित अधिनियम के अंतर्गत हुई?","optionsHi":["2005","2010","2013","2002"],"explanationHi":"राष्ट्रीय हरित अधिकरण अधिनियम, 2010 ने अनुच्छेद 21 और अनुच्छेद 48A के आधार पर पर्यावरण संबंधी मामलों के लिए एक विशेष निकाय बनाया। इसकी प्रधान पीठ नई दिल्ली में है।"},
  {"id":"polity-judiciary-90","question":"Who became the 53rd Chief Justice of India in November 2025?","options":["Sanjiv Khanna","B. R. Gavai","Surya Kant","D. Y. Chandrachud"],"answer":2,"explanation":"Justice Surya Kant succeeded B. R. Gavai (the 52nd CJI) in November 2025. Sanjiv Khanna was the 51st and D. Y. Chandrachud the 50th.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"नवंबर 2025 में भारत के 53वें मुख्य न्यायाधीश कौन बने?","optionsHi":["संजीव खन्ना","बी. आर. गवई","सूर्यकांत","डी. वाई. चंद्रचूड़"],"explanationHi":"न्यायमूर्ति सूर्यकांत नवंबर 2025 में बी. आर. गवई (52वें CJI) के उत्तराधिकारी बने। संजीव खन्ना 51वें और डी. वाई. चंद्रचूड़ 50वें CJI थे।"},
  {"id":"polity-judiciary-91","question":"Under Article 124(7), a person who has held office as a judge of the Supreme Court may NOT plead or act:","options":["In any court or authority within India","Only in the Supreme Court, for five years","Only in the High Court of his home State","Only before tribunals and commissions"],"answer":0,"explanation":"The bar on retired Supreme Court judges is total. A retired High Court judge is barred only in that High Court and courts below it, and may practise in the Supreme Court and other High Courts (Article 220).","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"अनुच्छेद 124(7) के अंतर्गत, जो व्यक्ति सर्वोच्च न्यायालय का न्यायाधीश रह चुका है, वह कहां वकालत या कार्य नहीं कर सकता?","optionsHi":["भारत के भीतर किसी भी न्यायालय या प्राधिकारी के समक्ष","केवल सर्वोच्च न्यायालय में, पांच वर्ष तक","केवल अपने गृह राज्य के उच्च न्यायालय में","केवल अधिकरणों और आयोगों के समक्ष"],"explanationHi":"सर्वोच्च न्यायालय के सेवानिवृत्त न्यायाधीशों पर प्रतिबंध पूर्ण है। उच्च न्यायालय का सेवानिवृत्त न्यायाधीश केवल उसी उच्च न्यायालय और उसके अधीनस्थ न्यायालयों में वर्जित है, और सर्वोच्च न्यायालय तथा अन्य उच्च न्यायालयों में वकालत कर सकता है (अनुच्छेद 220)।"},
  {"id":"polity-judiciary-92","question":"Family Courts for speedy settlement of matrimonial and family disputes were provided for by an Act passed in:","options":["1976","1987","1993","1984"],"answer":3,"explanation":"The Family Courts Act was passed in 1984. The Legal Services Authorities Act, which gave Lok Adalats statutory status, came in 1987.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"वैवाहिक और पारिवारिक विवादों के शीघ्र निपटारे के लिए पारिवारिक न्यायालयों का प्रावधान किस वर्ष पारित अधिनियम में किया गया?","optionsHi":["1976","1987","1993","1984"],"explanationHi":"पारिवारिक न्यायालय अधिनियम 1984 में पारित हुआ। विधिक सेवा प्राधिकरण अधिनियम, जिसने लोक अदालतों को वैधानिक दर्जा दिया, 1987 में आया।"},
  {"id":"polity-judiciary-93","question":"Who was the first Chief Justice of India from a Dalit community?","options":["K. G. Balakrishnan","B. R. Gavai","M. Hidayatullah","Mirza Hameedullah Beg"],"answer":0,"explanation":"K. G. Balakrishnan was CJI from 2007 to 2010. B. R. Gavai, CJI in 2025, was the second CJI from a Scheduled Caste background.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"दलित समुदाय से भारत के प्रथम मुख्य न्यायाधीश कौन थे?","optionsHi":["के. जी. बालकृष्णन","बी. आर. गवई","एम. हिदायतुल्ला","मिर्जा हमीदुल्ला बेग"],"explanationHi":"के. जी. बालकृष्णन 2007 से 2010 तक CJI रहे। 2025 में CJI बने बी. आर. गवई अनुसूचित जाति पृष्ठभूमि के दूसरे CJI थे।"},
  {"id":"polity-judiciary-94","question":"In 2020 the Supreme Court held advocate Prashant Bhushan guilty of contempt for his tweets. What punishment did it impose?","options":["Six months' simple imprisonment","A fine of Re 1","A fine of Rs 2,000","Suspension of his licence to practise"],"answer":1,"explanation":"The Court imposed a token fine of Re 1, with three months' jail and a three-year practice bar if unpaid. The 1971 Act allows up to six months or Rs 2,000.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"2020 में सर्वोच्च न्यायालय ने अधिवक्ता प्रशांत भूषण को उनके ट्वीट के लिए अवमानना का दोषी ठहराया। न्यायालय ने क्या दंड दिया?","optionsHi":["छह माह का साधारण कारावास","1 रुपये का जुर्माना","2,000 रुपये का जुर्माना","वकालत के लाइसेंस का निलंबन"],"explanationHi":"न्यायालय ने 1 रुपये का सांकेतिक जुर्माना लगाया, जिसे न चुकाने पर तीन माह का कारावास और तीन वर्ष का वकालत प्रतिबंध था। 1971 का अधिनियम अधिकतम छह माह या 2,000 रुपये की अनुमति देता है।"},
  {"id":"polity-judiciary-95","question":"Under Article 146, the officers and servants of the Supreme Court are appointed by:","options":["The President, on the Cabinet's advice","The Union Public Service Commission","The Department of Justice in the Law Ministry","The CJI, or a judge or officer he directs"],"answer":3,"explanation":"Article 146 gives the CJI control over the Court's staff, and its administrative expenses are charged on the Consolidated Fund of India. Article 229 gives High Court Chief Justices a similar power.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 146 के अंतर्गत सर्वोच्च न्यायालय के अधिकारियों और कर्मचारियों की नियुक्ति कौन करता है?","optionsHi":["राष्ट्रपति, मंत्रिमंडल की सलाह पर","संघ लोक सेवा आयोग","विधि मंत्रालय का न्याय विभाग","CJI, या उनके द्वारा निर्देशित कोई न्यायाधीश या अधिकारी"],"explanationHi":"अनुच्छेद 146 CJI को न्यायालय के कर्मचारियों पर नियंत्रण देता है, और उसके प्रशासनिक व्यय भारत की संचित निधि पर भारित हैं। अनुच्छेद 229 उच्च न्यायालयों के मुख्य न्यायाधीशों को ऐसी ही शक्ति देता है।"},
  {"id":"polity-judiciary-96","question":"Under Article 145, the Supreme Court makes rules for regulating its practice and procedure, subject to any law made by Parliament, with the approval of the:","options":["Union Law Minister","President","Parliament","Full court of all judges, without outside approval"],"answer":1,"explanation":"Article 145(1) requires the President's approval for the Supreme Court Rules. Article 145(3) separately fixes a minimum of five judges for constitutional questions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 145 के अंतर्गत, सर्वोच्च न्यायालय संसद द्वारा बनाए गए किसी कानून के अधीन रहते हुए अपनी प्रक्रिया और कार्यपद्धति के नियम किसकी स्वीकृति से बनाता है?","optionsHi":["केंद्रीय विधि मंत्री","राष्ट्रपति","संसद","सभी न्यायाधीशों की पूर्ण पीठ, बिना बाहरी स्वीकृति के"],"explanationHi":"अनुच्छेद 145(1) सर्वोच्च न्यायालय के नियमों के लिए राष्ट्रपति की स्वीकृति आवश्यक करता है। अनुच्छेद 145(3) अलग से संवैधानिक प्रश्नों के लिए कम से कम पांच न्यायाधीशों की न्यूनतम संख्या तय करता है।"},
  {"id":"polity-judiciary-97","question":"Under Article 234, appointments of persons other than district judges to the judicial service of a State are made by the Governor in accordance with rules made after consulting:","options":["The State Public Service Commission and High Court","The Chief Minister and the State's Advocate General","The Union Public Service Commission and the CJI","The State Legislature and the Law Department"],"answer":0,"explanation":"Article 234 involves both the State PSC and the High Court. District judges are appointed under Article 233 by the Governor in consultation with the High Court.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"अनुच्छेद 234 के अंतर्गत, किसी राज्य की न्यायिक सेवा में जिला न्यायाधीशों के अतिरिक्त अन्य व्यक्तियों की नियुक्ति राज्यपाल किन से परामर्श के बाद बनाए गए नियमों के अनुसार करता है?","optionsHi":["राज्य लोक सेवा आयोग और उच्च न्यायालय","मुख्यमंत्री और राज्य का महाधिवक्ता","संघ लोक सेवा आयोग और CJI","राज्य विधानमंडल और विधि विभाग"],"explanationHi":"अनुच्छेद 234 में राज्य लोक सेवा आयोग और उच्च न्यायालय दोनों शामिल हैं। जिला न्यायाधीशों की नियुक्ति अनुच्छेद 233 के अंतर्गत राज्यपाल उच्च न्यायालय के परामर्श से करता है।"},
  {"id":"polity-judiciary-98","question":"In April 1973, a day after the Kesavananda Bharati judgment, which judge was appointed Chief Justice of India superseding three senior judges?","options":["M. H. Beg","Y. V. Chandrachud","A. N. Ray","P. N. Bhagwati"],"answer":2,"explanation":"A. N. Ray was appointed over Justices Shelat, Hegde and Grover, who resigned in protest. M. H. Beg's appointment in 1977 superseded H. R. Khanna.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अप्रैल 1973 में, केशवानंद भारती निर्णय के एक दिन बाद, तीन वरिष्ठ न्यायाधीशों की अनदेखी कर किस न्यायाधीश को भारत का मुख्य न्यायाधीश नियुक्त किया गया?","optionsHi":["एम. एच. बेग","वाई. वी. चंद्रचूड़","ए. एन. रे","पी. एन. भगवती"],"explanationHi":"ए. एन. रे को न्यायमूर्ति शेलट, हेगड़े और ग्रोवर की अनदेखी कर नियुक्त किया गया, जिन्होंने विरोध में त्यागपत्र दे दिया। एम. एच. बेग की 1977 की नियुक्ति में एच. आर. खन्ना की अनदेखी हुई थी।"},
  {"id":"polity-judiciary-99","question":"Under Article 312, Parliament may create an All-India Judicial Service. Which posts does Article 312(3) expressly exclude from it?","options":["Posts of district judge and additional district judge","Posts in the registries of the Supreme Court","Posts of judges of the High Courts","Any post below that of a district judge"],"answer":3,"explanation":"Article 312(3) says the service shall not include any post inferior to a district judge. It needs a Rajya Sabha resolution under Article 312(1); no such service has been created yet.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 312 के अंतर्गत संसद अखिल भारतीय न्यायिक सेवा बना सकती है। अनुच्छेद 312(3) इसमें से किन पदों को स्पष्ट रूप से बाहर रखता है?","optionsHi":["जिला न्यायाधीश और अतिरिक्त जिला न्यायाधीश के पद","सर्वोच्च न्यायालय की रजिस्ट्री के पद","उच्च न्यायालयों के न्यायाधीशों के पद","जिला न्यायाधीश से निम्न कोई भी पद"],"explanationHi":"अनुच्छेद 312(3) कहता है कि सेवा में जिला न्यायाधीश से निम्न कोई पद शामिल नहीं होगा। अनुच्छेद 312(1) के अंतर्गत इसके लिए राज्यसभा का संकल्प चाहिए; ऐसी कोई सेवा अभी तक नहीं बनी है।"},
  {"id":"polity-judiciary-100","question":"In Daryao v. State of U.P. (1961), the Supreme Court held that:","options":["Res judicata bars an Article 32 petition on a matter a High Court decided on merits","High Courts cannot issue writs to enforce Fundamental Rights while Article 32 is available","Article 32 can be suspended by an ordinary law of Parliament during peace","Public interest petitions need no affected party and are exempt from res judicata"],"answer":0,"explanation":"Daryao applied res judicata to writ petitions: once a High Court decides a matter on merits, the same claim cannot be reopened through Article 32; the remedy is an appeal.","difficulty":"hard","source":"UPSC Prelims","questionHi":"दरयाओ बनाम उत्तर प्रदेश राज्य (1961) में सर्वोच्च न्यायालय ने क्या निर्णय दिया?","optionsHi":["जिस विषय पर उच्च न्यायालय गुण-दोष के आधार पर निर्णय दे चुका हो, उस पर अनुच्छेद 32 की याचिका पूर्व-न्याय (res judicata) से वर्जित है","जब तक अनुच्छेद 32 उपलब्ध है, उच्च न्यायालय मौलिक अधिकारों के प्रवर्तन के लिए रिट जारी नहीं कर सकते","शांति काल में संसद के साधारण कानून द्वारा अनुच्छेद 32 को निलंबित किया जा सकता है","जनहित याचिकाओं में प्रभावित पक्ष की आवश्यकता नहीं और वे पूर्व-न्याय से मुक्त हैं"],"explanationHi":"दरयाओ ने रिट याचिकाओं पर पूर्व-न्याय का सिद्धांत लागू किया: एक बार उच्च न्यायालय किसी विषय पर गुण-दोष के आधार पर निर्णय दे दे, तो वही दावा अनुच्छेद 32 के माध्यम से दोबारा नहीं उठाया जा सकता; उपाय अपील है।"},
  {"id":"polity-judiciary-101","question":"The first reference made by the President to the Supreme Court under Article 143 concerned:","options":["The Kerala Education Bill","The Delhi Laws Act","The Berubari Union","The Special Courts Bill"],"answer":1,"explanation":"In re Delhi Laws Act (1951), on delegated legislation, was the first advisory reference. The Kerala Education Bill (1958), Berubari (1960) and Special Courts Bill (1978) references came later.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 143 के अंतर्गत राष्ट्रपति द्वारा सर्वोच्च न्यायालय को भेजा गया पहला संदर्भ किससे संबंधित था?","optionsHi":["केरल शिक्षा विधेयक","दिल्ली लॉज़ एक्ट","बेरुबारी संघ","विशेष न्यायालय विधेयक"],"explanationHi":"प्रत्यायोजित विधान से संबंधित दिल्ली लॉज़ एक्ट मामला (1951) पहला परामर्शी संदर्भ था। केरल शिक्षा विधेयक (1958), बेरुबारी (1960) और विशेष न्यायालय विधेयक (1978) के संदर्भ बाद में आए।"},
  {"id":"polity-judiciary-102","question":"In 2013 three new High Courts were set up for States that had earlier been under the Gauhati High Court. Which of these was NOT one of them?","options":["Manipur","Meghalaya","Tripura","Mizoram"],"answer":3,"explanation":"Manipur, Meghalaya and Tripura got their own High Courts in March 2013. Mizoram, along with Assam, Nagaland and Arunachal Pradesh, remains under the Gauhati High Court.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"2013 में गुवाहाटी उच्च न्यायालय के अधीन रहे राज्यों के लिए तीन नए उच्च न्यायालय बनाए गए। इनमें से कौन-सा उनमें से एक नहीं था?","optionsHi":["मणिपुर","मेघालय","त्रिपुरा","मिजोरम"],"explanationHi":"मणिपुर, मेघालय और त्रिपुरा को मार्च 2013 में अपने उच्च न्यायालय मिले। मिजोरम, असम, नागालैंड और अरुणाचल प्रदेश के साथ, गुवाहाटी उच्च न्यायालय के अधीन ही है।"},
  {"id":"polity-judiciary-103","question":"Under Section 22 of the National Green Tribunal Act, 2010, an appeal against an order of the Tribunal lies to the:","options":["High Court of the State concerned","Union Ministry of Environment","Supreme Court","Central Pollution Control Board"],"answer":2,"explanation":"Appeals from the NGT go directly to the Supreme Court, ordinarily within 90 days. This is why environment cases decided by the NGT skip the High Courts on appeal.","difficulty":"hard","source":"UPSC Prelims","questionHi":"राष्ट्रीय हरित अधिकरण अधिनियम, 2010 की धारा 22 के अंतर्गत, अधिकरण के आदेश के विरुद्ध अपील कहां की जाती है?","optionsHi":["संबंधित राज्य का उच्च न्यायालय","केंद्रीय पर्यावरण मंत्रालय","सर्वोच्च न्यायालय","केंद्रीय प्रदूषण नियंत्रण बोर्ड"],"explanationHi":"NGT से अपील सीधे सर्वोच्च न्यायालय में जाती है, सामान्यतः 90 दिनों के भीतर। इसीलिए NGT द्वारा तय पर्यावरण मामले अपील में उच्च न्यायालयों को छोड़ देते हैं।"},
  {"id":"polity-judiciary-104","question":"Under Article 134A, inserted by the 44th Amendment, the certificate of fitness for an appeal to the Supreme Court is granted by:","options":["The Supreme Court itself, on special leave","The President, on the Law Ministry's advice","The Attorney General for India","The High Court that passed the judgment"],"answer":3,"explanation":"Article 134A lets the High Court grant the certificate needed under Articles 132, 133 and 134(1)(c), on its own or on an oral application right after the judgment.","difficulty":"hard","source":"UPSC Prelims","questionHi":"44वें संशोधन द्वारा जोड़े गए अनुच्छेद 134A के अंतर्गत, सर्वोच्च न्यायालय में अपील के लिए उपयुक्तता का प्रमाणपत्र कौन देता है?","optionsHi":["स्वयं सर्वोच्च न्यायालय, विशेष अनुमति पर","राष्ट्रपति, विधि मंत्रालय की सलाह पर","भारत का महान्यायवादी","वह उच्च न्यायालय जिसने निर्णय दिया"],"explanationHi":"अनुच्छेद 134A उच्च न्यायालय को अनुच्छेद 132, 133 और 134(1)(c) के अंतर्गत आवश्यक प्रमाणपत्र देने देता है, स्वयं या निर्णय के तुरंत बाद मौखिक आवेदन पर।"},
  {"id":"polity-judiciary-105","question":"Match the State with the principal seat of its High Court: A. Kerala B. Uttarakhand C. Himachal Pradesh D. Gujarat — 1. Shimla 2. Ahmedabad 3. Nainital 4. Ernakulam (Kochi)","options":["A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2","A-2, B-3, C-1, D-4","A-4, B-3, C-2, D-1"],"answer":1,"explanation":"The Kerala High Court sits at Ernakulam, not Thiruvananthapuram; Uttarakhand's at Nainital, not Dehradun; Himachal's at Shimla; Gujarat's at Ahmedabad, not Gandhinagar.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"राज्य का मिलान उसके उच्च न्यायालय की प्रधान पीठ से कीजिए: A. केरल B. उत्तराखंड C. हिमाचल प्रदेश D. गुजरात — 1. शिमला 2. अहमदाबाद 3. नैनीताल 4. एर्नाकुलम (कोच्चि)","optionsHi":["A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2","A-2, B-3, C-1, D-4","A-4, B-3, C-2, D-1"],"explanationHi":"केरल उच्च न्यायालय एर्नाकुलम में है, तिरुवनंतपुरम में नहीं; उत्तराखंड का नैनीताल में है, देहरादून में नहीं; हिमाचल का शिमला में; और गुजरात का अहमदाबाद में है, गांधीनगर में नहीं।"},
  {"id":"polity-judiciary-106","question":"Article 233A, which validated the appointments of certain district judges after the Supreme Court found them irregular in Chandra Mohan v. State of U.P., was inserted by the:","options":["7th Amendment, 1956","15th Amendment, 1963","20th Amendment, 1966","42nd Amendment, 1976"],"answer":2,"explanation":"The 20th Amendment (1966) added Article 233A to save judgments and appointments affected by Chandra Mohan, which held that the Governor must consult the High Court.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 233A, जिसने चंद्र मोहन बनाम उत्तर प्रदेश राज्य में सर्वोच्च न्यायालय द्वारा अनियमित पाए जाने के बाद कुछ जिला न्यायाधीशों की नियुक्तियों को वैध ठहराया, किस संशोधन द्वारा जोड़ा गया?","optionsHi":["7वां संशोधन, 1956","15वां संशोधन, 1963","20वां संशोधन, 1966","42वां संशोधन, 1976"],"explanationHi":"20वें संशोधन (1966) ने चंद्र मोहन से प्रभावित निर्णयों और नियुक्तियों को बचाने के लिए अनुच्छेद 233A जोड़ा; चंद्र मोहन ने माना था कि राज्यपाल को उच्च न्यायालय से परामर्श करना चाहिए।"},
  {"id":"polity-judiciary-107","question":"Consider the following statements: 1. In 2011 the Rajya Sabha passed a motion for the removal of Justice Soumitra Sen of the Calcutta High Court. 2. He was removed after the Lok Sabha also passed the motion. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct. Justice Sen resigned before the Lok Sabha took up the motion, so it lapsed; no judge has ever been removed under Article 124(4) or 218.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. 2011 में राज्यसभा ने कलकत्ता उच्च न्यायालय के न्यायमूर्ति सौमित्र सेन को हटाने का प्रस्ताव पारित किया। 2. लोकसभा द्वारा भी प्रस्ताव पारित करने के बाद उन्हें हटाया गया। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है। लोकसभा द्वारा प्रस्ताव लिए जाने से पहले न्यायमूर्ति सेन ने त्यागपत्र दे दिया, इसलिए प्रस्ताव व्यपगत हो गया; अनुच्छेद 124(4) या 218 के अंतर्गत आज तक किसी न्यायाधीश को हटाया नहीं गया।"},
  {"id":"polity-judiciary-108","question":"Consider the following statements: 1. Y. V. Chandrachud had the longest tenure of any Chief Justice of India. 2. Kamal Narain Singh had the shortest tenure as Chief Justice of India. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Chandrachud served from 1978 to 1985, over seven years; Kamal Narain Singh served for only about 17 days in 1991.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. वाई. वी. चंद्रचूड़ का कार्यकाल भारत के किसी भी मुख्य न्यायाधीश में सबसे लंबा था। 2. कमल नारायण सिंह का कार्यकाल भारत के मुख्य न्यायाधीश के रूप में सबसे छोटा था। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। चंद्रचूड़ ने 1978 से 1985 तक, सात वर्ष से अधिक, सेवा की; कमल नारायण सिंह ने 1991 में केवल लगभग 17 दिन सेवा की।"},
  {"id":"polity-judiciary-109","question":"Arrange these advisory references under Article 143 in chronological order: 1. Kerala Education Bill 2. Berubari Union 3. Special Courts Bill 4. Delhi Laws Act","options":["4, 2, 1, 3","1, 4, 2, 3","4, 1, 3, 2","4, 1, 2, 3"],"answer":3,"explanation":"Delhi Laws Act (1951), Kerala Education Bill (1958), Berubari Union (1960) and Special Courts Bill (1978).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 143 के अंतर्गत इन परामर्शी संदर्भों को कालक्रम में व्यवस्थित कीजिए: 1. केरल शिक्षा विधेयक 2. बेरुबारी संघ 3. विशेष न्यायालय विधेयक 4. दिल्ली लॉज़ एक्ट","optionsHi":["4, 2, 1, 3","1, 4, 2, 3","4, 1, 3, 2","4, 1, 2, 3"],"explanationHi":"दिल्ली लॉज़ एक्ट (1951), केरल शिक्षा विधेयक (1958), बेरुबारी संघ (1960) और विशेष न्यायालय विधेयक (1978)।"},
  {"id":"polity-judiciary-110","question":"Assertion (A): A High Court can issue a writ to an authority located outside its territory if the cause of action arises wholly or partly within its territory. Reason (R): Clause (2) of Article 226, added by the 15th Amendment, 1963, provides for this.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Before 1963 a writ could issue only to authorities located within the court's territory, which forced cases against the Centre to go to the Punjab High Court.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उच्च न्यायालय अपने क्षेत्र के बाहर स्थित किसी प्राधिकारी को रिट जारी कर सकता है, यदि वाद-हेतुक पूर्णतः या आंशिक रूप से उसके क्षेत्र में उत्पन्न हो। कारण (R): 15वें संशोधन, 1963 द्वारा जोड़ा गया अनुच्छेद 226 का खंड (2) इसका प्रावधान करता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं किंतु R, A की सही व्याख्या नहीं है","A सही है किंतु R गलत है","A गलत है किंतु R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है। 1963 से पहले रिट केवल न्यायालय के क्षेत्र में स्थित प्राधिकारियों को जारी हो सकती थी, जिसके कारण केंद्र के विरुद्ध मामले पंजाब उच्च न्यायालय में जाने पड़ते थे।"},
  {"id":"polity-judiciary-111","question":"Consider the following statements: 1. Officers and servants of a High Court are appointed by the Chief Justice of that High Court. 2. The administrative expenses of a High Court are charged on the Consolidated Fund of India. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct (Article 229). A High Court's administrative expenses are charged on the Consolidated Fund of the State; it is the Supreme Court's expenses that are charged on the Consolidated Fund of India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. उच्च न्यायालय के अधिकारियों और कर्मचारियों की नियुक्ति उस उच्च न्यायालय का मुख्य न्यायाधीश करता है। 2. उच्च न्यायालय के प्रशासनिक व्यय भारत की संचित निधि पर भारित होते हैं। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है (अनुच्छेद 229)। उच्च न्यायालय के प्रशासनिक व्यय राज्य की संचित निधि पर भारित होते हैं; सर्वोच्च न्यायालय के व्यय भारत की संचित निधि पर भारित हैं।"},
  {"id":"polity-judiciary-112","question":"Arrange these High Courts in the order in which they were established: 1. Andhra Pradesh High Court at Amaravati 2. Allahabad High Court 3. Tripura High Court 4. Calcutta High Court","options":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"answer":0,"explanation":"Calcutta (1862), Allahabad (1866), Tripura (2013) and the separate Andhra Pradesh High Court (1 January 2019), which made the total 25.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इन उच्च न्यायालयों को उनकी स्थापना के क्रम में व्यवस्थित कीजिए: 1. अमरावती में आंध्र प्रदेश उच्च न्यायालय 2. इलाहाबाद उच्च न्यायालय 3. त्रिपुरा उच्च न्यायालय 4. कलकत्ता उच्च न्यायालय","optionsHi":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"explanationHi":"कलकत्ता (1862), इलाहाबाद (1866), त्रिपुरा (2013) और अलग आंध्र प्रदेश उच्च न्यायालय (1 जनवरी 2019), जिससे कुल संख्या 25 हो गई।"},
  {"id":"polity-judiciary-113","question":"Consider the following statements: 1. M. H. Beg was appointed Chief Justice of India in 1977, superseding H. R. Khanna. 2. Khanna had written the lone dissent in ADM Jabalpur. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Khanna resigned after being superseded; his ADM Jabalpur dissent was vindicated when the judgment was overruled in Puttaswamy (2017).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एम. एच. बेग को 1977 में एच. आर. खन्ना की अनदेखी कर भारत का मुख्य न्यायाधीश नियुक्त किया गया। 2. खन्ना ने ADM जबलपुर में एकमात्र असहमति का निर्णय लिखा था। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। अनदेखी किए जाने पर खन्ना ने त्यागपत्र दे दिया; उनकी ADM जबलपुर की असहमति तब सही सिद्ध हुई जब पुट्टास्वामी (2017) में उस निर्णय को पलट दिया गया।"},
  {"id":"polity-judiciary-114","question":"Match the tribunal with the law that created it: A. National Green Tribunal B. Armed Forces Tribunal C. Central Administrative Tribunal D. National Company Law Tribunal — 1. Administrative Tribunals Act, 1985 2. Companies Act, 2013 3. National Green Tribunal Act, 2010 4. Armed Forces Tribunal Act, 2007","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"NGT: 2010 Act; AFT: 2007 Act; CAT: Administrative Tribunals Act, 1985 under Article 323A; NCLT: Companies Act, 2013.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अधिकरण का मिलान उस कानून से कीजिए जिसने उसे बनाया: A. राष्ट्रीय हरित अधिकरण B. सशस्त्र बल अधिकरण C. केंद्रीय प्रशासनिक अधिकरण D. राष्ट्रीय कंपनी विधि अधिकरण — 1. प्रशासनिक अधिकरण अधिनियम, 1985 2. कंपनी अधिनियम, 2013 3. राष्ट्रीय हरित अधिकरण अधिनियम, 2010 4. सशस्त्र बल अधिकरण अधिनियम, 2007","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"NGT: 2010 का अधिनियम; AFT: 2007 का अधिनियम; CAT: अनुच्छेद 323A के अंतर्गत प्रशासनिक अधिकरण अधिनियम, 1985; NCLT: कंपनी अधिनियम, 2013।"},
  {"id":"polity-judiciary-115","question":"Which of these is NOT a ground on which a High Court judge's office becomes vacant?","options":["Resignation addressed to the President","Removal by the President on an address by both Houses of Parliament","Appointment as a judge of the Supreme Court","A resolution of the State Legislative Assembly"],"answer":3,"explanation":"Under Article 217(1), a High Court judge's office ends by resignation to the President, removal through Parliament, appointment to the Supreme Court or transfer to another High Court. A State Legislature has no role in removal.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इनमें से कौन-सा उच्च न्यायालय के न्यायाधीश का पद रिक्त होने का आधार नहीं है?","optionsHi":["राष्ट्रपति को संबोधित त्यागपत्र","संसद के दोनों सदनों के समावेदन पर राष्ट्रपति द्वारा हटाया जाना","सर्वोच्च न्यायालय के न्यायाधीश के रूप में नियुक्ति","राज्य विधान सभा का संकल्प"],"explanationHi":"अनुच्छेद 217(1) के अंतर्गत उच्च न्यायालय के न्यायाधीश का पद राष्ट्रपति को त्यागपत्र, संसद के माध्यम से हटाए जाने, सर्वोच्च न्यायालय में नियुक्ति या किसी अन्य उच्च न्यायालय में स्थानांतरण से समाप्त होता है। राज्य विधानमंडल की हटाने में कोई भूमिका नहीं है।"},
  {"id":"polity-judiciary-116","question":"Once a motion to remove a Supreme Court judge is admitted, the Judges (Inquiry) Act, 1968 provides for a three-member inquiry committee. Who are its members?","options":["The Chief Justice of India, the Attorney General and the Union Law Minister","An SC judge or the CJI, a High Court Chief Justice and a distinguished jurist","Three senior judges of the Supreme Court nominated by the collegium","The Speaker, the Chairman of the Rajya Sabha and a retired Supreme Court judge"],"answer":1,"explanation":"Section 3(2) of the Act prescribes these three. The Speaker or Chairman only admits the motion and constitutes the committee; Parliament votes later only if the judge is found guilty.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय के न्यायाधीश को हटाने का प्रस्ताव स्वीकार होने के बाद, न्यायाधीश (जांच) अधिनियम, 1968 तीन सदस्यीय जांच समिति का प्रावधान करता है। इसके सदस्य कौन होते हैं?","optionsHi":["भारत के मुख्य न्यायाधीश, महान्यायवादी और केंद्रीय विधि मंत्री","सर्वोच्च न्यायालय का एक न्यायाधीश या CJI, एक उच्च न्यायालय का मुख्य न्यायाधीश और एक प्रतिष्ठित विधिवेत्ता","कॉलेजियम द्वारा नामित सर्वोच्च न्यायालय के तीन वरिष्ठ न्यायाधीश","अध्यक्ष, राज्यसभा के सभापति और सर्वोच्च न्यायालय का एक सेवानिवृत्त न्यायाधीश"],"explanationHi":"अधिनियम की धारा 3(2) ये तीन सदस्य निर्धारित करती है। अध्यक्ष या सभापति केवल प्रस्ताव स्वीकार करते हैं और समिति गठित करते हैं; संसद बाद में तभी मतदान करती है जब न्यायाधीश दोषी पाया जाए।"},
  {"id":"polity-judiciary-117","question":"Consider the following statements about ad hoc judges of the Supreme Court under Article 127: 1. Only a retired Supreme Court judge can be appointed. 2. The Chief Justice of India must consult the Chief Justice of the High Court concerned. 3. While so sitting, the ad hoc judge has only the jurisdiction and powers of a High Court judge. How many of the above statements are correct?","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only 2 is correct. Article 127 appoints a High Court judge duly qualified to be a Supreme Court judge (retired SC judges sit under Article 128), and while sitting he has all the jurisdiction, powers and privileges of a Supreme Court judge.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 127 के अंतर्गत सर्वोच्च न्यायालय के तदर्थ न्यायाधीशों के संबंध में निम्नलिखित कथनों पर विचार कीजिए: 1. केवल सर्वोच्च न्यायालय का सेवानिवृत्त न्यायाधीश ही नियुक्त हो सकता है। 2. भारत के मुख्य न्यायाधीश को संबंधित उच्च न्यायालय के मुख्य न्यायाधीश से परामर्श करना अनिवार्य है। 3. इस प्रकार बैठते समय तदर्थ न्यायाधीश के पास केवल उच्च न्यायालय के न्यायाधीश का क्षेत्राधिकार और शक्तियां होती हैं। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल 2 सही है। अनुच्छेद 127 के अंतर्गत सर्वोच्च न्यायालय का न्यायाधीश बनने के लिए विधिवत योग्य उच्च न्यायालय के न्यायाधीश की नियुक्ति होती है (सेवानिवृत्त SC न्यायाधीश अनुच्छेद 128 के अंतर्गत बैठते हैं), और बैठते समय उसके पास सर्वोच्च न्यायालय के न्यायाधीश का पूरा क्षेत्राधिकार, शक्तियां और विशेषाधिकार होते हैं।"},
  {"id":"polity-judiciary-118","question":"Consider the following statements about Article 128: 1. The Chief Justice of India may, with the President's previous consent, request a retired judge to sit and act as a Supreme Court judge. 2. A retired High Court judge who is duly qualified for appointment to the Supreme Court may also be requested. 3. A retired judge so requested cannot decline. Which of the above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 128 covers retired Supreme Court judges and qualified retired High Court judges, but expressly requires the person's own consent, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 128 के संबंध में निम्नलिखित कथनों पर विचार कीजिए: 1. भारत का मुख्य न्यायाधीश, राष्ट्रपति की पूर्व सहमति से, किसी सेवानिवृत्त न्यायाधीश से सर्वोच्च न्यायालय के न्यायाधीश के रूप में बैठने और कार्य करने का अनुरोध कर सकता है। 2. उच्च न्यायालय का सेवानिवृत्त न्यायाधीश, जो सर्वोच्च न्यायालय में नियुक्ति के लिए विधिवत योग्य हो, उससे भी अनुरोध किया जा सकता है। 3. इस प्रकार अनुरोध किया गया सेवानिवृत्त न्यायाधीश इनकार नहीं कर सकता। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अनुच्छेद 128 सर्वोच्च न्यायालय के सेवानिवृत्त न्यायाधीशों और योग्य सेवानिवृत्त उच्च न्यायालय न्यायाधीशों को कवर करता है, किंतु स्पष्ट रूप से उस व्यक्ति की अपनी सहमति आवश्यक करता है, इसलिए 3 गलत है।"},
  {"id":"polity-judiciary-119","question":"Consider the following statements: 1. The President may appoint additional judges of a High Court for up to two years to deal with a temporary increase in business or arrears. 2. The Chief Justice of a High Court may, with the President's previous consent, request a retired High Court judge to sit and act as a judge. 3. An additional judge may continue beyond 62 if his two-year term has not ended. Which of the above are correct?","options":["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Articles 224 and 224A support 1 and 2. Article 224(3) bars any additional or acting judge from holding office beyond 62.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. राष्ट्रपति कार्य में अस्थायी वृद्धि या बकाया मामलों से निपटने के लिए उच्च न्यायालय के अतिरिक्त न्यायाधीशों को दो वर्ष तक के लिए नियुक्त कर सकता है। 2. उच्च न्यायालय का मुख्य न्यायाधीश, राष्ट्रपति की पूर्व सहमति से, सेवानिवृत्त उच्च न्यायालय न्यायाधीश से न्यायाधीश के रूप में बैठने और कार्य करने का अनुरोध कर सकता है। 3. अतिरिक्त न्यायाधीश, यदि उसका दो वर्ष का कार्यकाल समाप्त न हुआ हो, तो 62 वर्ष के बाद भी पद पर बना रह सकता है। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","1, 2 और 3","केवल 1 और 2"],"explanationHi":"अनुच्छेद 224 और 224A कथन 1 और 2 का समर्थन करते हैं। अनुच्छेद 224(3) किसी भी अतिरिक्त या कार्यकारी न्यायाधीश को 62 वर्ष से आगे पद धारण करने से रोकता है।"},
  {"id":"polity-judiciary-120","question":"Consider the following statements: 1. A question about the age of a High Court judge is decided by the President after consulting the Chief Justice of India, and the decision is final. 2. The age of a Supreme Court judge is determined by such authority and in such manner as Parliament may by law provide. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Article 217(3) covers High Court judges. Article 124(2A), added by the 15th Amendment (1963), leaves the Supreme Court case to a law of Parliament.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. उच्च न्यायालय के न्यायाधीश की आयु का प्रश्न राष्ट्रपति भारत के मुख्य न्यायाधीश से परामर्श के बाद तय करता है, और उसका निर्णय अंतिम होता है। 2. सर्वोच्च न्यायालय के न्यायाधीश की आयु ऐसे प्राधिकारी द्वारा और ऐसी रीति से निर्धारित की जाती है जैसा संसद कानून द्वारा उपबंध करे। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"अनुच्छेद 217(3) उच्च न्यायालय के न्यायाधीशों से संबंधित है। 15वें संशोधन (1963) द्वारा जोड़ा गया अनुच्छेद 124(2A) सर्वोच्च न्यायालय का मामला संसद के कानून पर छोड़ता है।"},
  {"id":"polity-judiciary-121","question":"After retiring as a permanent judge of a High Court, a person wants to resume legal practice. Under Article 220, he may plead:","options":["before the Supreme Court and other High Courts, but not his own","in any court in India, including the High Court where he served","only before tribunals and arbitral bodies, not before any court","only before the Supreme Court, and in no High Court at all"],"answer":0,"explanation":"Article 220 bars him only from his own High Court and its subordinate courts. A retired Supreme Court judge, by contrast, cannot plead in any court in India (Article 124(7)).","difficulty":"hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालय के स्थायी न्यायाधीश के रूप में सेवानिवृत्त होने के बाद, कोई व्यक्ति फिर से वकालत शुरू करना चाहता है। अनुच्छेद 220 के अंतर्गत वह कहां वकालत कर सकता है?","optionsHi":["सर्वोच्च न्यायालय और अन्य उच्च न्यायालयों में, किंतु अपने उच्च न्यायालय में नहीं","भारत के किसी भी न्यायालय में, उस उच्च न्यायालय सहित जहां उसने सेवा दी","केवल अधिकरणों और माध्यस्थम निकायों के समक्ष, किसी न्यायालय में नहीं","केवल सर्वोच्च न्यायालय में, किसी भी उच्च न्यायालय में नहीं"],"explanationHi":"अनुच्छेद 220 उसे केवल उसके अपने उच्च न्यायालय और उसके अधीनस्थ न्यायालयों में वकालत से रोकता है। इसके विपरीत, सर्वोच्च न्यायालय का सेवानिवृत्त न्यायाधीश भारत के किसी भी न्यायालय में वकालत नहीं कर सकता (अनुच्छेद 124(7))।"},
  {"id":"polity-judiciary-122","question":"Before entering office, a judge of a High Court makes the oath or affirmation before:","options":["the Chief Justice of that High Court, in open court","the Governor of the State, or a person he appoints","the President of India, who appoints him","the Chief Justice of India or a judge he nominates"],"answer":1,"explanation":"Article 219 requires the oath before the Governor or someone he appoints, though the President appoints High Court judges. Supreme Court judges take their oath before the President.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"पद ग्रहण करने से पहले उच्च न्यायालय का न्यायाधीश किसके समक्ष शपथ या प्रतिज्ञान लेता है?","optionsHi":["उस उच्च न्यायालय के मुख्य न्यायाधीश, खुले न्यायालय में","राज्य के राज्यपाल, या उसके द्वारा नियुक्त व्यक्ति","भारत के राष्ट्रपति, जो उसे नियुक्त करता है","भारत के मुख्य न्यायाधीश या उनके द्वारा नामित न्यायाधीश"],"explanationHi":"अनुच्छेद 219 के अनुसार शपथ राज्यपाल या उसके द्वारा नियुक्त व्यक्ति के समक्ष ली जाती है, यद्यपि उच्च न्यायालय के न्यायाधीशों की नियुक्ति राष्ट्रपति करता है। सर्वोच्च न्यायालय के न्यायाधीश राष्ट्रपति के समक्ष शपथ लेते हैं।"},
  {"id":"polity-judiciary-123","question":"In Union of India v. Sankalchand Sheth (1977), on the transfer of High Court judges under Article 222, the Supreme Court held that:","options":["a judge can be transferred only with his own consent, since transfer changes his service conditions","the President may transfer a judge without consulting the CJI if public interest requires","transfer is a form of punishment and so needs a prior inquiry into the judge's conduct","his consent is not needed, but there must be full and effective consultation with the CJI"],"answer":3,"explanation":"The Court held that consent is not required, but the transfer must serve the public interest and follow real consultation with the CJI. It is not a punitive measure.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत संघ बनाम संकलचंद शेठ (1977) में, अनुच्छेद 222 के अंतर्गत उच्च न्यायालय के न्यायाधीशों के स्थानांतरण के संबंध में, सर्वोच्च न्यायालय ने क्या निर्णय दिया?","optionsHi":["न्यायाधीश का स्थानांतरण केवल उसकी अपनी सहमति से हो सकता है, क्योंकि स्थानांतरण उसकी सेवा शर्तें बदलता है","जनहित में आवश्यक होने पर राष्ट्रपति CJI से परामर्श किए बिना न्यायाधीश का स्थानांतरण कर सकता है","स्थानांतरण एक प्रकार का दंड है, इसलिए न्यायाधीश के आचरण की पूर्व जांच आवश्यक है","उसकी सहमति आवश्यक नहीं है, किंतु CJI के साथ पूर्ण और प्रभावी परामर्श होना चाहिए"],"explanationHi":"न्यायालय ने माना कि सहमति आवश्यक नहीं है, किंतु स्थानांतरण जनहित में होना चाहिए और CJI से वास्तविक परामर्श के बाद होना चाहिए। यह दंडात्मक उपाय नहीं है।"},
  {"id":"polity-judiciary-124","question":"A High Court grants an interim order under Article 226 without notice to the other party, which then applies to have it vacated. Under Article 226(3):","options":["the Court must decide the application within two weeks, or the interim order stands vacated","the interim order continues until the Court decides the application, however long that takes","the interim order lapses automatically one month after it was granted","the other party's only remedy is a special leave petition to the Supreme Court"],"answer":0,"explanation":"Clause (3), in its 44th Amendment form, sets a two-week deadline (or the next working day) after which the ex parte interim order stands vacated.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालय अनुच्छेद 226 के अंतर्गत दूसरे पक्ष को सूचना दिए बिना एक अंतरिम आदेश देता है, और वह पक्ष उसे रद्द कराने के लिए आवेदन करता है। अनुच्छेद 226(3) के अनुसार:","optionsHi":["न्यायालय को आवेदन दो सप्ताह के भीतर तय करना होगा, अन्यथा अंतरिम आदेश रद्द माना जाएगा","अंतरिम आदेश तब तक जारी रहता है जब तक न्यायालय आवेदन तय न करे, चाहे कितना भी समय लगे","अंतरिम आदेश दिए जाने के एक माह बाद स्वतः समाप्त हो जाता है","दूसरे पक्ष का एकमात्र उपाय सर्वोच्च न्यायालय में विशेष अनुमति याचिका है"],"explanationHi":"खंड (3), अपने 44वें संशोधन के रूप में, दो सप्ताह की समय-सीमा (या अगला कार्य दिवस) तय करता है, जिसके बाद एकपक्षीय अंतरिम आदेश रद्द माना जाता है।"},
  {"id":"polity-judiciary-125","question":"A case pending in a subordinate court raises a substantial question of law on the interpretation of the Constitution, and deciding it is necessary to dispose of the case. Under Article 228, the High Court:","options":["must refer the question to the Supreme Court under Article 143 for its opinion","may decide the question only if both parties consent to the withdrawal","shall withdraw the case and decide it, or decide the question and return it","has no power to intervene until the subordinate court gives judgment"],"answer":2,"explanation":"Article 228 obliges the High Court to withdraw the case; it may then decide the whole case or only the constitutional question. Article 143 is a reference by the President, not by courts.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किसी अधीनस्थ न्यायालय में लंबित मामले में संविधान की व्याख्या का सारवान विधि-प्रश्न उठता है, और मामले के निपटारे के लिए उसका निर्णय आवश्यक है। अनुच्छेद 228 के अंतर्गत, उच्च न्यायालय:","optionsHi":["प्रश्न को अनुच्छेद 143 के अंतर्गत राय के लिए सर्वोच्च न्यायालय को भेजेगा","प्रश्न का निर्णय तभी कर सकता है जब दोनों पक्ष मामले को मंगवाने पर सहमत हों","मामले को अपने पास मंगवाकर उसका निर्णय करेगा, या प्रश्न का निर्णय करके मामला लौटा देगा","अधीनस्थ न्यायालय के निर्णय देने तक हस्तक्षेप करने की कोई शक्ति नहीं रखता"],"explanationHi":"अनुच्छेद 228 उच्च न्यायालय को मामला अपने पास मंगवाने के लिए बाध्य करता है; वह फिर पूरे मामले का या केवल संवैधानिक प्रश्न का निर्णय कर सकता है। अनुच्छेद 143 राष्ट्रपति द्वारा किया गया संदर्भ है, न्यायालयों द्वारा नहीं।"},
  {"id":"polity-judiciary-126","question":"A practising lawyer who is not in government service wants to be appointed directly as a district judge. Under Article 233(2), he must:","options":["have been an advocate for at least ten years and be recommended by the State PSC","have practised for at least seven years and be recommended by the High Court","have held judicial office for at least five years and pass a State PSC exam","be recommended by the Chief Justice of India after an interview by the collegium"],"answer":1,"explanation":"Article 233(2) requires seven years at the bar and the High Court's recommendation; the Governor then appoints. Ten years is the requirement for a High Court judge.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सरकारी सेवा में न रहने वाला एक प्रैक्टिसरत वकील सीधे जिला न्यायाधीश नियुक्त होना चाहता है। अनुच्छेद 233(2) के अंतर्गत उसे:","optionsHi":["कम से कम दस वर्ष अधिवक्ता रहा होना चाहिए और राज्य लोक सेवा आयोग द्वारा अनुशंसित होना चाहिए","कम से कम सात वर्ष वकालत की होनी चाहिए और उच्च न्यायालय द्वारा अनुशंसित होना चाहिए","कम से कम पांच वर्ष न्यायिक पद धारण किया होना चाहिए और राज्य लोक सेवा आयोग की परीक्षा उत्तीर्ण करनी चाहिए","कॉलेजियम द्वारा साक्षात्कार के बाद भारत के मुख्य न्यायाधीश द्वारा अनुशंसित होना चाहिए"],"explanationHi":"अनुच्छेद 233(2) में बार में सात वर्ष और उच्च न्यायालय की सिफारिश आवश्यक है; इसके बाद राज्यपाल नियुक्त करता है। दस वर्ष उच्च न्यायालय के न्यायाधीश के लिए आवश्यकता है।"},
  {"id":"polity-judiciary-127","question":"Control over district courts and subordinate courts, including the posting, promotion and leave of judicial officers below the rank of district judge, is vested by Article 235 in the:","options":["Governor","State Public Service Commission","State Law Department","High Court"],"answer":3,"explanation":"Article 235 gives the High Court control over the subordinate judiciary, which protects its independence from the State executive.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"जिला न्यायाधीश से निम्न रैंक के न्यायिक अधिकारियों की पदस्थापना, पदोन्नति और अवकाश सहित जिला न्यायालयों और अधीनस्थ न्यायालयों पर नियंत्रण अनुच्छेद 235 द्वारा किसमें निहित है?","optionsHi":["राज्यपाल","राज्य लोक सेवा आयोग","राज्य विधि विभाग","उच्च न्यायालय"],"explanationHi":"अनुच्छेद 235 उच्च न्यायालय को अधीनस्थ न्यायपालिका पर नियंत्रण देता है, जो उसकी राज्य कार्यपालिका से स्वतंत्रता की रक्षा करता है।"},
  {"id":"polity-judiciary-128","question":"Which statement about the writ of quo warranto is correct?","options":["Even a person who is not aggrieved may seek it against a usurper of a public office","It can be issued against a person holding a ministerial office or a private office","Only a person who claims the office for himself, as the rightful holder, can seek it","It is used to compel a public official to perform a duty imposed on him by statute"],"answer":0,"explanation":"Quo warranto tests title to a substantive public office and does not need a personally aggrieved petitioner. It does not lie for ministerial or private offices; compelling a duty is mandamus.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अधिकार पृच्छा रिट के बारे में कौन-सा कथन सही है?","optionsHi":["जो व्यक्ति पीड़ित नहीं है वह भी लोक पद पर अनधिकृत कब्जा करने वाले के विरुद्ध इसकी मांग कर सकता है","इसे लिपिकीय पद या निजी पद धारण करने वाले व्यक्ति के विरुद्ध जारी किया जा सकता है","केवल वही व्यक्ति इसकी मांग कर सकता है जो पद को सही धारक के रूप में अपने लिए दावा करता हो","इसका उपयोग किसी लोक अधिकारी को कानून द्वारा उस पर लगाया गया कर्तव्य निभाने के लिए बाध्य करने में होता है"],"explanationHi":"अधिकार पृच्छा किसी सारवान लोक पद के स्वत्व की जांच करती है और इसके लिए व्यक्तिगत रूप से पीड़ित याचिकाकर्ता आवश्यक नहीं है। यह लिपिकीय या निजी पदों के लिए नहीं है; कर्तव्य निभाने के लिए बाध्य करना परमादेश है।"},
  {"id":"polity-judiciary-129","question":"Against which of the following can a writ of mandamus be issued?","options":["The Governor of a State, for acts done in his personal capacity","A private individual, to enforce a contract","A public authority that refuses to perform a statutory duty owed to the petitioner","An authority, to make it exercise a purely discretionary power in a particular way"],"answer":2,"explanation":"Mandamus enforces a public legal duty. It does not lie against the President or Governor personally (Article 361), against private persons, to enforce contracts, or to dictate discretion.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से किसके विरुद्ध परमादेश रिट जारी की जा सकती है?","optionsHi":["किसी राज्य का राज्यपाल, उसके व्यक्तिगत हैसियत में किए गए कार्यों के लिए","कोई निजी व्यक्ति, संविदा लागू कराने के लिए","कोई लोक प्राधिकारी जो याचिकाकर्ता के प्रति देय वैधानिक कर्तव्य निभाने से इनकार करता है","कोई प्राधिकारी, उसे विशुद्ध विवेकाधीन शक्ति का किसी विशेष तरीके से प्रयोग कराने के लिए"],"explanationHi":"परमादेश लोक विधिक कर्तव्य को लागू कराता है। यह राष्ट्रपति या राज्यपाल के व्यक्तिगत रूप से विरुद्ध (अनुच्छेद 361), निजी व्यक्तियों के विरुद्ध, संविदाएं लागू कराने के लिए, या विवेकाधिकार को निर्देशित करने के लिए जारी नहीं होता।"},
  {"id":"polity-judiciary-130","question":"Consider the following statements about writs: 1. Prohibition can be issued only while proceedings are pending before the lower court or tribunal. 2. Certiorari is not available against legislative bodies or private individuals. 3. Prohibition can be issued against purely administrative authorities. Which of the above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Prohibition is preventive and lies only against judicial or quasi-judicial bodies, so 3 is wrong. Certiorari has been extended to administrative authorities affecting rights, but not to legislatures or private persons.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"रिटों के संबंध में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रतिषेध केवल तभी जारी किया जा सकता है जब अधीनस्थ न्यायालय या अधिकरण के समक्ष कार्यवाही लंबित हो। 2. उत्प्रेषण विधायी निकायों या निजी व्यक्तियों के विरुद्ध उपलब्ध नहीं है। 3. प्रतिषेध विशुद्ध प्रशासनिक प्राधिकारियों के विरुद्ध जारी किया जा सकता है। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"प्रतिषेध निवारक है और केवल न्यायिक या अर्ध-न्यायिक निकायों के विरुद्ध जारी होता है, इसलिए 3 गलत है। उत्प्रेषण को अधिकारों को प्रभावित करने वाले प्रशासनिक प्राधिकारियों तक बढ़ाया गया है, किंतु विधायिकाओं या निजी व्यक्तियों तक नहीं।"},
  {"id":"polity-judiciary-131","question":"In which of these situations will a court NOT issue a writ of habeas corpus?","options":["A person is held by a private individual against his will","A person is held by the police without being produced before a magistrate","A person is held under a preventive detention law without a valid order","A person is jailed for contempt of a court or of a legislature"],"answer":3,"explanation":"Habeas corpus lies even against private detention, but not where the detention is lawful, such as committal for contempt of court or legislature, or detention by a competent court.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इनमें से किस स्थिति में न्यायालय बंदी प्रत्यक्षीकरण रिट जारी नहीं करेगा?","optionsHi":["किसी व्यक्ति को निजी व्यक्ति द्वारा उसकी इच्छा के विरुद्ध रखा गया है","किसी व्यक्ति को पुलिस ने मजिस्ट्रेट के समक्ष प्रस्तुत किए बिना रखा है","किसी व्यक्ति को निवारक निरोध कानून के अंतर्गत वैध आदेश के बिना रखा गया है","किसी व्यक्ति को किसी न्यायालय या विधायिका की अवमानना के लिए कारावास में रखा गया है"],"explanationHi":"बंदी प्रत्यक्षीकरण निजी निरोध के विरुद्ध भी जारी हो सकता है, किंतु वहां नहीं जहां निरोध वैध हो, जैसे न्यायालय या विधायिका की अवमानना के लिए सुपुर्दगी, या सक्षम न्यायालय द्वारा निरोध।"},
  {"id":"polity-judiciary-132","question":"In ADM Jabalpur v. Shivkant Shukla (1976), the majority of the Supreme Court held that:","options":["no detenu could seek habeas corpus, even alleging illegality or mala fides","detenus could still challenge a detention shown to be mala fide or ultra vires the Act","Article 21 itself stood repealed for the duration of the Emergency proclamation","habeas corpus remained available, but only in the Supreme Court under Article 32"],"answer":0,"explanation":"The 4:1 majority closed the courts to detenus; Justice H. R. Khanna dissented. The nine-judge bench in Puttaswamy (2017) declared the majority view overruled.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ADM जबलपुर बनाम शिवकांत शुक्ला (1976) में सर्वोच्च न्यायालय के बहुमत ने क्या निर्णय दिया?","optionsHi":["कोई भी निरुद्ध व्यक्ति बंदी प्रत्यक्षीकरण की मांग नहीं कर सकता, चाहे अवैधता या दुर्भावना का आरोप हो","निरुद्ध व्यक्ति फिर भी ऐसे निरोध को चुनौती दे सकते थे जो दुर्भावनापूर्ण या अधिनियम के अधिकारातीत सिद्ध हो","आपातकाल की उद्घोषणा की अवधि के लिए अनुच्छेद 21 स्वयं निरसित हो गया था","बंदी प्रत्यक्षीकरण उपलब्ध रहा, किंतु केवल अनुच्छेद 32 के अंतर्गत सर्वोच्च न्यायालय में"],"explanationHi":"4:1 के बहुमत ने निरुद्ध व्यक्तियों के लिए न्यायालयों के द्वार बंद कर दिए; न्यायमूर्ति एच. आर. खन्ना ने असहमति जताई। पुट्टास्वामी (2017) में नौ न्यायाधीशों की पीठ ने बहुमत के मत को पलटा हुआ घोषित किया।"},
  {"id":"polity-judiciary-133","question":"Match the doctrine with the case associated with it: A. Doctrine of eclipse B. Doctrine of severability C. No waiver of Fundamental Rights D. Prospective overruling — 1. Basheshar Nath (1959) 2. Golaknath (1967) 3. Bhikaji Narain Dhakras (1955) 4. R. M. D. Chamarbaugwalla (1957)","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":2,"explanation":"Bhikaji Narain held a pre-Constitution law is eclipsed, not dead; RMDC applied severability; Basheshar Nath held Fundamental Rights cannot be waived; Golaknath introduced prospective overruling.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सिद्धांत का मिलान उससे संबद्ध मामले से कीजिए: A. आच्छादन का सिद्धांत (doctrine of eclipse) B. पृथक्करणीयता का सिद्धांत (doctrine of severability) C. मौलिक अधिकारों का अधित्याग नहीं D. भविष्यलक्षी विनिर्णय-उलटाव (prospective overruling) — 1. बशेशर नाथ (1959) 2. गोलकनाथ (1967) 3. भीकाजी नारायण ढाकरस (1955) 4. आर. एम. डी. चमारबागवाला (1957)","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"explanationHi":"भीकाजी नारायण ने माना कि संविधान-पूर्व कानून आच्छादित होता है, मृत नहीं; RMDC ने पृथक्करणीयता लागू की; बशेशर नाथ ने माना कि मौलिक अधिकारों का अधित्याग नहीं किया जा सकता; गोलकनाथ ने भविष्यलक्षी विनिर्णय-उलटाव (prospective overruling) का सिद्धांत प्रतिपादित किया।"},
  {"id":"polity-judiciary-134","question":"Under Article 138, how can the jurisdiction of the Supreme Court be enlarged?","options":["Only by a constitutional amendment passed under Article 368 by special majority","By Parliament by law (Union List), or by Union-State agreement if Parliament allows","By the President by order, after consulting the CJI and the Attorney General","By the Supreme Court itself, through rules of procedure framed under Article 145"],"answer":1,"explanation":"Article 138(1) lets Parliament enlarge jurisdiction on Union List matters; Article 138(2) allows more by special agreement between the Union and a State, if Parliament provides for it by law.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 138 के अंतर्गत, सर्वोच्च न्यायालय के क्षेत्राधिकार का विस्तार कैसे किया जा सकता है?","optionsHi":["केवल अनुच्छेद 368 के अंतर्गत विशेष बहुमत से पारित संवैधानिक संशोधन द्वारा","संसद द्वारा कानून से (संघ सूची), या संसद की अनुमति होने पर संघ और राज्य के बीच समझौते से","राष्ट्रपति द्वारा आदेश से, CJI और महान्यायवादी से परामर्श के बाद","स्वयं सर्वोच्च न्यायालय द्वारा, अनुच्छेद 145 के अंतर्गत बनाए गए प्रक्रिया नियमों से"],"explanationHi":"अनुच्छेद 138(1) संसद को संघ सूची के विषयों पर क्षेत्राधिकार बढ़ाने देता है; अनुच्छेद 138(2) संघ और राज्य के बीच विशेष समझौते से और अधिक विस्तार की अनुमति देता है, यदि संसद कानून द्वारा ऐसा उपबंध करे।"},
  {"id":"polity-judiciary-135","question":"Consider the following statements: 1. Parliament may discuss the conduct of a High Court judge in the discharge of his duties when a motion for his removal is before it. 2. A State legislature may discuss the conduct of a judge of its High Court when an address for his removal is under consideration. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Article 121 allows discussion only on a removal motion. Article 211 bars State legislatures from discussing judges' conduct at all, since they have no role in removing judges.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. जब उच्च न्यायालय के न्यायाधीश को हटाने का प्रस्ताव संसद के समक्ष हो, तब संसद उसके कर्तव्य-निर्वहन में आचरण पर चर्चा कर सकती है। 2. जब उच्च न्यायालय के न्यायाधीश को हटाने का समावेदन विचाराधीन हो, तब राज्य विधानमंडल उस उच्च न्यायालय के न्यायाधीश के आचरण पर चर्चा कर सकता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"अनुच्छेद 121 केवल हटाने के प्रस्ताव पर चर्चा की अनुमति देता है। अनुच्छेद 211 राज्य विधानमंडलों को न्यायाधीशों के आचरण पर चर्चा करने से पूरी तरह रोकता है, क्योंकि उनकी न्यायाधीशों को हटाने में कोई भूमिका नहीं है।"},
  {"id":"polity-judiciary-136","question":"Which Article allows Parliament by law to empower any other court to exercise, within its local limits, the Supreme Court's power to issue writs for enforcing Fundamental Rights?","options":["Article 139","Article 226","Article 138(2)","Article 32(3)"],"answer":3,"explanation":"Article 32(3) lets Parliament confer the Supreme Court's writ powers on other courts. High Courts already have their own writ power under Article 226, Article 138(2) enlarges the Supreme Court's own jurisdiction by agreement, and Article 139 deals with writs for other purposes.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"कौन-सा अनुच्छेद संसद को कानून द्वारा किसी अन्य न्यायालय को, उसकी स्थानीय सीमाओं के भीतर, मौलिक अधिकारों के प्रवर्तन के लिए रिट जारी करने की सर्वोच्च न्यायालय की शक्ति का प्रयोग करने के लिए सशक्त करने देता है?","optionsHi":["अनुच्छेद 139","अनुच्छेद 226","अनुच्छेद 138(2)","अनुच्छेद 32(3)"],"explanationHi":"अनुच्छेद 32(3) संसद को सर्वोच्च न्यायालय की रिट शक्तियां अन्य न्यायालयों को सौंपने देता है। उच्च न्यायालयों की अपनी रिट शक्ति अनुच्छेद 226 के अंतर्गत पहले से है, अनुच्छेद 138(2) समझौते द्वारा सर्वोच्च न्यायालय के अपने क्षेत्राधिकार का विस्तार करता है, और अनुच्छेद 139 अन्य प्रयोजनों के लिए रिटों से संबंधित है।"},
  {"id":"polity-judiciary-137","question":"Consider the following statements about the Contempt of Courts Act, 1971: 1. The maximum punishment is simple imprisonment up to six months, or a fine up to ₹2,000, or both. 2. Since a 2006 amendment, truth can be a valid defence if it is in the public interest and the defence is bona fide. 3. An apology, once tendered, must be accepted and the contemnor discharged. Which of the above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Section 12 sets the punishment and allows discharge on an apology only if the court is satisfied it is bona fide. Section 13 was amended in 2006 to allow justification by truth.","difficulty":"hard","source":"UPSC Prelims","questionHi":"न्यायालय अवमान अधिनियम, 1971 के संबंध में निम्नलिखित कथनों पर विचार कीजिए: 1. अधिकतम दंड छह माह तक का साधारण कारावास, या ₹2,000 तक का जुर्माना, या दोनों है। 2. 2006 के संशोधन के बाद, सत्य एक वैध बचाव हो सकता है यदि वह जनहित में हो और बचाव सद्भावपूर्ण हो। 3. क्षमायाचना, एक बार की जाने पर, स्वीकार की जानी चाहिए और अवमानना करने वाले को मुक्त कर दिया जाना चाहिए। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"धारा 12 दंड निर्धारित करती है और क्षमायाचना पर मुक्ति तभी देती है जब न्यायालय संतुष्ट हो कि वह सद्भावपूर्ण है। धारा 13 को 2006 में संशोधित कर सत्य द्वारा औचित्य सिद्ध करने की अनुमति दी गई।"},
  {"id":"polity-judiciary-138","question":"Assertion (A): The Supreme Court may treat a letter written to it as a writ petition under Article 32. Reason (R): Article 32(1) guarantees the right to move the Court by ‘appropriate proceedings’ and prescribes no particular form for them.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In Bandhua Mukti Morcha (1984) and earlier cases, the Court read ‘appropriate proceedings’ broadly, so a letter could suffice. This is the basis of its epistolary jurisdiction.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): सर्वोच्च न्यायालय अपने नाम लिखे गए पत्र को अनुच्छेद 32 के अंतर्गत रिट याचिका मान सकता है। कारण (R): अनुच्छेद 32(1) ‘समुचित कार्यवाहियों’ द्वारा न्यायालय में जाने के अधिकार की गारंटी देता है और उनके लिए कोई विशेष प्रारूप निर्धारित नहीं करता।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"बंधुआ मुक्ति मोर्चा (1984) और पहले के मामलों में न्यायालय ने ‘समुचित कार्यवाहियों’ का व्यापक अर्थ लिया, इसलिए पत्र पर्याप्त हो सकता है। यही इसके पत्र-क्षेत्राधिकार (epistolary jurisdiction) का आधार है।"},
  {"id":"polity-judiciary-139","question":"After L. Chandra Kumar v. Union of India (1997), an order of the Central Administrative Tribunal is challenged first before:","options":["the Supreme Court directly, by special leave under Article 136","a larger bench of the CAT presided over by its Chairman","a Division Bench of the High Court concerned","the Union Government, on a revision petition under Article 323A"],"answer":2,"explanation":"The Court held tribunals cannot oust the High Courts' power under Articles 226 and 227, so their decisions go first to a Division Bench of the High Court.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एल. चंद्र कुमार बनाम भारत संघ (1997) के बाद, केंद्रीय प्रशासनिक अधिकरण के आदेश को सबसे पहले कहां चुनौती दी जाती है?","optionsHi":["सीधे सर्वोच्च न्यायालय में, अनुच्छेद 136 के अंतर्गत विशेष अनुमति द्वारा","CAT की बड़ी पीठ में, जिसकी अध्यक्षता उसका अध्यक्ष करता है","संबंधित उच्च न्यायालय की खंडपीठ में","केंद्र सरकार के पास, अनुच्छेद 323A के अंतर्गत पुनरीक्षण याचिका द्वारा"],"explanationHi":"न्यायालय ने माना कि अधिकरण अनुच्छेद 226 और 227 के अंतर्गत उच्च न्यायालयों की शक्ति को समाप्त नहीं कर सकते, इसलिए उनके निर्णय पहले उच्च न्यायालय की खंडपीठ के पास जाते हैं।"},
  {"id":"polity-judiciary-140","question":"Under Article 323B, a State legislature can set up a tribunal for which of these matters?","options":["Recruitment and service conditions of Union Government employees","Disputes about the election of the President","Inter-State river water disputes","Rent and tenancy rights"],"answer":3,"explanation":"Article 323B lists matters such as taxation, land reforms, rent and tenancy, and industrial disputes. Public service tribunals under Article 323A can be set up only by Parliament.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"अनुच्छेद 323B के अंतर्गत, राज्य विधानमंडल इनमें से किस विषय के लिए अधिकरण बना सकता है?","optionsHi":["संघ सरकार के कर्मचारियों की भर्ती और सेवा शर्तें","राष्ट्रपति के निर्वाचन संबंधी विवाद","अंतर-राज्यीय नदी जल विवाद","किराया और काश्तकारी अधिकार"],"explanationHi":"अनुच्छेद 323B कराधान, भूमि सुधार, किराया और काश्तकारी तथा औद्योगिक विवाद जैसे विषय सूचीबद्ध करता है। अनुच्छेद 323A के अंतर्गत लोक सेवा अधिकरण केवल संसद बना सकती है।"},
  {"id":"polity-judiciary-141","question":"In 1993 the President referred a question on the Ayodhya dispute to the Supreme Court under Article 143(1). What did the Court do in M. Ismail Faruqui (1994)?","options":["It answered the reference in favour of the Union Government","It respectfully declined to answer the reference","It held the reference was barred by Article 131","It transferred the question to the Allahabad High Court under Article 139A"],"answer":1,"explanation":"Article 143(1) says the Court ‘may’ report its opinion, so it can decline, as it did here. Only references under Article 143(2) must be answered.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1993 में राष्ट्रपति ने अयोध्या विवाद पर एक प्रश्न अनुच्छेद 143(1) के अंतर्गत सर्वोच्च न्यायालय को भेजा। एम. इस्माइल फारूकी (1994) में न्यायालय ने क्या किया?","optionsHi":["उसने संदर्भ का उत्तर केंद्र सरकार के पक्ष में दिया","उसने संदर्भ का उत्तर देने से सविनय इनकार कर दिया","उसने माना कि संदर्भ अनुच्छेद 131 से वर्जित है","उसने प्रश्न अनुच्छेद 139A के अंतर्गत इलाहाबाद उच्च न्यायालय को स्थानांतरित कर दिया"],"explanationHi":"अनुच्छेद 143(1) कहता है कि न्यायालय अपनी राय ‘दे सकता’ है, इसलिए वह इनकार कर सकता है, जैसा उसने यहां किया। केवल अनुच्छेद 143(2) के अंतर्गत संदर्भों का उत्तर देना अनिवार्य है।"},
  {"id":"polity-judiciary-142","question":"In Delhi Judicial Service Association v. State of Gujarat (1991), arising from the assault on a Chief Judicial Magistrate at Nadiad, the Supreme Court held that under Article 129 it can punish contempt:","options":["only of itself, never of any other court","of itself and of the High Courts, but not of subordinate courts","of itself and also of subordinate courts in India","only when the High Court concerned refers the matter to it"],"answer":2,"explanation":"The Court held that its power as a court of record under Article 129 extends to protecting subordinate courts from contempt, since it heads the whole judicial system.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"दिल्ली न्यायिक सेवा संघ बनाम गुजरात राज्य (1991), जो नडियाद में एक मुख्य न्यायिक मजिस्ट्रेट पर हमले से उत्पन्न हुआ, में सर्वोच्च न्यायालय ने माना कि अनुच्छेद 129 के अंतर्गत वह किसकी अवमानना को दंडित कर सकता है?","optionsHi":["केवल अपनी, किसी अन्य न्यायालय की कभी नहीं","अपनी और उच्च न्यायालयों की, किंतु अधीनस्थ न्यायालयों की नहीं","अपनी और भारत के अधीनस्थ न्यायालयों की भी","केवल तब जब संबंधित उच्च न्यायालय मामला उसे भेजे"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 129 के अंतर्गत अभिलेख न्यायालय के रूप में उसकी शक्ति अधीनस्थ न्यायालयों को अवमानना से बचाने तक विस्तृत है, क्योंकि वह संपूर्ण न्यायिक प्रणाली का प्रमुख है।"},
  {"id":"polity-judiciary-143","question":"Calling the Supreme Court a ‘court of record’ means, among other things, that:","options":["its records are conclusive evidence, and it can punish for contempt of itself","it must keep a written record of every case filed in any court anywhere in India","it can hear only those cases in which a full written record of the trial exists","its records and judgments can be amended by Parliament through ordinary law"],"answer":0,"explanation":"Under Article 129, records of a court of record carry evidentiary value and cannot be questioned when produced in any court; the status also carries the power to punish for contempt.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"सर्वोच्च न्यायालय को ‘अभिलेख न्यायालय’ कहने का, अन्य बातों के साथ, अर्थ यह है कि:","optionsHi":["उसके अभिलेख निर्णायक साक्ष्य हैं, और वह अपनी अवमानना के लिए दंड दे सकता है","उसे भारत में कहीं भी किसी भी न्यायालय में दायर प्रत्येक मामले का लिखित अभिलेख रखना होगा","वह केवल उन्हीं मामलों की सुनवाई कर सकता है जिनमें विचारण का पूर्ण लिखित अभिलेख मौजूद हो","उसके अभिलेखों और निर्णयों में संसद साधारण कानून द्वारा संशोधन कर सकती है"],"explanationHi":"अनुच्छेद 129 के अंतर्गत अभिलेख न्यायालय के अभिलेखों का साक्ष्य मूल्य होता है और किसी भी न्यायालय में प्रस्तुत किए जाने पर उन पर प्रश्न नहीं उठाया जा सकता; इस दर्जे के साथ अवमानना के लिए दंड देने की शक्ति भी आती है।"},
  {"id":"polity-judiciary-144","question":"In Mohd. Arif v. Registrar, Supreme Court of India (2014), the Court held that review petitions in cases where the death sentence has been imposed:","options":["must be decided by circulation in chambers like other review petitions","must get an oral hearing in open court before at least three judges","cannot be filed once a curative petition has been dismissed","must be heard by a Constitution Bench of five judges"],"answer":1,"explanation":"Because the right to life is at stake, the Court required a limited oral hearing in open court before a bench of three or more judges. Other review petitions are usually decided by circulation.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मोहम्मद आरिफ बनाम रजिस्ट्रार, भारत का सर्वोच्च न्यायालय (2014) में न्यायालय ने माना कि जिन मामलों में मृत्युदंड दिया गया है उनमें पुनर्विचार याचिकाएं:","optionsHi":["अन्य पुनर्विचार याचिकाओं की तरह चैंबर में सर्कुलेशन द्वारा तय की जानी चाहिए","कम से कम तीन न्यायाधीशों के समक्ष खुले न्यायालय में मौखिक सुनवाई पाएं","उपचारात्मक याचिका खारिज होने के बाद दायर नहीं की जा सकतीं","पांच न्यायाधीशों की संविधान पीठ द्वारा सुनी जानी चाहिए"],"explanationHi":"क्योंकि जीवन का अधिकार दांव पर है, न्यायालय ने तीन या अधिक न्यायाधीशों की पीठ के समक्ष खुले न्यायालय में सीमित मौखिक सुनवाई आवश्यक की। अन्य पुनर्विचार याचिकाएं सामान्यतः सर्कुलेशन द्वारा तय होती हैं।"},
  {"id":"polity-judiciary-145","question":"In Zee Telefilms v. Union of India (2005), the Supreme Court held that the BCCI:","options":["is ‘State’ under Article 12, so a writ petition under Article 32 lies against it","is a private society, so no writ of any kind can ever lie against it","is ‘State’ because the Government controls its finances and its administration","is not ‘State’, but a High Court writ may lie for its public functions"],"answer":3,"explanation":"By 3:2 the Court held the BCCI is not State, so Article 32 was unavailable. Since it discharges public functions, a High Court can still reach it under Article 226.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ज़ी टेलीफिल्म्स बनाम भारत संघ (2005) में सर्वोच्च न्यायालय ने माना कि BCCI:","optionsHi":["अनुच्छेद 12 के अंतर्गत ‘राज्य’ है, इसलिए उसके विरुद्ध अनुच्छेद 32 के अंतर्गत रिट याचिका हो सकती है","एक निजी समिति है, इसलिए उसके विरुद्ध किसी प्रकार की रिट कभी नहीं हो सकती","‘राज्य’ है क्योंकि सरकार उसके वित्त और प्रशासन को नियंत्रित करती है","‘राज्य’ नहीं है, किंतु उसके सार्वजनिक कार्यों के लिए उच्च न्यायालय की रिट हो सकती है"],"explanationHi":"3:2 के बहुमत से न्यायालय ने माना कि BCCI ‘राज्य’ नहीं है, इसलिए अनुच्छेद 32 उपलब्ध नहीं था। चूंकि वह सार्वजनिक कार्य करता है, उच्च न्यायालय अनुच्छेद 226 के अंतर्गत फिर भी उस तक पहुंच सकता है।"},
  {"id":"polity-judiciary-146","question":"Even before PIL relaxed the rule of locus standi, which two writs could be sought by a person who was not personally aggrieved?","options":["Habeas corpus and quo warranto","Prohibition and quo warranto","Habeas corpus and certiorari","Mandamus and certiorari"],"answer":0,"explanation":"Habeas corpus can be sought by anyone on the detenu's behalf, and quo warranto by anyone questioning a usurper's title. The other writs traditionally needed an aggrieved petitioner.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जनहित याचिका द्वारा वाद दायर करने के अधिकार (locus standi) के नियम को शिथिल करने से पहले भी, कौन-सी दो रिटें ऐसा व्यक्ति मांग सकता था जो व्यक्तिगत रूप से पीड़ित नहीं था?","optionsHi":["बंदी प्रत्यक्षीकरण और अधिकार पृच्छा","प्रतिषेध और अधिकार पृच्छा","बंदी प्रत्यक्षीकरण और उत्प्रेषण","परमादेश और उत्प्रेषण"],"explanationHi":"बंदी प्रत्यक्षीकरण कोई भी व्यक्ति निरुद्ध व्यक्ति की ओर से मांग सकता है, और अधिकार पृच्छा कोई भी व्यक्ति अनधिकृत कब्जाधारी के स्वत्व पर प्रश्न उठाते हुए मांग सकता है। अन्य रिटों के लिए परंपरागत रूप से पीड़ित याचिकाकर्ता आवश्यक था।"},
  {"id":"polity-judiciary-147","question":"The number of judges of a High Court is fixed by:","options":["Parliament by law","the Governor of the State, on the High Court's advice","the President","the Chief Justice of India"],"answer":2,"explanation":"Article 216 lets the President appoint as many judges as he deems necessary. For the Supreme Court the number is fixed by Parliament by law (Article 124(1)), the usual trap.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालय के न्यायाधीशों की संख्या कौन निर्धारित करता है?","optionsHi":["संसद, कानून द्वारा","राज्य का राज्यपाल, उच्च न्यायालय की सलाह पर","राष्ट्रपति","भारत के मुख्य न्यायाधीश"],"explanationHi":"अनुच्छेद 216 राष्ट्रपति को उतने न्यायाधीश नियुक्त करने देता है जितने वह आवश्यक समझे। सर्वोच्च न्यायालय के लिए संख्या संसद कानून द्वारा तय करती है (अनुच्छेद 124(1)), जो सामान्य भ्रम है।"},
  {"id":"polity-judiciary-148","question":"Consider the following statements: 1. The Federal Court of India was set up in 1937 under the Government of India Act, 1935. 2. Appeals from Indian courts to the Privy Council were abolished by a law passed in 1949. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The Federal Court began in 1937 and the Abolition of Privy Council Jurisdiction Act came in 1949. The Supreme Court took over both roles from January 1950.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. भारत का संघीय न्यायालय 1937 में भारत शासन अधिनियम, 1935 के अंतर्गत स्थापित किया गया था। 2. भारतीय न्यायालयों से प्रिवी काउंसिल में अपीलें 1949 में पारित एक कानून द्वारा समाप्त की गईं। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"संघीय न्यायालय ने 1937 में कार्य शुरू किया और प्रिवी काउंसिल क्षेत्राधिकार उन्मूलन अधिनियम 1949 में आया। सर्वोच्च न्यायालय ने जनवरी 1950 से दोनों की भूमिकाएं संभालीं।"},
  {"id":"polity-judiciary-149","question":"Consider the following statements about Article 124(2): 1. When appointing a Supreme Court judge other than the Chief Justice, the President must always consult the Chief Justice of India. 2. The Article expressly provides that the senior-most judge shall be appointed Chief Justice of India. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The proviso makes consulting the CJI compulsory. Appointing the senior-most judge as CJI is only a convention, broken in 1973 and 1977, not a text in the Constitution.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 124(2) के संबंध में निम्नलिखित कथनों पर विचार कीजिए: 1. मुख्य न्यायाधीश के अतिरिक्त सर्वोच्च न्यायालय के किसी न्यायाधीश की नियुक्ति करते समय राष्ट्रपति को सदैव भारत के मुख्य न्यायाधीश से परामर्श करना होगा। 2. अनुच्छेद स्पष्ट रूप से उपबंध करता है कि वरिष्ठतम न्यायाधीश को भारत का मुख्य न्यायाधीश नियुक्त किया जाएगा। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"परंतुक CJI से परामर्श अनिवार्य बनाता है। वरिष्ठतम न्यायाधीश को CJI नियुक्त करना केवल एक परंपरा है, जो 1973 और 1977 में तोड़ी गई, संविधान का पाठ नहीं है।"},
  {"id":"polity-judiciary-150","question":"Who was the first Supreme Court judge against whom a removal motion was taken up and put to vote in Parliament?","options":["Justice Dipak Misra","Justice V. Ramaswami","Justice Soumitra Sen","Justice P. D. Dinakaran"],"answer":1,"explanation":"The 1993 motion against Justice V. Ramaswami failed in the Lok Sabha for want of the special majority, as the ruling party abstained. Soumitra Sen and Dinakaran were High Court judges.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय का वह पहला न्यायाधीश कौन था जिसके विरुद्ध हटाने का प्रस्ताव संसद में लिया गया और उस पर मतदान हुआ?","optionsHi":["न्यायमूर्ति दीपक मिश्रा","न्यायमूर्ति वी. रामास्वामी","न्यायमूर्ति सौमित्र सेन","न्यायमूर्ति पी. डी. दिनाकरन"],"explanationHi":"न्यायमूर्ति वी. रामास्वामी के विरुद्ध 1993 का प्रस्ताव लोकसभा में विशेष बहुमत के अभाव में विफल हो गया, क्योंकि सत्तारूढ़ दल मतदान से अनुपस्थित रहा। सौमित्र सेन और दिनाकरन उच्च न्यायालय के न्यायाधीश थे।"},
  {"id":"polity-judiciary-151","question":"A three-judge bench of the Supreme Court disagrees with an earlier judgment of another three-judge bench. What should it do?","options":["Overrule the earlier judgment, since benches of equal strength have equal authority","Follow its own view and leave the conflict for the High Courts to resolve","Seek the President's opinion under Article 143","Refer the matter to a larger bench"],"answer":3,"explanation":"A bench cannot overrule a coordinate bench; it must refer the question to a larger bench (Central Board of Dawoodi Bohra Community, 2005). A larger bench's ruling binds smaller ones.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय की तीन न्यायाधीशों की एक पीठ किसी अन्य तीन न्यायाधीशों की पीठ के पूर्व निर्णय से असहमत है। उसे क्या करना चाहिए?","optionsHi":["पूर्व निर्णय को पलट देना चाहिए, क्योंकि समान संख्या की पीठों का समान अधिकार होता है","अपना मत मानना चाहिए और विरोधाभास को उच्च न्यायालयों के सुलझाने के लिए छोड़ देना चाहिए","अनुच्छेद 143 के अंतर्गत राष्ट्रपति की राय मांगनी चाहिए","मामले को बड़ी पीठ को भेजना चाहिए"],"explanationHi":"कोई पीठ समन्वय पीठ के निर्णय को नहीं पलट सकती; उसे प्रश्न बड़ी पीठ को भेजना होगा (सेंट्रल बोर्ड ऑफ दाऊदी बोहरा कम्युनिटी, 2005)। बड़ी पीठ का निर्णय छोटी पीठों पर बाध्यकारी होता है।"},
  {"id":"polity-judiciary-152","question":"A judgment is said to be ‘per incuriam’ when it is:","options":["delivered by a bench that lacked the required minimum number of judges","made in ignorance of a binding law or precedent, so it does not bind","later overruled by a larger bench, but only with prospective effect","given by a judge who had a personal or pecuniary interest in the case"],"answer":1,"explanation":"A per incuriam decision overlooked a binding law or precedent, so it loses its binding force under Article 141. Bias by a judge makes a decision void on another ground.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कोई निर्णय ‘पर इन्क्यूरियम’ (per incuriam) तब कहा जाता है जब वह:","optionsHi":["ऐसी पीठ द्वारा दिया गया हो जिसमें आवश्यक न्यूनतम संख्या में न्यायाधीश न हों","किसी बाध्यकारी कानून या पूर्व-निर्णय की अनदेखी में दिया गया हो, इसलिए वह बाध्यकारी नहीं होता","बाद में बड़ी पीठ द्वारा पलटा गया हो, किंतु केवल भावी प्रभाव से","ऐसे न्यायाधीश द्वारा दिया गया हो जिसका मामले में व्यक्तिगत या आर्थिक हित था"],"explanationHi":"पर इन्क्यूरियम निर्णय किसी बाध्यकारी कानून या पूर्व-निर्णय की अनदेखी करता है, इसलिए वह अनुच्छेद 141 के अंतर्गत अपनी बाध्यकारी शक्ति खो देता है। न्यायाधीश का पक्षपात निर्णय को किसी अन्य आधार पर शून्य बनाता है।"},
  {"id":"polity-judiciary-153","question":"In Mahesh Chandra Gupta v. Union of India (2009), on challenges to the appointment of High Court judges, the Supreme Court held that:","options":["neither eligibility nor suitability can ever be examined by a court","both eligibility and suitability are fully open to judicial review","eligibility is justiciable as an objective fact, but suitability is not","only the President's satisfaction can be questioned, on the ground of mala fides"],"answer":2,"explanation":"The Court drew this line: whether a person meets Article 217 qualifications can be tested in court; whether he is fit for the post is left to the consultative process.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"महेश चंद्र गुप्ता बनाम भारत संघ (2009) में, उच्च न्यायालय के न्यायाधीशों की नियुक्ति को चुनौती के संबंध में सर्वोच्च न्यायालय ने क्या निर्णय दिया?","optionsHi":["न तो पात्रता और न ही उपयुक्तता की जांच न्यायालय कभी कर सकता है","पात्रता और उपयुक्तता दोनों न्यायिक पुनरावलोकन के लिए पूर्णतः खुली हैं","पात्रता एक वस्तुनिष्ठ तथ्य के रूप में न्यायिक जांच योग्य है, किंतु उपयुक्तता नहीं","केवल राष्ट्रपति की संतुष्टि पर प्रश्न उठाया जा सकता है, दुर्भावना के आधार पर"],"explanationHi":"न्यायालय ने यह रेखा खींची: व्यक्ति अनुच्छेद 217 की योग्यताएं पूरी करता है या नहीं, इसकी जांच न्यायालय में हो सकती है; वह पद के लिए उपयुक्त है या नहीं, यह परामर्श प्रक्रिया पर छोड़ा गया है।"},
  {"id":"polity-judiciary-154","question":"A High Court judge is transferred to another High Court under Article 222. Under clause (2), in addition to salary he is entitled to:","options":["a transfer grant fixed by the Chief Justice of India","no extra amount, since salaries are uniform across High Courts","an allowance fixed by the Governor of the receiving State","a compensatory allowance determined by Parliament by law"],"answer":3,"explanation":"Article 222(2) provides for a compensatory allowance as Parliament determines by law (and, until then, as the President fixes by order).","difficulty":"hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालय के न्यायाधीश का अनुच्छेद 222 के अंतर्गत दूसरे उच्च न्यायालय में स्थानांतरण होता है। खंड (2) के अंतर्गत, वेतन के अतिरिक्त वह किसका हकदार है?","optionsHi":["भारत के मुख्य न्यायाधीश द्वारा निर्धारित स्थानांतरण अनुदान","कुछ नहीं, क्योंकि सभी उच्च न्यायालयों में वेतन समान है","प्राप्तकर्ता राज्य के राज्यपाल द्वारा निर्धारित भत्ता","संसद द्वारा कानून से निर्धारित प्रतिकरात्मक भत्ता"],"explanationHi":"अनुच्छेद 222(2) प्रतिकरात्मक भत्ते का प्रावधान करता है जैसा संसद कानून द्वारा निर्धारित करे (और तब तक जैसा राष्ट्रपति आदेश द्वारा तय करे)।"},
  {"id":"polity-judiciary-155","question":"A judge of a High Court who wishes to resign does so by writing addressed to the:","options":["President","Governor of the State","Chief Justice of the High Court","Chief Justice of India"],"answer":0,"explanation":"Under Article 217(1)(a), a High Court judge resigns to the President, who appoints him. The oath, by contrast, is taken before the Governor.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"उच्च न्यायालय का न्यायाधीश जो त्यागपत्र देना चाहता है, वह किसे संबोधित पत्र द्वारा ऐसा करता है?","optionsHi":["राष्ट्रपति","राज्य के राज्यपाल","उच्च न्यायालय के मुख्य न्यायाधीश","भारत के मुख्य न्यायाधीश"],"explanationHi":"अनुच्छेद 217(1)(a) के अंतर्गत उच्च न्यायालय का न्यायाधीश राष्ट्रपति को त्यागपत्र देता है, जो उसे नियुक्त करता है। इसके विपरीत, शपथ राज्यपाल के समक्ष ली जाती है।"},
  {"id":"polity-judiciary-156","question":"The Directive in Article 50 to separate the judiciary from the executive was given practical effect in criminal courts mainly by:","options":["the 42nd Amendment, which made Article 50 justiciable","the CrPC, 1973, which split judicial from executive magistrates","the Legal Services Authorities Act, 1987, which set up Lok Adalats","the Gram Nyayalayas Act, 2008, which set up village courts"],"answer":1,"explanation":"The 1973 Code placed judicial magistrates under the High Court and confined executive magistrates to preventive and administrative functions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"न्यायपालिका को कार्यपालिका से पृथक करने के अनुच्छेद 50 के निदेशक तत्व को आपराधिक न्यायालयों में व्यावहारिक रूप मुख्यतः किसके द्वारा दिया गया?","optionsHi":["42वें संशोधन ने, जिसने अनुच्छेद 50 को न्यायोचित बनाया","CrPC, 1973 ने, जिसने न्यायिक मजिस्ट्रेटों को कार्यकारी मजिस्ट्रेटों से अलग किया","विधिक सेवा प्राधिकरण अधिनियम, 1987 ने, जिसने लोक अदालतें बनाईं","ग्राम न्यायालय अधिनियम, 2008 ने, जिसने ग्राम न्यायालय बनाए"],"explanationHi":"1973 की संहिता ने न्यायिक मजिस्ट्रेटों को उच्च न्यायालय के अधीन रखा और कार्यकारी मजिस्ट्रेटों को निवारक और प्रशासनिक कार्यों तक सीमित किया।"},
  {"id":"polity-judiciary-157","question":"Consider the following statements: 1. A High Court can issue writs under Article 226 to enforce ordinary legal rights as well as Fundamental Rights. 2. A petition under Article 32 lies only for the enforcement of Fundamental Rights. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Article 226 reaches ‘any other purpose’, so it is wider. Article 32 is limited to Part III rights, though it is itself a Fundamental Right.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. उच्च न्यायालय अनुच्छेद 226 के अंतर्गत मौलिक अधिकारों के साथ-साथ सामान्य कानूनी अधिकारों के प्रवर्तन के लिए भी रिट जारी कर सकता है। 2. अनुच्छेद 32 के अंतर्गत याचिका केवल मौलिक अधिकारों के प्रवर्तन के लिए ही हो सकती है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"अनुच्छेद 226 ‘किसी अन्य प्रयोजन’ तक पहुंचता है, इसलिए वह अधिक व्यापक है। अनुच्छेद 32 भाग III के अधिकारों तक सीमित है, यद्यपि वह स्वयं एक मौलिक अधिकार है।"},
  {"id":"polity-judiciary-158","question":"Consider the following statements: 1. The word ‘collegium’ does not appear anywhere in the Constitution. 2. In the Second Judges case (1993), ‘consultation’ with the Chief Justice of India was read to mean ‘concurrence’. 3. In the First Judges case (1981), the Court gave primacy to the opinion of the Chief Justice of India. Which of the above are correct?","options":["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"S. P. Gupta (1981) gave the executive the final say. The Second Judges case reversed this, and the collegium grew out of judicial interpretation, not the text.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. ‘कॉलेजियम’ शब्द संविधान में कहीं नहीं आता। 2. द्वितीय न्यायाधीश मामले (1993) में भारत के मुख्य न्यायाधीश के साथ ‘परामर्श’ का अर्थ ‘सहमति’ माना गया। 3. प्रथम न्यायाधीश मामले (1981) में न्यायालय ने भारत के मुख्य न्यायाधीश की राय को प्राथमिकता दी। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","1, 2 और 3","केवल 1 और 2"],"explanationHi":"एस. पी. गुप्ता (1981) ने कार्यपालिका को अंतिम निर्णय का अधिकार दिया। द्वितीय न्यायाधीश मामले ने इसे पलट दिया, और कॉलेजियम न्यायिक व्याख्या से उपजा, संविधान के पाठ से नहीं।"},
  {"id":"polity-judiciary-159","question":"Under Article 133(3), unless Parliament by law provides otherwise, an appeal to the Supreme Court does NOT lie from:","options":["a judgment of a single judge of a High Court","a judgment of a Division Bench in a civil case","a High Court judgment certified under Article 134A","a High Court order reversing an acquittal and imposing a death sentence"],"answer":0,"explanation":"Article 133(3) bars appeals from a single judge's decision; such decisions go first to a Division Bench of the High Court. The death-sentence case is an appeal as of right under Article 134.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 133(3) के अंतर्गत, जब तक संसद कानून द्वारा अन्यथा उपबंध न करे, सर्वोच्च न्यायालय में अपील किससे नहीं हो सकती?","optionsHi":["उच्च न्यायालय के एकल न्यायाधीश के निर्णय से","दीवानी मामले में खंडपीठ के निर्णय से","अनुच्छेद 134A के अंतर्गत प्रमाणित उच्च न्यायालय के निर्णय से","उच्च न्यायालय के उस आदेश से जो दोषमुक्ति को पलटकर मृत्युदंड देता है"],"explanationHi":"अनुच्छेद 133(3) एकल न्यायाधीश के निर्णय से अपील को रोकता है; ऐसे निर्णय पहले उच्च न्यायालय की खंडपीठ के पास जाते हैं। मृत्युदंड वाला मामला अनुच्छेद 134 के अंतर्गत अधिकार के रूप में अपील है।"},
  {"id":"polity-judiciary-160","question":"The Supreme Court began with the Chief Justice and seven other judges. The Supreme Court (Number of Judges) Act, 1956, the first such increase, raised the total strength including the Chief Justice to:","options":["8","11","14","18"],"answer":1,"explanation":"The 1956 Act added three judges, for a total of 11. Later laws raised the total to 14 (1960), 18 (1977) and then further.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय की शुरुआत मुख्य न्यायाधीश और सात अन्य न्यायाधीशों से हुई थी। सर्वोच्च न्यायालय (न्यायाधीशों की संख्या) अधिनियम, 1956, जो ऐसी पहली वृद्धि थी, ने मुख्य न्यायाधीश सहित कुल संख्या कितनी की?","optionsHi":["8","11","14","18"],"explanationHi":"1956 के अधिनियम ने तीन न्यायाधीश जोड़े, कुल 11। बाद के कानूनों ने कुल संख्या 14 (1960), 18 (1977) और फिर और अधिक की।"},
  {"id":"polity-judiciary-161","question":"Consider the following statements: 1. Article 32(4) says the right to move the Supreme Court shall not be suspended except as provided by the Constitution. 2. During a National Emergency, the President may suspend the right to move any court for the enforcement of Article 21. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Article 32 can be suspended only through Article 359, and since the 44th Amendment an Article 359 order cannot cover Articles 20 and 21. Statement 2 is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. अनुच्छेद 32(4) कहता है कि सर्वोच्च न्यायालय में जाने का अधिकार निलंबित नहीं किया जाएगा, सिवाय इसके कि संविधान द्वारा अन्यथा उपबंधित हो। 2. राष्ट्रीय आपातकाल के दौरान, राष्ट्रपति अनुच्छेद 21 के प्रवर्तन के लिए किसी भी न्यायालय में जाने का अधिकार निलंबित कर सकता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"अनुच्छेद 32 को केवल अनुच्छेद 359 के माध्यम से निलंबित किया जा सकता है, और 44वें संशोधन के बाद अनुच्छेद 359 का आदेश अनुच्छेद 20 और 21 को कवर नहीं कर सकता। कथन 2 गलत है।"},
  {"id":"polity-judiciary-162","question":"As ‘master of the roster’ in the Supreme Court, who constitutes benches and allocates cases to them?","options":["The collegium of the five senior-most judges","The Registrar General","The full court, by vote","The Chief Justice of India"],"answer":3,"explanation":"The Court has affirmed (in 2017–18 rulings) that the CJI alone holds this administrative power, as first among equals.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"सर्वोच्च न्यायालय में ‘रोस्टर के स्वामी’ (master of the roster) के रूप में, पीठों का गठन और उन्हें मामलों का आवंटन कौन करता है?","optionsHi":["पांच वरिष्ठतम न्यायाधीशों का कॉलेजियम","रजिस्ट्रार जनरल","पूर्ण न्यायालय, मतदान द्वारा","भारत के मुख्य न्यायाधीश"],"explanationHi":"न्यायालय ने (2017–18 के निर्णयों में) पुष्टि की है कि यह प्रशासनिक शक्ति केवल CJI के पास है, जो बराबरी वालों में प्रथम हैं।"},
  {"id":"polity-judiciary-163","question":"In which case did the Supreme Court treat a letter from a prisoner, complaining of torture of a fellow prisoner, as a habeas corpus petition?","options":["Maneka Gandhi v. Union of India","Sunil Batra v. Delhi Administration","Hussainara Khatoon v. State of Bihar","M. C. Mehta v. Union of India"],"answer":1,"explanation":"Sunil Batra (II) (1980) is a landmark of epistolary jurisdiction. Hussainara Khatoon arose from newspaper reports on undertrial prisoners.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने एक कैदी के पत्र को, जिसमें साथी कैदी पर यातना की शिकायत थी, बंदी प्रत्यक्षीकरण याचिका माना?","optionsHi":["मेनका गांधी बनाम भारत संघ","सुनील बत्रा बनाम दिल्ली प्रशासन","हुसैनारा खातून बनाम बिहार राज्य","एम. सी. मेहता बनाम भारत संघ"],"explanationHi":"सुनील बत्रा (II) (1980) पत्र-क्षेत्राधिकार का एक ऐतिहासिक मामला है। हुसैनारा खातून विचाराधीन कैदियों पर समाचार रिपोर्टों से उत्पन्न हुआ था।"},
  {"id":"polity-judiciary-164","question":"Consider the following statements: 1. The administrative expenses of the Supreme Court, including the salaries and pensions of its staff, are charged on the Consolidated Fund of India. 2. Fees collected by the Supreme Court form part of the Consolidated Fund of India. 3. The administrative expenses of a High Court, including staff pensions, are charged on the Consolidated Fund of India. Which of the above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Article 146(3) supports 1 and 2. Under Article 229(3), a High Court's administrative expenses are charged on the State's Consolidated Fund.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. सर्वोच्च न्यायालय के प्रशासनिक व्यय, जिनमें उसके कर्मचारियों के वेतन और पेंशन शामिल हैं, भारत की संचित निधि पर भारित हैं। 2. सर्वोच्च न्यायालय द्वारा एकत्र शुल्क भारत की संचित निधि का हिस्सा हैं। 3. उच्च न्यायालय के प्रशासनिक व्यय, जिनमें कर्मचारियों की पेंशन शामिल है, भारत की संचित निधि पर भारित हैं। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"अनुच्छेद 146(3) कथन 1 और 2 का समर्थन करता है। अनुच्छेद 229(3) के अंतर्गत उच्च न्यायालय के प्रशासनिक व्यय राज्य की संचित निधि पर भारित हैं।"},
  {"id":"polity-judiciary-165","question":"Consider the following statements: 1. India has a single integrated judiciary that enforces both Union and State laws, unlike the dual system of the USA. 2. The High Courts are under the administrative control of the Supreme Court. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The Supreme Court hears appeals from High Courts but does not control them administratively. High Courts are independent constitutional courts and control the subordinate courts themselves.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. भारत में एकल एकीकृत न्यायपालिका है जो संघ और राज्य दोनों के कानूनों को लागू करती है, जो अमेरिका की दोहरी प्रणाली से भिन्न है। 2. उच्च न्यायालय सर्वोच्च न्यायालय के प्रशासनिक नियंत्रण में हैं। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"सर्वोच्च न्यायालय उच्च न्यायालयों से अपीलें सुनता है, किंतु उन पर प्रशासनिक नियंत्रण नहीं रखता। उच्च न्यायालय स्वतंत्र संवैधानिक न्यायालय हैं और अधीनस्थ न्यायालयों पर स्वयं नियंत्रण रखते हैं।"},
  {"id":"polity-judiciary-166","question":"A district judge is called a ‘Sessions Judge’ when he:","options":["sits on the administrative side of the High Court","presides over a Lok Adalat","hears appeals from revenue courts","deals with criminal cases"],"answer":3,"explanation":"The same officer hears civil cases as District Judge and criminal cases as Sessions Judge, with power to try serious offences.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"जिला न्यायाधीश को ‘सत्र न्यायाधीश’ तब कहा जाता है जब वह:","optionsHi":["उच्च न्यायालय के प्रशासनिक पक्ष पर बैठता है","लोक अदालत की अध्यक्षता करता है","राजस्व न्यायालयों से अपीलें सुनता है","आपराधिक मामलों का निपटारा करता है"],"explanationHi":"वही अधिकारी दीवानी मामलों की सुनवाई जिला न्यायाधीश के रूप में और आपराधिक मामलों की सत्र न्यायाधीश के रूप में करता है, जिसे गंभीर अपराधों का विचारण करने की शक्ति है।"},
  {"id":"polity-judiciary-167","question":"In the Cauvery Water Disputes Tribunal reference (1991), what did the Supreme Court say about its advisory jurisdiction under Article 143?","options":["A reference on a matter affecting a State can be made only with that State's consent","The President cannot use Article 143 to have it reconsider a decided question","It is bound to answer every reference made to it under Article 143(1)","A reference may be used to review a decided case if the Union so requests"],"answer":1,"explanation":"The Court held that Article 143 is not an appellate or review power over its own decisions. Nor does the Constitution require any State's consent for a reference.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कावेरी जल विवाद अधिकरण संदर्भ (1991) में, सर्वोच्च न्यायालय ने अनुच्छेद 143 के अंतर्गत अपने परामर्शी क्षेत्राधिकार के बारे में क्या कहा?","optionsHi":["किसी राज्य को प्रभावित करने वाले विषय पर संदर्भ केवल उस राज्य की सहमति से किया जा सकता है","राष्ट्रपति अनुच्छेद 143 का उपयोग किसी तय हो चुके प्रश्न पर पुनर्विचार कराने के लिए नहीं कर सकता","वह अनुच्छेद 143(1) के अंतर्गत उसे भेजे गए प्रत्येक संदर्भ का उत्तर देने के लिए बाध्य है","यदि संघ अनुरोध करे तो संदर्भ का उपयोग किसी तय हो चुके मामले के पुनर्विलोकन के लिए किया जा सकता है"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 143 अपने निर्णयों पर अपीलीय या पुनर्विलोकन की शक्ति नहीं है। न ही संविधान संदर्भ के लिए किसी राज्य की सहमति आवश्यक करता है।"},
  {"id":"polity-judiciary-168","question":"In Union Carbide Corporation v. Union of India (1991), upholding the Bhopal gas settlement, the Supreme Court said of its power under Article 142 that:","options":["Ordinary statutory limits do not bind it, though it must respect fundamental public policy","It can be used only in criminal appeals and never in civil disputes between parties","It is subject to every provision of the Code of Civil Procedure, like any civil court's power","It can be exercised only on a reference made by the President under Article 143"],"answer":0,"explanation":"The Court held that prohibitions or limitations in ordinary laws do not as such limit its power under Article 142 to do complete justice, provided it does not contravene fundamental principles of public policy; on that basis it upheld the settlement.","difficulty":"hard","source":"UPSC Prelims","questionHi":"यूनियन कार्बाइड कॉर्पोरेशन बनाम भारत संघ (1991) में, भोपाल गैस समझौते को बरकरार रखते हुए, सर्वोच्च न्यायालय ने अनुच्छेद 142 की अपनी शक्ति के बारे में क्या कहा?","optionsHi":["साधारण वैधानिक सीमाएं उसे बाध्य नहीं करतीं, किंतु उसे मूलभूत लोकनीति का सम्मान करना होगा","इसका प्रयोग केवल आपराधिक अपीलों में हो सकता है, पक्षों के बीच दीवानी विवादों में कभी नहीं","यह सिविल प्रक्रिया संहिता के प्रत्येक प्रावधान के अधीन है, जैसे किसी दीवानी न्यायालय की शक्ति","इसका प्रयोग केवल अनुच्छेद 143 के अंतर्गत राष्ट्रपति के संदर्भ पर किया जा सकता है"],"explanationHi":"न्यायालय ने माना कि साधारण कानूनों में निषेध या सीमाएं स्वयं अनुच्छेद 142 के अंतर्गत पूर्ण न्याय करने की उसकी शक्ति को सीमित नहीं करतीं, बशर्ते वह लोकनीति के मूलभूत सिद्धांतों का उल्लंघन न करे; इसी आधार पर उसने समझौते को बरकरार रखा।"},
  {"id":"polity-judiciary-169","question":"In Supreme Court Bar Association v. Union of India (1998), the Court reviewed its earlier order in In re Vinay Chandra Mishra (1995), which had suspended an advocate's licence to practise for contempt. It held that:","options":["Article 129 lets the Court suspend an advocate's licence whenever it finds him guilty of contempt","Article 142 cannot supplant substantive law, so suspending a licence is for the Bar Council","Only Parliament, by a resolution of both Houses, can suspend an advocate's licence to practise","An advocate guilty of contempt can be punished only by the High Court where he is enrolled"],"answer":1,"explanation":"The Court held that Article 142 cannot be used to ignore express statutory provisions; suspending a licence for professional misconduct is for the Bar Council under the Advocates Act, though the Court may punish for contempt and bar the advocate from appearing before it until he purges the contempt.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सुप्रीम कोर्ट बार एसोसिएशन बनाम भारत संघ (1998) में न्यायालय ने इन री विनय चंद्र मिश्रा (1995) में अपने पूर्व आदेश का पुनर्विलोकन किया, जिसमें अवमानना के लिए एक अधिवक्ता का वकालत का लाइसेंस निलंबित किया गया था। उसने माना कि:","optionsHi":["अनुच्छेद 129 न्यायालय को किसी अधिवक्ता को अवमानना का दोषी पाने पर उसका लाइसेंस निलंबित करने देता है","अनुच्छेद 142 मूल कानून का स्थान नहीं ले सकता, इसलिए लाइसेंस निलंबित करना बार काउंसिल का काम है","केवल संसद, दोनों सदनों के संकल्प द्वारा, अधिवक्ता का वकालत का लाइसेंस निलंबित कर सकती है","अवमानना का दोषी अधिवक्ता केवल उस उच्च न्यायालय द्वारा दंडित किया जा सकता है जहां वह पंजीकृत है"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 142 का उपयोग स्पष्ट वैधानिक प्रावधानों की अनदेखी के लिए नहीं हो सकता; व्यावसायिक कदाचार के लिए लाइसेंस निलंबित करना अधिवक्ता अधिनियम के अंतर्गत बार काउंसिल का काम है, यद्यपि न्यायालय अवमानना के लिए दंड दे सकता है और अवमानना की शुद्धि तक अधिवक्ता को अपने समक्ष उपस्थित होने से रोक सकता है।"},
  {"id":"polity-judiciary-170","question":"In K. Veeraswami v. Union of India (1991), a former Chief Justice of a High Court was prosecuted for having assets beyond his known income. The Supreme Court held that:","options":["Judges of superior courts are immune from criminal prosecution, since only Parliament can remove them","A judge can be prosecuted only after Parliament has passed a removal motion against him","Judges are public servants under the anti-corruption law, but cases need the CJI's consultation","The anti-corruption law applies only to subordinate judges and not to High Court judges"],"answer":2,"explanation":"The majority held that High Court and Supreme Court judges are public servants under the Prevention of Corruption Act, 1947, but directed that no criminal case be registered against such a judge without first consulting the Chief Justice of India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"के. वीरास्वामी बनाम भारत संघ (1991) में, एक उच्च न्यायालय के पूर्व मुख्य न्यायाधीश पर ज्ञात आय से अधिक संपत्ति रखने का अभियोग चलाया गया। सर्वोच्च न्यायालय ने माना कि:","optionsHi":["उच्चतर न्यायालयों के न्यायाधीश आपराधिक अभियोजन से मुक्त हैं, क्योंकि केवल संसद उन्हें हटा सकती है","न्यायाधीश पर अभियोजन तभी चल सकता है जब संसद उसके विरुद्ध हटाने का प्रस्ताव पारित कर चुकी हो","न्यायाधीश भ्रष्टाचार-रोधी कानून के अंतर्गत लोक सेवक हैं, किंतु मामलों में CJI से परामर्श आवश्यक है","भ्रष्टाचार-रोधी कानून केवल अधीनस्थ न्यायाधीशों पर लागू होता है, उच्च न्यायालय के न्यायाधीशों पर नहीं"],"explanationHi":"बहुमत ने माना कि उच्च न्यायालय और सर्वोच्च न्यायालय के न्यायाधीश भ्रष्टाचार निवारण अधिनियम, 1947 के अंतर्गत लोक सेवक हैं, किंतु निर्देश दिया कि भारत के मुख्य न्यायाधीश से पहले परामर्श किए बिना ऐसे न्यायाधीश के विरुद्ध कोई आपराधिक मामला दर्ज न किया जाए।"},
  {"id":"polity-judiciary-171","question":"In C. Ravichandran Iyer v. Justice A. M. Bhattacharjee (1995), a Bar association had passed resolutions demanding a High Court Chief Justice's resignation. The Supreme Court:","options":["Upheld the Bar's right to force a judge to resign by boycotting his court indefinitely","Held that only Parliament may ever examine the conduct of a sitting High Court judge","Directed the Chief Justice of the High Court to resign within a period of thirty days","Held such resolutions improper and called for an in-house procedure for misconduct"],"answer":3,"explanation":"The Court held that Bar associations cannot coerce a judge into resigning, and that conduct falling short of impeachable misbehaviour needs an in-house procedure through the Chief Justices; the Supreme Court adopted such a procedure in 1999.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सी. रविचंद्रन अय्यर बनाम न्यायमूर्ति ए. एम. भट्टाचार्जी (1995) में एक बार एसोसिएशन ने एक उच्च न्यायालय के मुख्य न्यायाधीश के त्यागपत्र की मांग करते हुए संकल्प पारित किए थे। सर्वोच्च न्यायालय ने:","optionsHi":["बार के उस अधिकार को बरकरार रखा कि वह किसी न्यायाधीश के न्यायालय का अनिश्चितकालीन बहिष्कार करके उसे त्यागपत्र के लिए बाध्य कर सकता है","माना कि केवल संसद ही कभी किसी पदासीन उच्च न्यायालय न्यायाधीश के आचरण की जांच कर सकती है","उच्च न्यायालय के मुख्य न्यायाधीश को तीस दिन के भीतर त्यागपत्र देने का निर्देश दिया","ऐसे संकल्पों को अनुचित माना और कदाचार के लिए आंतरिक प्रक्रिया की आवश्यकता बताई"],"explanationHi":"न्यायालय ने माना कि बार एसोसिएशन किसी न्यायाधीश को त्यागपत्र के लिए बाध्य नहीं कर सकते, और महाभियोग योग्य कदाचार से कम के आचरण के लिए मुख्य न्यायाधीशों के माध्यम से आंतरिक प्रक्रिया चाहिए; सर्वोच्च न्यायालय ने 1999 में ऐसी प्रक्रिया अपनाई।"},
  {"id":"polity-judiciary-172","question":"The Tribunals Reforms Act, 2021 abolished several appellate bodies and transferred their work to courts. Which of these was abolished by it?","options":["Intellectual Property Appellate Board","National Company Law Appellate Tribunal","Armed Forces Tribunal","Central Administrative Tribunal"],"answer":0,"explanation":"The Act abolished bodies such as the Intellectual Property Appellate Board, the Film Certification Appellate Tribunal and the Airport Appellate Tribunal, shifting their work mainly to the High Courts. The NCLAT, AFT and CAT continue, with only their service conditions now governed by the Act.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अधिकरण सुधार अधिनियम, 2021 ने कई अपीलीय निकायों को समाप्त कर उनका कार्य न्यायालयों को सौंप दिया। इनमें से कौन-सा उसके द्वारा समाप्त किया गया?","optionsHi":["बौद्धिक संपदा अपीलीय बोर्ड","राष्ट्रीय कंपनी विधि अपीलीय अधिकरण","सशस्त्र बल अधिकरण","केंद्रीय प्रशासनिक अधिकरण"],"explanationHi":"अधिनियम ने बौद्धिक संपदा अपीलीय बोर्ड, फिल्म प्रमाणन अपीलीय अधिकरण और विमानपत्तन अपीलीय अधिकरण जैसे निकायों को समाप्त किया, और उनका कार्य मुख्यतः उच्च न्यायालयों को सौंपा। NCLAT, AFT और CAT जारी हैं, और अब केवल उनकी सेवा शर्तें इस अधिनियम से शासित होती हैं।"},
  {"id":"polity-judiciary-173","question":"In Prakash Singh v. Union of India (2006), the Supreme Court issued directions on police reform. Which of these was among them?","options":["Merging all State police forces into one national police under the Union","Setting up a State Security Commission and a Police Establishment Board","Placing every police station under the direct control of the district judge","Electing the Director General of Police by the State Legislative Assembly"],"answer":1,"explanation":"The Court directed States to set up State Security Commissions, Police Establishment Boards and Police Complaints Authorities, give the DGP and field officers a minimum tenure, and separate investigation from law and order duties.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रकाश सिंह बनाम भारत संघ (2006) में सर्वोच्च न्यायालय ने पुलिस सुधार पर निर्देश जारी किए। इनमें से कौन-सा उनमें शामिल था?","optionsHi":["सभी राज्य पुलिस बलों को संघ के अधीन एक राष्ट्रीय पुलिस में मिला देना","राज्य सुरक्षा आयोग और पुलिस स्थापना बोर्ड की स्थापना","प्रत्येक पुलिस थाने को जिला न्यायाधीश के सीधे नियंत्रण में रखना","राज्य विधान सभा द्वारा पुलिस महानिदेशक का निर्वाचन"],"explanationHi":"न्यायालय ने राज्यों को राज्य सुरक्षा आयोग, पुलिस स्थापना बोर्ड और पुलिस शिकायत प्राधिकरण स्थापित करने, DGP और क्षेत्रीय अधिकारियों को न्यूनतम कार्यकाल देने, तथा जांच को कानून-व्यवस्था के कर्तव्यों से अलग करने का निर्देश दिया।"},
  {"id":"polity-judiciary-174","question":"In State of Uttaranchal v. Balwant Singh Chaufal (2010), the Supreme Court addressed public interest litigation. What did it do?","options":["It abolished PIL and restored the strict rule that only an aggrieved person may sue","It held that PIL can be filed only by registered NGOs and not by individuals","It laid down guidelines to encourage genuine PILs and to curb frivolous or motivated ones","It held that a PIL may be filed only in the Supreme Court, and never before any High Court of a State"],"answer":2,"explanation":"Tracing the history of PIL, the Court asked High Courts to frame rules for PIL, to check the petitioner's credentials and bona fides, and to impose costs on petitions filed for oblique motives, while keeping PIL open for genuine causes.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उत्तरांचल राज्य बनाम बलवंत सिंह चौफाल (2010) में सर्वोच्च न्यायालय ने जनहित याचिका पर विचार किया। उसने क्या किया?","optionsHi":["उसने जनहित याचिका समाप्त कर दी और यह कठोर नियम बहाल किया कि केवल पीड़ित व्यक्ति ही वाद दायर कर सकता है","उसने माना कि जनहित याचिका केवल पंजीकृत NGO दायर कर सकते हैं, व्यक्ति नहीं","उसने वास्तविक जनहित याचिकाओं को प्रोत्साहित करने और तुच्छ या प्रेरित याचिकाओं पर अंकुश लगाने के लिए दिशानिर्देश बनाए","उसने माना कि जनहित याचिका केवल सर्वोच्च न्यायालय में दायर हो सकती है, किसी राज्य के उच्च न्यायालय में कभी नहीं"],"explanationHi":"जनहित याचिका के इतिहास का अनुसरण करते हुए, न्यायालय ने उच्च न्यायालयों से जनहित याचिका के लिए नियम बनाने, याचिकाकर्ता की साख और सद्भावना की जांच करने, तथा अप्रत्यक्ष उद्देश्यों से दायर याचिकाओं पर जुर्माना लगाने को कहा, साथ ही वास्तविक मुद्दों के लिए जनहित याचिका खुली रखी।"},
  {"id":"polity-judiciary-175","question":"In Central Public Information Officer, Supreme Court of India v. Subhash Chandra Agarwal (2019), a Constitution Bench held that:","options":["The judiciary is wholly outside the Right to Information Act to protect its independence","Judges' assets may be disclosed only with the consent of Parliament given by resolution","Only the Registry is covered by the RTI Act, and the Chief Justice's office is not","The office of the Chief Justice of India is a public authority under the RTI Act"],"answer":3,"explanation":"The Court held that the office of the CJI is part of the Supreme Court, a public authority under the RTI Act, so information such as judges' asset declarations can be disclosed, subject to the Act's exemptions; transparency and judicial independence go together.","difficulty":"hard","source":"UPSC Prelims","questionHi":"केंद्रीय लोक सूचना अधिकारी, भारत का सर्वोच्च न्यायालय बनाम सुभाष चंद्र अग्रवाल (2019) में संविधान पीठ ने क्या निर्णय दिया?","optionsHi":["न्यायपालिका अपनी स्वतंत्रता की रक्षा के लिए सूचना का अधिकार अधिनियम से पूर्णतः बाहर है","न्यायाधीशों की संपत्ति का खुलासा केवल संसद की सहमति से, संकल्प द्वारा, हो सकता है","केवल रजिस्ट्री RTI अधिनियम के अंतर्गत आती है, मुख्य न्यायाधीश का कार्यालय नहीं","भारत के मुख्य न्यायाधीश का कार्यालय RTI अधिनियम के अंतर्गत एक लोक प्राधिकरण है"],"explanationHi":"न्यायालय ने माना कि CJI का कार्यालय सर्वोच्च न्यायालय का हिस्सा है, जो RTI अधिनियम के अंतर्गत एक लोक प्राधिकरण है, इसलिए न्यायाधीशों की संपत्ति की घोषणा जैसी जानकारी अधिनियम की छूटों के अधीन प्रकट की जा सकती है; पारदर्शिता और न्यायिक स्वतंत्रता साथ-साथ चलती हैं।"},
  {"id":"polity-judiciary-176","question":"In Swapnil Tripathi v. Supreme Court of India (2018), the Supreme Court accepted in principle:","options":["Live-streaming of hearings in cases of national importance","Conducting all of its hearings in Hindi instead of English","Allowing television cameras into judges' deliberations in chambers","Announcing each judge's vote in open court before writing judgments"],"answer":0,"explanation":"The Court held that live-streaming of proceedings, beginning with cases of constitutional and national importance, furthers open justice and access to justice; Constitution Bench hearings began to be streamed in 2022.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"स्वप्निल त्रिपाठी बनाम भारत का सर्वोच्च न्यायालय (2018) में सर्वोच्च न्यायालय ने सैद्धांतिक रूप से क्या स्वीकार किया?","optionsHi":["राष्ट्रीय महत्व के मामलों में सुनवाई का सीधा प्रसारण (लाइव-स्ट्रीमिंग)","अपनी सभी सुनवाइयां अंग्रेजी के स्थान पर हिंदी में करना","चैंबर में न्यायाधीशों के विचार-विमर्श में टेलीविजन कैमरों को अनुमति देना","निर्णय लिखने से पहले खुले न्यायालय में प्रत्येक न्यायाधीश के मत की घोषणा करना"],"explanationHi":"न्यायालय ने माना कि कार्यवाही का सीधा प्रसारण, जो संवैधानिक और राष्ट्रीय महत्व के मामलों से शुरू हो, खुले न्याय और न्याय तक पहुंच को बढ़ावा देता है; संविधान पीठ की सुनवाइयों का प्रसारण 2022 में शुरू हुआ।"},
  {"id":"polity-judiciary-177","question":"In P. Sambamurthy v. State of Andhra Pradesh (1987), the Supreme Court struck down the proviso to Article 371D(5), which let the State government modify or annul orders of the State Administrative Tribunal. Why?","options":["Because Article 371D was inserted without ratification by half the States","Because letting the executive override a tribunal's decision violates the rule of law","Because administrative tribunals may be set up only by Parliament under Article 323A itself","Because the proviso conflicted with the directive in Article 50 and nothing else"],"answer":1,"explanation":"The Court held that letting the government, itself a party, set aside the tribunal's decisions offended the rule of law and effective judicial review, both basic features, so the proviso fell even though it had been added by a constitutional amendment.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पी. संबमूर्ति बनाम आंध्र प्रदेश राज्य (1987) में, सर्वोच्च न्यायालय ने अनुच्छेद 371D(5) के उस परंतुक को रद्द कर दिया जो राज्य सरकार को राज्य प्रशासनिक अधिकरण के आदेशों को बदलने या रद्द करने देता था। ऐसा क्यों?","optionsHi":["क्योंकि अनुच्छेद 371D आधे राज्यों के अनुसमर्थन के बिना जोड़ा गया था","क्योंकि कार्यपालिका को अधिकरण के निर्णय को पलटने देना विधि के शासन का उल्लंघन है","क्योंकि प्रशासनिक अधिकरण केवल संसद ही अनुच्छेद 323A के अंतर्गत बना सकती है","क्योंकि परंतुक अनुच्छेद 50 के निदेशक तत्व से टकराता था, और किसी अन्य कारण से नहीं"],"explanationHi":"न्यायालय ने माना कि स्वयं पक्षकार सरकार को अधिकरण के निर्णयों को रद्द करने देना विधि के शासन और प्रभावी न्यायिक पुनरावलोकन, जो दोनों मूल ढांचे के अंग हैं, का उल्लंघन है, इसलिए परंतुक रद्द हो गया, भले ही उसे संवैधानिक संशोधन द्वारा जोड़ा गया था।"},
  {"id":"polity-judiciary-178","question":"In Union of India v. R. Gandhi, President, Madras Bar Association (2010), on the National Company Law Tribunal, the Supreme Court held that:","options":["Parliament can never move any part of the jurisdiction of the High Courts to tribunals at all","Tribunals may be staffed entirely by civil servants if Parliament so decides by law","Tribunals replacing courts must have judicial members and independence like those courts","The NCLT is unconstitutional because company law falls in the State List"],"answer":2,"explanation":"The Court upheld Parliament's power to create the NCLT and its appellate tribunal, but held that a tribunal taking over court work must keep judicial independence and standards, and struck down provisions on qualifications and selection that fell short.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत संघ बनाम आर. गांधी, अध्यक्ष, मद्रास बार एसोसिएशन (2010) में, राष्ट्रीय कंपनी विधि अधिकरण के संबंध में, सर्वोच्च न्यायालय ने क्या निर्णय दिया?","optionsHi":["संसद उच्च न्यायालयों के क्षेत्राधिकार का कोई भी भाग अधिकरणों को कभी नहीं सौंप सकती","यदि संसद कानून द्वारा ऐसा तय करे तो अधिकरणों में पूर्णतः सिविल सेवक नियुक्त किए जा सकते हैं","न्यायालयों का स्थान लेने वाले अधिकरणों में न्यायिक सदस्य और उन न्यायालयों जैसी स्वतंत्रता होनी चाहिए","NCLT असंवैधानिक है क्योंकि कंपनी कानून राज्य सूची में आता है"],"explanationHi":"न्यायालय ने NCLT और उसके अपीलीय अधिकरण को बनाने की संसद की शक्ति को बरकरार रखा, किंतु माना कि न्यायालय का कार्य संभालने वाले अधिकरण को न्यायिक स्वतंत्रता और मानक बनाए रखने चाहिए, और योग्यता तथा चयन से संबंधित उन प्रावधानों को रद्द कर दिया जो इस कसौटी पर खरे नहीं उतरे।"},
  {"id":"polity-judiciary-179","question":"The Judicial Standards and Accountability Bill, 2010, which proposed a National Judicial Oversight Council to examine complaints against judges, finally:","options":["Became law in 2012 and replaced the Judges (Inquiry) Act, 1968","Was struck down by the Supreme Court along with the NJAC Act","Became law but was never notified in the Gazette by the Union government","Lapsed on the dissolution of the 15th Lok Sabha without being enacted"],"answer":3,"explanation":"The Lok Sabha passed the Bill in 2012, but it lapsed when the 15th Lok Sabha was dissolved in 2014 before the Rajya Sabha could pass it; the Judges (Inquiry) Act, 1968 still governs removal inquiries.","difficulty":"hard","source":"UPSC Prelims","questionHi":"न्यायिक मानक और जवाबदेही विधेयक, 2010, जिसमें न्यायाधीशों के विरुद्ध शिकायतों की जांच के लिए राष्ट्रीय न्यायिक निरीक्षण परिषद का प्रस्ताव था, अंततः:","optionsHi":["2012 में कानून बना और उसने न्यायाधीश (जांच) अधिनियम, 1968 का स्थान लिया","NJAC अधिनियम के साथ सर्वोच्च न्यायालय द्वारा रद्द कर दिया गया","कानून बना, किंतु केंद्र सरकार द्वारा राजपत्र में कभी अधिसूचित नहीं किया गया","बिना अधिनियमित हुए 15वीं लोकसभा के भंग होने पर व्यपगत हो गया"],"explanationHi":"लोकसभा ने विधेयक 2012 में पारित किया, किंतु राज्यसभा द्वारा पारित किए जाने से पहले 2014 में 15वीं लोकसभा के भंग होने पर यह व्यपगत हो गया; हटाने की जांच अब भी न्यायाधीश (जांच) अधिनियम, 1968 से शासित होती है।"},
  {"id":"polity-judiciary-180","question":"The ‘Restatement of Values of Judicial Life’, a code of conduct for judges, was adopted by:","options":["A full court meeting of the Supreme Court in 1997","Parliament through an amendment to the Judges (Inquiry) Act","The Bar Council of India under the Advocates Act, 1961","The Law Commission in a report on judicial reforms in 2008"],"answer":0,"explanation":"The full court of the Supreme Court adopted the Restatement in May 1997, and a Chief Justices' Conference endorsed it in 1999. It is a self-regulatory code, not a law.","difficulty":"hard","source":"UPSC Prelims","questionHi":"न्यायाधीशों की आचार संहिता ‘न्यायिक जीवन के मूल्यों का पुनर्कथन’ (Restatement of Values of Judicial Life) किसके द्वारा अपनाई गई?","optionsHi":["1997 में सर्वोच्च न्यायालय की पूर्ण न्यायालय बैठक द्वारा","संसद द्वारा, न्यायाधीश (जांच) अधिनियम में संशोधन के माध्यम से","बार काउंसिल ऑफ इंडिया द्वारा, अधिवक्ता अधिनियम, 1961 के अंतर्गत","विधि आयोग द्वारा, 2008 में न्यायिक सुधारों पर एक रिपोर्ट में"],"explanationHi":"सर्वोच्च न्यायालय की पूर्ण न्यायालय ने मई 1997 में पुनर्कथन अपनाया, और मुख्य न्यायाधीशों के एक सम्मेलन ने 1999 में उसका समर्थन किया। यह एक स्व-नियामक संहिता है, कानून नहीं।"},
  {"id":"polity-judiciary-181","question":"In Indira Jaising v. Supreme Court of India (2017), the Supreme Court laid down a system for designating senior advocates. What did it create?","options":["A rule that every advocate becomes senior after 20 years of practice","A permanent committee, headed by the Chief Justice, using a points-based assessment","An election by the Bar Council of India from among all enrolled advocates","A written examination for the senior title, to be conducted by the Supreme Court itself"],"answer":1,"explanation":"The Court set up a Permanent Committee for Designation of Senior Advocates, chaired by the CJI with two senior judges, the Attorney General and a member of the Bar, to assess candidates on a points system before the full court decides.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"इंदिरा जयसिंह बनाम भारत का सर्वोच्च न्यायालय (2017) में सर्वोच्च न्यायालय ने वरिष्ठ अधिवक्ता नामित करने की एक प्रणाली निर्धारित की। उसने क्या बनाया?","optionsHi":["यह नियम कि प्रत्येक अधिवक्ता 20 वर्ष की वकालत के बाद वरिष्ठ बन जाता है","मुख्य न्यायाधीश की अध्यक्षता में एक स्थायी समिति, जो अंक-आधारित मूल्यांकन का उपयोग करती है","बार काउंसिल ऑफ इंडिया द्वारा सभी पंजीकृत अधिवक्ताओं में से चुनाव","वरिष्ठ की उपाधि के लिए लिखित परीक्षा, जो स्वयं सर्वोच्च न्यायालय द्वारा आयोजित हो"],"explanationHi":"न्यायालय ने वरिष्ठ अधिवक्ता नामित करने के लिए एक स्थायी समिति बनाई, जिसकी अध्यक्षता CJI करते हैं और जिसमें दो वरिष्ठ न्यायाधीश, महान्यायवादी और बार का एक सदस्य होता है; यह पूर्ण न्यायालय के निर्णय से पहले अंक प्रणाली पर अभ्यर्थियों का मूल्यांकन करती है।"},
  {"id":"polity-judiciary-182","question":"Since the 54th Amendment (1986), how are the salaries of Supreme Court and High Court judges fixed?","options":["By an order of the President issued after consulting the Chief Justice of India","Only by a constitutional amendment to the Second Schedule each time","By Parliament by law, with the Second Schedule applying until such law is made","By the Finance Commission in its report once every five years"],"answer":2,"explanation":"The 54th Amendment changed Articles 125 and 221 so that judges' salaries are determined by Parliament by law, the Second Schedule figures applying only until then. Salaries cannot be varied to a judge's disadvantage after appointment, except in a Financial Emergency.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"54वें संशोधन (1986) के बाद से सर्वोच्च न्यायालय और उच्च न्यायालयों के न्यायाधीशों के वेतन कैसे निर्धारित होते हैं?","optionsHi":["भारत के मुख्य न्यायाधीश से परामर्श के बाद जारी राष्ट्रपति के आदेश द्वारा","हर बार केवल दूसरी अनुसूची में संवैधानिक संशोधन द्वारा","संसद द्वारा कानून से, और ऐसा कानून बनने तक दूसरी अनुसूची लागू रहती है","वित्त आयोग द्वारा, हर पांच वर्ष में अपनी रिपोर्ट में"],"explanationHi":"54वें संशोधन ने अनुच्छेद 125 और 221 को बदला ताकि न्यायाधीशों के वेतन संसद कानून द्वारा निर्धारित करे, और दूसरी अनुसूची के आंकड़े तभी तक लागू रहें। नियुक्ति के बाद न्यायाधीश के प्रतिकूल वेतन में परिवर्तन नहीं हो सकता, वित्तीय आपातकाल को छोड़कर।"},
  {"id":"polity-judiciary-183","question":"In Pritam Singh v. The State (1950), one of its earliest judgments, the Supreme Court explained how it would use the power under Article 136 to grant special leave in criminal cases. It said it would:","options":["Grant leave in every case where a sentence of imprisonment has been imposed","Re-examine the evidence in every appeal as if it were the trial court","Grant leave only where the High Court has certified the case as fit","Interfere only in exceptional cases, where grave injustice has been done"],"answer":3,"explanation":"The Court held that Article 136 gives a wide discretion to be used sparingly and only in exceptional cases, such as where substantial and grave injustice has been done; it is not a regular appeal against every conviction, and no High Court certificate is needed.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"प्रीतम सिंह बनाम राज्य (1950), जो उसके शुरुआती निर्णयों में से एक है, में सर्वोच्च न्यायालय ने बताया कि वह आपराधिक मामलों में विशेष अनुमति देने के लिए अनुच्छेद 136 की शक्ति का उपयोग कैसे करेगा। उसने कहा कि वह:","optionsHi":["हर उस मामले में अनुमति देगा जहां कारावास का दंड दिया गया हो","प्रत्येक अपील में साक्ष्य की पुनः जांच करेगा, मानो वह विचारण न्यायालय हो","केवल वहीं अनुमति देगा जहां उच्च न्यायालय ने मामले को उपयुक्त प्रमाणित किया हो","केवल असाधारण मामलों में हस्तक्षेप करेगा, जहां गंभीर अन्याय हुआ हो"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 136 व्यापक विवेकाधिकार देता है जिसका प्रयोग संयम से और केवल असाधारण मामलों में किया जाना चाहिए, जैसे जहां सारवान और गंभीर अन्याय हुआ हो; यह हर दोषसिद्धि के विरुद्ध नियमित अपील नहीं है, और उच्च न्यायालय के प्रमाणपत्र की आवश्यकता नहीं है।"},
  {"id":"polity-judiciary-184","question":"How many of these Supreme Court decisions were given on a Presidential reference under Article 143? I. The Third Judges case (1998) on the collegium II. In re Keshav Singh (1965) on legislative privilege III. The opinion on allocation of natural resources (2012) IV. Kesavananda Bharati v. State of Kerala (1973)","options":["Only three","Only two","All four","Only one"],"answer":0,"explanation":"The Third Judges case, Keshav Singh and the 2012 opinion on natural resources (sought after the 2G judgment) were all references under Article 143(1). Kesavananda was decided on writ petitions under Article 32.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय के इनमें से कितने निर्णय अनुच्छेद 143 के अंतर्गत राष्ट्रपति के संदर्भ पर दिए गए? I. कॉलेजियम पर तृतीय न्यायाधीश मामला (1998) II. विधायी विशेषाधिकार पर इन री केशव सिंह (1965) III. प्राकृतिक संसाधनों के आवंटन पर राय (2012) IV. केशवानंद भारती बनाम केरल राज्य (1973)","optionsHi":["केवल तीन","केवल दो","सभी चार","केवल एक"],"explanationHi":"तृतीय न्यायाधीश मामला, केशव सिंह और प्राकृतिक संसाधनों पर 2012 की राय (2G निर्णय के बाद मांगी गई) सभी अनुच्छेद 143(1) के अंतर्गत संदर्भ थे। केशवानंद का निर्णय अनुच्छेद 32 के अंतर्गत रिट याचिकाओं पर हुआ।"},
  {"id":"polity-judiciary-185","question":"In its 2012 opinion on the allocation of natural resources, given after the 2G spectrum judgment, the Supreme Court said that:","options":["Auction is the only constitutionally permissible way to allocate any natural resource at all","Auction is not a constitutional mandate for every resource, though allocation must be fair","Allocation of natural resources is a policy matter wholly outside judicial review","Only Parliament, by a resolution of both Houses, may allocate natural resources"],"answer":1,"explanation":"The Court held that auction is not constitutionally required for all natural resources; whatever method is chosen must be fair, non-arbitrary and for the common good under Articles 14 and 39(b), and remains open to judicial review.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2G स्पेक्ट्रम निर्णय के बाद दी गई प्राकृतिक संसाधनों के आवंटन पर अपनी 2012 की राय में सर्वोच्च न्यायालय ने कहा कि:","optionsHi":["नीलामी किसी भी प्राकृतिक संसाधन के आवंटन का एकमात्र संवैधानिक रूप से अनुमत तरीका है","नीलामी प्रत्येक संसाधन के लिए संवैधानिक आदेश नहीं है, यद्यपि आवंटन निष्पक्ष होना चाहिए","प्राकृतिक संसाधनों का आवंटन नीति का विषय है जो पूर्णतः न्यायिक पुनरावलोकन से बाहर है","केवल संसद, दोनों सदनों के संकल्प द्वारा, प्राकृतिक संसाधनों का आवंटन कर सकती है"],"explanationHi":"न्यायालय ने माना कि सभी प्राकृतिक संसाधनों के लिए नीलामी संवैधानिक रूप से अपेक्षित नहीं है; जो भी तरीका चुना जाए वह अनुच्छेद 14 और 39(b) के अंतर्गत निष्पक्ष, मनमानी रहित और सामान्य हित में होना चाहिए, और न्यायिक पुनरावलोकन के लिए खुला रहता है।"},
  {"id":"polity-judiciary-186","question":"How many of these statements about increases in the strength of the Supreme Court, counting the Chief Justice, are correct? I. It rose to 14 in 1960. II. It rose to 26 in 1986. III. It rose to 31 in 2009.","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Through amendments to the Supreme Court (Number of Judges) Act, 1956 the strength went from 11 (1956) to 14 (1960), 18 (1977), 26 (1986), 31 (2009) and 34 (2019), so all three are correct.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मुख्य न्यायाधीश सहित सर्वोच्च न्यायालय की संख्या में वृद्धि के संबंध में इनमें से कितने कथन सही हैं? I. 1960 में यह बढ़कर 14 हो गई। II. 1986 में यह बढ़कर 26 हो गई। III. 2009 में यह बढ़कर 31 हो गई।","optionsHi":["केवल एक","केवल दो","सभी तीन","इनमें से कोई नहीं"],"explanationHi":"सर्वोच्च न्यायालय (न्यायाधीशों की संख्या) अधिनियम, 1956 में संशोधनों के माध्यम से संख्या 11 (1956) से 14 (1960), 18 (1977), 26 (1986), 31 (2009) और 34 (2019) हुई, इसलिए तीनों सही हैं।"},
  {"id":"polity-judiciary-187","question":"In Andi Mukta Sadguru Trust v. V. R. Rudani (1989), teachers of a college run by a private trust sought their unpaid dues. The Supreme Court held that a writ of mandamus:","options":["Can never issue to a private trust, which must be sued in a civil court","Can issue only if the trust has first been declared ‘State’ under Article 12","Can issue only to bodies created by a statute and not to registered trusts","Can issue to any body performing a public duty, even a private trust"],"answer":3,"explanation":"The Court held that ‘any person or authority’ in Article 226 is wider than ‘State’ in Article 12, so mandamus can issue to a private body performing a public duty such as running an aided college.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आंदी मुक्ता सद्गुरु ट्रस्ट बनाम वी. आर. रुदानी (1989) में, एक निजी ट्रस्ट द्वारा संचालित कॉलेज के शिक्षकों ने अपने बकाया वेतन की मांग की। सर्वोच्च न्यायालय ने माना कि परमादेश रिट:","optionsHi":["निजी ट्रस्ट के विरुद्ध कभी जारी नहीं हो सकती, उस पर दीवानी न्यायालय में वाद करना होगा","केवल तभी जारी हो सकती है जब ट्रस्ट को पहले अनुच्छेद 12 के अंतर्गत ‘राज्य’ घोषित किया गया हो","केवल कानून द्वारा बनाई गई संस्थाओं के विरुद्ध जारी हो सकती है, पंजीकृत ट्रस्टों के विरुद्ध नहीं","किसी भी ऐसी संस्था के विरुद्ध जारी हो सकती है जो सार्वजनिक कर्तव्य निभाती हो, चाहे वह निजी ट्रस्ट हो"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 226 में ‘कोई भी व्यक्ति या प्राधिकारी’ अनुच्छेद 12 के ‘राज्य’ से व्यापक है, इसलिए परमादेश किसी ऐसी निजी संस्था के विरुद्ध जारी हो सकती है जो सार्वजनिक कर्तव्य निभाती हो, जैसे सहायता प्राप्त कॉलेज चलाना।"},
  {"id":"polity-judiciary-188","question":"In Radhey Shyam v. Chhabi Nath (2015), a three-judge bench of the Supreme Court overruled part of Surya Dev Rai (2003). It held that judicial orders of civil courts:","options":["Are not open to writs under Article 226, but can be corrected under Article 227","Can be quashed by certiorari under Article 226 like the orders of any tribunal","Can be challenged only by special leave in the Supreme Court under Article 136","Are final, and no High Court may correct them under any Article of the Constitution"],"answer":0,"explanation":"The bench held that judicial orders of civil courts are not amenable to certiorari under Article 226, since such courts are not authorities to be corrected by writ, but the High Court's supervisory jurisdiction under Article 227 remains available.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"राधेश्याम बनाम छबि नाथ (2015) में सर्वोच्च न्यायालय की तीन न्यायाधीशों की पीठ ने सूर्य देव राय (2003) के एक भाग को पलट दिया। उसने माना कि दीवानी न्यायालयों के न्यायिक आदेश:","optionsHi":["अनुच्छेद 226 के अंतर्गत रिट के लिए खुले नहीं हैं, किंतु अनुच्छेद 227 के अंतर्गत सुधारे जा सकते हैं","किसी भी अधिकरण के आदेशों की तरह अनुच्छेद 226 के अंतर्गत उत्प्रेषण द्वारा रद्द किए जा सकते हैं","केवल अनुच्छेद 136 के अंतर्गत सर्वोच्च न्यायालय में विशेष अनुमति द्वारा चुनौती दिए जा सकते हैं","अंतिम हैं, और कोई उच्च न्यायालय संविधान के किसी भी अनुच्छेद के अंतर्गत उन्हें सुधार नहीं सकता"],"explanationHi":"पीठ ने माना कि दीवानी न्यायालयों के न्यायिक आदेश अनुच्छेद 226 के अंतर्गत उत्प्रेषण के योग्य नहीं हैं, क्योंकि ऐसे न्यायालय रिट द्वारा सुधारे जाने वाले प्राधिकारी नहीं हैं, किंतु अनुच्छेद 227 के अंतर्गत उच्च न्यायालय का पर्यवेक्षी क्षेत्राधिकार उपलब्ध रहता है।"},
  {"id":"polity-judiciary-189","question":"In Bandhua Mukti Morcha v. Union of India (1984), the State objected to the Supreme Court appointing commissioners to inquire into bonded labour in stone quarries. The Court held that under Article 32 it:","options":["Can act only on affidavits and cannot gather facts through its own commissioners","Can appoint commissioners to find facts, as Article 32 is not tied to adversarial procedure","Can appoint commissioners only if the State government concerned first agrees to their appointment","Must send all fact-finding to the High Court of the State concerned in such cases"],"answer":1,"explanation":"Justice Bhagwati held that Article 32 prescribes no particular procedure, so in PIL the Court may appoint socio-legal commissions to gather facts; their reports serve as evidence, open to objection by the parties.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बंधुआ मुक्ति मोर्चा बनाम भारत संघ (1984) में, राज्य ने पत्थर की खदानों में बंधुआ मजदूरी की जांच के लिए सर्वोच्च न्यायालय द्वारा आयुक्त नियुक्त करने पर आपत्ति की। न्यायालय ने माना कि अनुच्छेद 32 के अंतर्गत वह:","optionsHi":["केवल शपथपत्रों पर कार्य कर सकता है और अपने आयुक्तों द्वारा तथ्य एकत्र नहीं कर सकता","तथ्य खोजने के लिए आयुक्त नियुक्त कर सकता है, क्योंकि अनुच्छेद 32 प्रतिपक्षी प्रक्रिया से बंधा नहीं है","आयुक्त केवल तभी नियुक्त कर सकता है जब संबंधित राज्य सरकार पहले उनकी नियुक्ति के लिए सहमत हो","ऐसे मामलों में सभी तथ्य-खोज संबंधित राज्य के उच्च न्यायालय को भेजनी होगी"],"explanationHi":"न्यायमूर्ति भगवती ने माना कि अनुच्छेद 32 कोई विशेष प्रक्रिया निर्धारित नहीं करता, इसलिए जनहित याचिका में न्यायालय तथ्य एकत्र करने के लिए सामाजिक-विधिक आयोग नियुक्त कर सकता है; उनकी रिपोर्टें साक्ष्य के रूप में काम करती हैं, जिन पर पक्ष आपत्ति कर सकते हैं।"},
  {"id":"polity-judiciary-190","question":"In Kanu Sanyal v. District Magistrate, Darjeeling (1974), the Supreme Court considered whether a writ of habeas corpus requires the detenu to be physically produced in court. It held that:","options":["Physical production of the body is an essential condition of every habeas corpus writ","Habeas corpus can issue only from the High Court within whose limits the person is held","Production of the body is not essential to decide the legality of the detention","Habeas corpus cannot be issued once the detenu has been moved to another State"],"answer":2,"explanation":"The Court held that the essence of habeas corpus is an inquiry into the legality of detention; bringing the person physically before the court is not indispensable, and the court may decide on the record.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कनु सान्याल बनाम जिला मजिस्ट्रेट, दार्जिलिंग (1974) में सर्वोच्च न्यायालय ने विचार किया कि क्या बंदी प्रत्यक्षीकरण रिट के लिए निरुद्ध व्यक्ति को न्यायालय में भौतिक रूप से प्रस्तुत करना आवश्यक है। उसने माना कि:","optionsHi":["शरीर को भौतिक रूप से प्रस्तुत करना प्रत्येक बंदी प्रत्यक्षीकरण रिट की आवश्यक शर्त है","बंदी प्रत्यक्षीकरण केवल उसी उच्च न्यायालय से जारी हो सकता है जिसकी सीमाओं में व्यक्ति रखा गया है","निरोध की वैधता तय करने के लिए शरीर को प्रस्तुत करना आवश्यक नहीं है","निरुद्ध व्यक्ति को किसी अन्य राज्य में स्थानांतरित कर दिए जाने के बाद बंदी प्रत्यक्षीकरण जारी नहीं हो सकता"],"explanationHi":"न्यायालय ने माना कि बंदी प्रत्यक्षीकरण का सार निरोध की वैधता की जांच है; व्यक्ति को भौतिक रूप से न्यायालय के समक्ष लाना अनिवार्य नहीं है, और न्यायालय अभिलेख के आधार पर निर्णय कर सकता है।"},
  {"id":"polity-judiciary-191","question":"In In re Arundhati Roy (2002), the Supreme Court held the writer guilty of contempt over statements in her reply to an earlier contempt notice. What sentence did it impose?","options":["Six months' simple imprisonment with no option of a fine","A ban on publishing any writing about the courts for a year","A fine of ₹1 only, with no term of imprisonment at all","Simple imprisonment for one day and a fine of ₹2,000"],"answer":3,"explanation":"Holding that her affidavit scandalised the Court, it imposed a symbolic one day's simple imprisonment and a fine of ₹2,000, with three months' imprisonment in default. The ₹1 fine was the 2020 Prashant Bhushan case.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"इन री अरुंधति रॉय (2002) में सर्वोच्च न्यायालय ने लेखिका को पहले के अवमानना नोटिस के उत्तर में दिए गए उनके कथनों के लिए अवमानना का दोषी ठहराया। उसने कौन-सा दंड दिया?","optionsHi":["छह माह का साधारण कारावास, जुर्माने के विकल्प के बिना","न्यायालयों के बारे में एक वर्ष तक कोई लेख प्रकाशित करने पर प्रतिबंध","केवल ₹1 का जुर्माना, कारावास बिल्कुल नहीं","एक दिन का साधारण कारावास और ₹2,000 का जुर्माना"],"explanationHi":"यह मानते हुए कि उनके शपथपत्र ने न्यायालय की प्रतिष्ठा को ठेस पहुंचाई, उसने एक दिन के साधारण कारावास का प्रतीकात्मक दंड और ₹2,000 का जुर्माना लगाया, जो न चुकाने पर तीन माह का कारावास था। ₹1 का जुर्माना 2020 के प्रशांत भूषण मामले में था।"},
  {"id":"polity-judiciary-192","question":"In 2017 a seven-judge bench of the Supreme Court sentenced Justice C. S. Karnan of the Calcutta High Court for contempt. What was notable about this?","options":["He was the first sitting High Court judge jailed for contempt of court","He was removed from office by Parliament on the same day as the sentence","The Court ordered his removal from office using its power under Article 142","The President pardoned him before the sentence could be carried out"],"answer":0,"explanation":"The bench sentenced him to six months' imprisonment, the first such punishment of a sitting High Court judge. It could not remove him, since removal needs the parliamentary process under Articles 124(4) and 218.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2017 में सर्वोच्च न्यायालय की सात न्यायाधीशों की पीठ ने कलकत्ता उच्च न्यायालय के न्यायमूर्ति सी. एस. कर्णन को अवमानना के लिए दंडित किया। इसमें उल्लेखनीय क्या था?","optionsHi":["वह अवमानना के लिए जेल भेजे जाने वाले पहले पदासीन उच्च न्यायालय न्यायाधीश थे","संसद ने उसी दिन उन्हें पद से हटा दिया जिस दिन दंड दिया गया","न्यायालय ने अनुच्छेद 142 की अपनी शक्ति का प्रयोग कर उन्हें पद से हटाने का आदेश दिया","राष्ट्रपति ने दंड पूरा होने से पहले उन्हें क्षमा कर दिया"],"explanationHi":"पीठ ने उन्हें छह माह के कारावास की सजा दी, जो किसी पदासीन उच्च न्यायालय न्यायाधीश को ऐसा पहला दंड था। वह उन्हें हटा नहीं सकती थी, क्योंकि हटाने के लिए अनुच्छेद 124(4) और 218 के अंतर्गत संसदीय प्रक्रिया आवश्यक है।"},
  {"id":"polity-judiciary-193","question":"Which Chief Justice of India resigned in 1967 to contest the election to the office of President?","options":["M. Hidayatullah","K. Subba Rao","P. B. Gajendragadkar","A. K. Sarkar"],"answer":1,"explanation":"Chief Justice K. Subba Rao, who wrote the majority judgment in Golaknath, resigned in April 1967 to contest the presidential election, which Zakir Husain won. Hidayatullah later acted as President in 1969 while he was CJI.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"भारत के किन मुख्य न्यायाधीश ने 1967 में राष्ट्रपति पद का चुनाव लड़ने के लिए त्यागपत्र दिया?","optionsHi":["एम. हिदायतुल्ला","के. सुब्बा राव","पी. बी. गजेंद्रगडकर","ए. के. सरकार"],"explanationHi":"मुख्य न्यायाधीश के. सुब्बा राव, जिन्होंने गोलकनाथ में बहुमत का निर्णय लिखा था, ने अप्रैल 1967 में राष्ट्रपति चुनाव लड़ने के लिए त्यागपत्र दिया, जिसे ज़ाकिर हुसैन ने जीता। हिदायतुल्ला ने बाद में 1969 में, जब वे CJI थे, कार्यवाहक राष्ट्रपति के रूप में कार्य किया।"},
  {"id":"polity-judiciary-194","question":"In All India Judges' Association v. Union of India (1993), the Supreme Court gave directions on the service conditions of the subordinate judiciary. Which of these was among them?","options":["Abolishing the posts of civil judge, leaving only district judges","Placing subordinate judges under the State Law Department's control","Raising the retirement age of judicial officers to 60 years","Requiring all subordinate judges to be recruited through the UPSC"],"answer":2,"explanation":"The Court directed a retirement age of 60 for judicial officers, subject to assessment of their fitness, and separate service conditions, which led to the First National Judicial Pay Commission under Justice K. J. Shetty.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अखिल भारतीय न्यायाधीश संघ बनाम भारत संघ (1993) में सर्वोच्च न्यायालय ने अधीनस्थ न्यायपालिका की सेवा शर्तों पर निर्देश दिए। इनमें से कौन-सा उनमें शामिल था?","optionsHi":["सिविल जज के पद समाप्त करना, केवल जिला न्यायाधीश रखना","अधीनस्थ न्यायाधीशों को राज्य विधि विभाग के नियंत्रण में रखना","न्यायिक अधिकारियों की सेवानिवृत्ति की आयु 60 वर्ष करना","सभी अधीनस्थ न्यायाधीशों की भर्ती UPSC के माध्यम से अनिवार्य करना"],"explanationHi":"न्यायालय ने न्यायिक अधिकारियों के लिए उनकी उपयुक्तता के मूल्यांकन के अधीन 60 वर्ष की सेवानिवृत्ति आयु और पृथक सेवा शर्तों का निर्देश दिया, जिसके कारण न्यायमूर्ति के. जे. शेट्टी की अध्यक्षता में प्रथम राष्ट्रीय न्यायिक वेतन आयोग बना।"},
  {"id":"polity-judiciary-195","question":"In S. P. Gupta v. Union of India (1981), the government claimed privilege over its correspondence with the Chief Justice of India and others about the appointment and transfer of judges. The Supreme Court:","options":["Upheld the claim, holding such correspondence absolutely privileged","Held that only the President could decide whether to disclose it","Referred the question to Parliament under its rules on privileges","Rejected the claim and ordered disclosure, citing open government"],"answer":3,"explanation":"The Court held that the right to know flows from Article 19(1)(a) and disclosure is the rule; privilege applies only where disclosure would really harm the public interest, which was not shown, so the correspondence was disclosed.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"एस. पी. गुप्ता बनाम भारत संघ (1981) में, सरकार ने न्यायाधीशों की नियुक्ति और स्थानांतरण के बारे में भारत के मुख्य न्यायाधीश और अन्य के साथ अपने पत्राचार पर विशेषाधिकार का दावा किया। सर्वोच्च न्यायालय ने:","optionsHi":["दावे को बरकरार रखा, यह मानते हुए कि ऐसा पत्राचार पूर्णतः विशेषाधिकार प्राप्त है","माना कि केवल राष्ट्रपति ही तय कर सकता है कि उसे प्रकट किया जाए या नहीं","प्रश्न को विशेषाधिकारों संबंधी अपने नियमों के अंतर्गत संसद को भेज दिया","दावे को अस्वीकार कर खुली सरकार का हवाला देते हुए प्रकटीकरण का आदेश दिया"],"explanationHi":"न्यायालय ने माना कि जानने का अधिकार अनुच्छेद 19(1)(a) से उत्पन्न होता है और प्रकटीकरण नियम है; विशेषाधिकार केवल वहीं लागू होता है जहां प्रकटीकरण से लोकहित को वास्तव में हानि हो, जो सिद्ध नहीं हुआ, इसलिए पत्राचार प्रकट किया गया।"},
  {"id":"polity-judiciary-196","question":"In Special Reference No. 1 of 1964 (the Keshav Singh case), the Uttar Pradesh Assembly had ordered two High Court judges to be brought before it for granting bail to a man it had jailed for contempt. The Supreme Court opined that:","options":["The High Court could hear the habeas corpus plea, and the Assembly could not punish its judges","The Assembly's privilege under Article 194(3) is absolute and is beyond review by any court of law","Only the Supreme Court, and not a High Court, may examine a committal by a legislature","The Assembly could punish the judges but not the advocate who had filed the petition"],"answer":0,"explanation":"The Court held that legislative privileges are subject to the Constitution, so the High Court could entertain a habeas corpus petition against a committal by the House, and the judges who did so were not guilty of contempt of the Assembly.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"विशेष संदर्भ संख्या 1 ऑफ 1964 (केशव सिंह मामला) में, उत्तर प्रदेश विधान सभा ने दो उच्च न्यायालय न्यायाधीशों को अपने समक्ष लाने का आदेश दिया, क्योंकि उन्होंने ऐसे व्यक्ति को जमानत दी थी जिसे उसने अवमानना के लिए जेल भेजा था। सर्वोच्च न्यायालय ने राय दी कि:","optionsHi":["उच्च न्यायालय बंदी प्रत्यक्षीकरण की याचिका सुन सकता था, और विधान सभा उसके न्यायाधीशों को दंडित नहीं कर सकती थी","अनुच्छेद 194(3) के अंतर्गत विधान सभा का विशेषाधिकार निरपेक्ष है और किसी भी न्यायालय की समीक्षा से परे है","केवल सर्वोच्च न्यायालय ही, उच्च न्यायालय नहीं, विधायिका द्वारा की गई सुपुर्दगी की जांच कर सकता है","विधान सभा न्यायाधीशों को दंडित कर सकती थी, किंतु याचिका दायर करने वाले अधिवक्ता को नहीं"],"explanationHi":"न्यायालय ने माना कि विधायी विशेषाधिकार संविधान के अधीन हैं, इसलिए उच्च न्यायालय सदन द्वारा की गई सुपुर्दगी के विरुद्ध बंदी प्रत्यक्षीकरण याचिका स्वीकार कर सकता था, और ऐसा करने वाले न्यायाधीश विधान सभा की अवमानना के दोषी नहीं थे।"},
  {"id":"polity-judiciary-197","question":"Which of these has the Supreme Court held is NOT part of the basic structure of the Constitution?","options":["Judicial review under Articles 32 and 226","The right to property under Article 300A","Free and fair elections","Independence of the judiciary"],"answer":1,"explanation":"In Jilubhai Nanbhai Khachar (1995) the Court held that the right to property under Article 300A is not part of the basic structure. Judicial review (Minerva Mills, L. Chandra Kumar), free and fair elections (Indira Gandhi v. Raj Narain) and judicial independence (the NJAC case) are.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय ने इनमें से किसे संविधान के मूल ढांचे का हिस्सा नहीं माना है?","optionsHi":["अनुच्छेद 32 और 226 के अंतर्गत न्यायिक पुनरावलोकन","अनुच्छेद 300A के अंतर्गत संपत्ति का अधिकार","स्वतंत्र और निष्पक्ष चुनाव","न्यायपालिका की स्वतंत्रता"],"explanationHi":"जिलुभाई नानभाई खाचर (1995) में न्यायालय ने माना कि अनुच्छेद 300A के अंतर्गत संपत्ति का अधिकार मूल ढांचे का हिस्सा नहीं है। न्यायिक पुनरावलोकन (मिनर्वा मिल्स, एल. चंद्र कुमार), स्वतंत्र और निष्पक्ष चुनाव (इंदिरा गांधी बनाम राज नारायण) और न्यायिक स्वतंत्रता (NJAC मामला) हैं।"},
  {"id":"polity-judiciary-198","question":"In State of Rajasthan v. Union of India (1977), several States challenged the Union government's move to have their Assemblies dissolved after the Lok Sabha elections. The Supreme Court:","options":["Struck down the dissolutions as mala fide and restored all the dissolved State Assemblies at once","Held that a State can never sue the Union under Article 131 on such a matter","Dismissed the suits, declining to interfere with the President's satisfaction under Article 356","Referred the dispute to the Inter-State Council under Article 263 for its decision"],"answer":2,"explanation":"The Court entertained the suits under Article 131 but dismissed them, holding that it could not interfere with the President's satisfaction on the facts shown. S. R. Bommai (1994) later widened judicial review of Article 356.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"राजस्थान राज्य बनाम भारत संघ (1977) में, कई राज्यों ने लोकसभा चुनावों के बाद अपनी विधान सभाओं को भंग कराने के केंद्र सरकार के कदम को चुनौती दी। सर्वोच्च न्यायालय ने:","optionsHi":["भंग करने को दुर्भावनापूर्ण मानकर रद्द कर दिया और सभी भंग विधान सभाओं को तुरंत बहाल कर दिया","माना कि राज्य ऐसे विषय पर अनुच्छेद 131 के अंतर्गत संघ पर कभी वाद नहीं कर सकता","वादों को खारिज कर दिया, अनुच्छेद 356 के अंतर्गत राष्ट्रपति की संतुष्टि में हस्तक्षेप करने से इनकार करते हुए","विवाद को निर्णय के लिए अनुच्छेद 263 के अंतर्गत अंतर-राज्यीय परिषद को भेज दिया"],"explanationHi":"न्यायालय ने अनुच्छेद 131 के अंतर्गत वाद स्वीकार किए किंतु उन्हें खारिज कर दिया, यह मानते हुए कि वह दिखाए गए तथ्यों पर राष्ट्रपति की संतुष्टि में हस्तक्षेप नहीं कर सकता। एस. आर. बोम्मई (1994) ने बाद में अनुच्छेद 356 के न्यायिक पुनरावलोकन का विस्तार किया।"},
  {"id":"polity-judiciary-199","question":"How many of these were done by the Supreme Court invoking Article 142? I. Directing the allotment of five acres for a mosque in the Ayodhya judgment (2019) II. Declaring the right to privacy a fundamental right (2017) III. Holding that it may dissolve a marriage on the ground of irretrievable breakdown (2023) IV. Striking down the 99th Amendment on judicial appointments (2015)","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III rested on the power to do complete justice under Article 142. The privacy ruling (Puttaswamy) interpreted Articles 14, 19 and 21, and the NJAC ruling was judicial review of an amendment, not Article 142.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कार्य सर्वोच्च न्यायालय ने अनुच्छेद 142 का आह्वान करके किए? I. अयोध्या निर्णय (2019) में मस्जिद के लिए पांच एकड़ भूमि के आवंटन का निर्देश II. निजता के अधिकार को मौलिक अधिकार घोषित करना (2017) III. यह मानना कि वह अपूरणीय विघटन के आधार पर विवाह विच्छेद कर सकता है (2023) IV. न्यायिक नियुक्तियों पर 99वें संशोधन को रद्द करना (2015)","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III पूर्ण न्याय करने की अनुच्छेद 142 की शक्ति पर आधारित थे। निजता का निर्णय (पुट्टास्वामी) अनुच्छेद 14, 19 और 21 की व्याख्या था, और NJAC का निर्णय एक संशोधन का न्यायिक पुनरावलोकन था, अनुच्छेद 142 नहीं।"},
  {"id":"polity-judiciary-200","question":"In K. Ashok Reddy v. Government of India (1994), on transfers of High Court judges under Article 222, the Supreme Court held that:","options":["No High Court judge can be transferred without first obtaining his own written consent","Every transfer must first be approved by a resolution of both Houses of Parliament","A transfer is punitive in nature, so an inquiry must be held before it is made","Judicial review is confined to whether the transfer followed the CJI's recommendation"],"answer":3,"explanation":"Following the Second Judges case, the Court held that transfers are made in the public interest on the recommendation of the CJI after due consultation, so judicial review is limited to whether that procedure was followed; the judge's consent is not needed.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"के. अशोक रेड्डी बनाम भारत सरकार (1994) में, अनुच्छेद 222 के अंतर्गत उच्च न्यायालय के न्यायाधीशों के स्थानांतरण के संबंध में, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["किसी उच्च न्यायालय न्यायाधीश का स्थानांतरण उसकी अपनी लिखित सहमति प्राप्त किए बिना नहीं हो सकता","प्रत्येक स्थानांतरण को पहले संसद के दोनों सदनों के संकल्प द्वारा अनुमोदित किया जाना चाहिए","स्थानांतरण दंडात्मक स्वरूप का है, इसलिए उससे पहले जांच होनी चाहिए","न्यायिक पुनरावलोकन इस बात तक सीमित है कि स्थानांतरण CJI की सिफारिश के अनुसार हुआ या नहीं"],"explanationHi":"द्वितीय न्यायाधीश मामले के बाद, न्यायालय ने माना कि स्थानांतरण जनहित में CJI की उचित परामर्श के बाद की गई सिफारिश पर होते हैं, इसलिए न्यायिक पुनरावलोकन इस बात तक सीमित है कि वह प्रक्रिया अपनाई गई या नहीं; न्यायाधीश की सहमति आवश्यक नहीं है।"},
  {"id":"polity-judiciary-201","question":"ADM Jabalpur v. Shivkant Shukla (1976), which had denied habeas corpus during the Emergency, was expressly declared wrongly decided and overruled in:","options":["K. S. Puttaswamy v. Union of India (2017)","Maneka Gandhi v. Union of India (1978)","Minerva Mills Ltd. v. Union of India (1980)","S. R. Bommai v. Union of India (1994)"],"answer":0,"explanation":"The nine-judge bench in Puttaswamy (2017) held that ADM Jabalpur was seriously flawed and expressly overruled it, affirming that life and personal liberty are inalienable. The 44th Amendment had earlier barred suspension of Articles 20 and 21.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"ADM जबलपुर बनाम शिवकांत शुक्ला (1976), जिसने आपातकाल के दौरान बंदी प्रत्यक्षीकरण से इनकार किया था, को किस मामले में स्पष्ट रूप से गलत तय किया गया घोषित कर पलटा गया?","optionsHi":["के. एस. पुट्टास्वामी बनाम भारत संघ (2017)","मेनका गांधी बनाम भारत संघ (1978)","मिनर्वा मिल्स लिमिटेड बनाम भारत संघ (1980)","एस. आर. बोम्मई बनाम भारत संघ (1994)"],"explanationHi":"पुट्टास्वामी (2017) में नौ न्यायाधीशों की पीठ ने माना कि ADM जबलपुर गंभीर रूप से त्रुटिपूर्ण था और उसे स्पष्ट रूप से पलट दिया, यह पुष्टि करते हुए कि जीवन और व्यक्तिगत स्वतंत्रता अहस्तांतरणीय हैं। 44वें संशोधन ने पहले ही अनुच्छेद 20 और 21 के निलंबन को रोक दिया था।"},
  {"id":"polity-judiciary-202","question":"Under the Supreme Court Rules, who alone is entitled to file an appearance and act for a party in the Supreme Court?","options":["Any Senior Advocate designated by the Court","An Advocate-on-Record","Any advocate with ten years' standing at the Bar","The Attorney General or the Solicitor General"],"answer":1,"explanation":"Only an Advocate-on-Record, who has passed the Court's examination and meets its conditions, can file matters and act for a party; other advocates, including senior advocates, can argue only on the instructions of an Advocate-on-Record.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"सर्वोच्च न्यायालय के नियमों के अंतर्गत, सर्वोच्च न्यायालय में किसी पक्ष की ओर से उपस्थिति दर्ज कराने और कार्य करने का अधिकार केवल किसे है?","optionsHi":["न्यायालय द्वारा नामित कोई भी वरिष्ठ अधिवक्ता","एडवोकेट-ऑन-रिकॉर्ड (अभिलेख अधिवक्ता)","बार में दस वर्ष का अनुभव रखने वाला कोई भी अधिवक्ता","महान्यायवादी या सॉलिसिटर जनरल"],"explanationHi":"केवल एडवोकेट-ऑन-रिकॉर्ड (अभिलेख अधिवक्ता), जिसने न्यायालय की परीक्षा उत्तीर्ण की हो और उसकी शर्तें पूरी करता हो, मामले दायर कर सकता है और पक्ष की ओर से कार्य कर सकता है; वरिष्ठ अधिवक्ताओं सहित अन्य अधिवक्ता केवल एडवोकेट-ऑन-रिकॉर्ड के निर्देशों पर बहस कर सकते हैं।"},
  {"id":"polity-judiciary-203","question":"The power of courts to strike down laws that conflict with the Constitution, known as judicial review, is traced to which judgment of the US Supreme Court?","options":["McCulloch v. Maryland (1819)","Gibbons v. Ogden (1824)","Marbury v. Madison (1803)","Brown v. Board of Education (1954)"],"answer":2,"explanation":"Chief Justice John Marshall's opinion in Marbury v. Madison (1803) established that courts can declare a law void for conflicting with the Constitution. In India judicial review rests on express provisions such as Articles 13, 32 and 226.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"संविधान से टकराने वाले कानूनों को रद्द करने की न्यायालयों की शक्ति, जिसे न्यायिक पुनरावलोकन कहा जाता है, का उद्गम अमेरिकी सर्वोच्च न्यायालय के किस निर्णय से माना जाता है?","optionsHi":["मैकुलोक बनाम मैरीलैंड (1819)","गिबन्स बनाम ओग्डेन (1824)","मार्बरी बनाम मेडिसन (1803)","ब्राउन बनाम बोर्ड ऑफ एजुकेशन (1954)"],"explanationHi":"मुख्य न्यायाधीश जॉन मार्शल की मार्बरी बनाम मेडिसन (1803) में दी गई राय ने स्थापित किया कि न्यायालय संविधान से टकराने वाले कानून को शून्य घोषित कर सकते हैं। भारत में न्यायिक पुनरावलोकन अनुच्छेद 13, 32 और 226 जैसे स्पष्ट प्रावधानों पर आधारित है।"},
  {"id":"polity-judiciary-204","question":"The Supreme Court of Judicature at Fort William in Calcutta, set up in 1774 under the Regulating Act, 1773, had as its first Chief Justice:","options":["William Jones","Robert Chambers","Warren Hastings","Elijah Impey"],"answer":3,"explanation":"Sir Elijah Impey was the first Chief Justice of the Calcutta Supreme Court, with Chambers, Lemaistre and Hyde as puisne judges. Warren Hastings was the Governor-General, and William Jones joined the court later.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"1774 में रेग्युलेटिंग एक्ट, 1773 के अंतर्गत कलकत्ता में स्थापित फोर्ट विलियम के सर्वोच्च न्यायालय (Supreme Court of Judicature) के प्रथम मुख्य न्यायाधीश कौन थे?","optionsHi":["विलियम जोन्स","रॉबर्ट चैंबर्स","वॉरेन हेस्टिंग्स","एलिजा इम्पी"],"explanationHi":"सर एलिजा इम्पी कलकत्ता सर्वोच्च न्यायालय के प्रथम मुख्य न्यायाधीश थे, जिनके साथ चैंबर्स, लेमेस्त्रे और हाइड अन्य न्यायाधीश थे। वॉरेन हेस्टिंग्स गवर्नर-जनरल थे, और विलियम जोन्स बाद में न्यायालय में शामिल हुए।"},
  {"id":"polity-judiciary-205","question":"Which statement about a High Court's power to punish for contempt is correct?","options":["It can punish contempt of itself and of the courts subordinate to it","It can punish contempt of itself only, never of a subordinate court","It can act only if the Advocate General files a contempt petition","It cannot punish a contempt committed outside its territorial limits"],"answer":0,"explanation":"Article 215 makes a High Court a court of record with power to punish contempt of itself, and the Contempt of Courts Act, 1971 also lets it punish contempt of subordinate courts, even if the contempt is committed outside its territorial limits. It may act on its own motion.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उच्च न्यायालय की अवमानना के लिए दंड देने की शक्ति के बारे में कौन-सा कथन सही है?","optionsHi":["वह अपनी और अपने अधीनस्थ न्यायालयों की अवमानना को दंडित कर सकता है","वह केवल अपनी अवमानना को दंडित कर सकता है, अधीनस्थ न्यायालय की कभी नहीं","वह तभी कार्य कर सकता है जब महाधिवक्ता अवमानना याचिका दायर करे","वह अपनी क्षेत्रीय सीमाओं के बाहर की गई अवमानना को दंडित नहीं कर सकता"],"explanationHi":"अनुच्छेद 215 उच्च न्यायालय को अभिलेख न्यायालय बनाता है जिसे अपनी अवमानना के लिए दंड देने की शक्ति है, और न्यायालय अवमान अधिनियम, 1971 उसे अधीनस्थ न्यायालयों की अवमानना, भले ही वह उसकी क्षेत्रीय सीमाओं के बाहर की गई हो, को दंडित करने भी देता है। वह स्वतः संज्ञान ले सकता है।"},
  {"id":"polity-judiciary-206","question":"In E. M. S. Namboodiripad v. T. Narayanan Nambiar (1970), the former Kerala Chief Minister had described the judiciary as an instrument of class oppression. The Supreme Court held that:","options":["His remarks were political criticism and so protected absolutely by Article 19(1)(a)","Free speech does not shield remarks that lower courts' authority, so he was guilty","As a former Chief Minister he was immune from contempt proceedings under Article 361","Only the Kerala Assembly, and not a court, could act against him for such remarks"],"answer":1,"explanation":"The Court upheld his conviction for contempt, holding that freedom of speech under Article 19(1)(a) is subject to the law of contempt and does not protect statements that lower the authority of courts in the public eye; it reduced the fine.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ई. एम. एस. नंबूदिरीपाद बनाम टी. नारायणन नंबियार (1970) में, केरल के पूर्व मुख्यमंत्री ने न्यायपालिका को वर्ग उत्पीड़न का साधन बताया था। सर्वोच्च न्यायालय ने माना कि:","optionsHi":["उनकी टिप्पणियां राजनीतिक आलोचना थीं और अनुच्छेद 19(1)(a) द्वारा पूर्णतः संरक्षित थीं","वाक्-स्वातंत्र्य न्यायालयों के अधिकार को घटाने वाली टिप्पणियों को संरक्षण नहीं देता, इसलिए वे दोषी थे","पूर्व मुख्यमंत्री के रूप में वे अनुच्छेद 361 के अंतर्गत अवमानना की कार्यवाही से मुक्त थे","ऐसी टिप्पणियों के लिए केवल केरल विधान सभा उनके विरुद्ध कार्रवाई कर सकती थी, न्यायालय नहीं"],"explanationHi":"न्यायालय ने उनकी अवमानना की दोषसिद्धि को बरकरार रखा, यह मानते हुए कि अनुच्छेद 19(1)(a) के अंतर्गत वाक्-स्वातंत्र्य अवमानना के कानून के अधीन है और उन कथनों को संरक्षण नहीं देता जो जनता की दृष्टि में न्यायालयों के अधिकार को घटाते हैं; उसने जुर्माना कम कर दिया।"},
  {"id":"polity-judiciary-207","question":"The idea that Parliament's amending power has implied limits, argued by M. K. Nambyar in Golaknath and later shaped into the basic structure doctrine, drew on a 1965 lecture in India by:","options":["Ivor Jennings, a British constitutional scholar","Granville Austin, an American historian","Dieter Conrad, a German jurist","K. C. Wheare, an Australian-born scholar"],"answer":2,"explanation":"Dieter Conrad's lecture on implied limitations of the amending power, drawing on Germany's experience under the Weimar Constitution, was cited by Nambyar and influenced the Court's reasoning that culminated in Kesavananda (1973).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"यह विचार कि संसद की संशोधन शक्ति की निहित सीमाएं हैं, जिसे गोलकनाथ में एम. के. नंबियार ने प्रस्तुत किया और जो बाद में मूल ढांचे के सिद्धांत में ढला, भारत में 1965 के किसके व्याख्यान से प्रेरित था?","optionsHi":["आइवर जेनिंग्स, ब्रिटिश संवैधानिक विद्वान","ग्रैनविल ऑस्टिन, अमेरिकी इतिहासकार","डिएटर कोनराड, जर्मन विधिवेत्ता","के. सी. व्हीयर, ऑस्ट्रेलियाई मूल के विद्वान"],"explanationHi":"डिएटर कोनराड के, वाइमर संविधान के अंतर्गत जर्मनी के अनुभव पर आधारित, संशोधन शक्ति की निहित सीमाओं पर व्याख्यान का हवाला नंबियार ने दिया और उसने न्यायालय के उस तर्क को प्रभावित किया जो केशवानंद (1973) में परिणत हुआ।"},
  {"id":"polity-judiciary-208","question":"The Contempt of Courts Act, 1971 was based largely on the recommendations of a committee headed by:","options":["M. C. Setalvad","V. R. Krishna Iyer","K. Santhanam","H. N. Sanyal"],"answer":3,"explanation":"The H. N. Sanyal Committee (1961-63) studied the law of contempt and its recommendations shaped the 1971 Act, which defines civil and criminal contempt. K. Santhanam headed the committee on prevention of corruption.","difficulty":"hard","source":"UPSC Prelims","questionHi":"न्यायालय अवमान अधिनियम, 1971 मुख्यतः किसकी अध्यक्षता वाली समिति की सिफारिशों पर आधारित था?","optionsHi":["एम. सी. सीतलवाड़","वी. आर. कृष्णा अय्यर","के. संथानम","एच. एन. सान्याल"],"explanationHi":"एच. एन. सान्याल समिति (1961-63) ने अवमानना के कानून का अध्ययन किया और उसकी सिफारिशों ने 1971 के अधिनियम को आकार दिया, जो सिविल और आपराधिक अवमानना को परिभाषित करता है। के. संथानम ने भ्रष्टाचार निवारण समिति की अध्यक्षता की थी।"},
  {"id":"polity-judiciary-209","question":"How many of these statements about legal services institutions are correct? I. The Chief Justice of India is the Patron-in-Chief of the National Legal Services Authority. II. The Supreme Court Legal Services Committee is chaired by a sitting judge of the Supreme Court. III. The Chief Justice of the High Court is the Patron-in-Chief of the State Legal Services Authority.","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Under the Legal Services Authorities Act, 1987 the CJI is Patron-in-Chief of NALSA, a sitting Supreme Court judge chairs the Supreme Court Legal Services Committee, and the High Court's Chief Justice is Patron-in-Chief of the State authority. All three are correct.","difficulty":"hard","source":"UPSC Prelims","questionHi":"विधिक सेवा संस्थाओं के संबंध में इनमें से कितने कथन सही हैं? I. भारत का मुख्य न्यायाधीश राष्ट्रीय विधिक सेवा प्राधिकरण का मुख्य संरक्षक होता है। II. सर्वोच्च न्यायालय विधिक सेवा समिति की अध्यक्षता सर्वोच्च न्यायालय का पदासीन न्यायाधीश करता है। III. उच्च न्यायालय का मुख्य न्यायाधीश राज्य विधिक सेवा प्राधिकरण का मुख्य संरक्षक होता है।","optionsHi":["केवल एक","केवल दो","सभी तीन","इनमें से कोई नहीं"],"explanationHi":"विधिक सेवा प्राधिकरण अधिनियम, 1987 के अंतर्गत CJI NALSA के मुख्य संरक्षक होते हैं, सर्वोच्च न्यायालय का पदासीन न्यायाधीश सर्वोच्च न्यायालय विधिक सेवा समिति की अध्यक्षता करता है, और उच्च न्यायालय का मुख्य न्यायाधीश राज्य प्राधिकरण का मुख्य संरक्षक होता है। तीनों सही हैं।"},
  {"id":"polity-judiciary-210","question":"Fast Track Courts to clear the backlog of sessions cases were first set up from 2000-01 on the recommendation of the:","options":["Eleventh Finance Commission","Law Commission in its Fourteenth Report","Malimath Committee on criminal justice","Second Administrative Reforms Commission"],"answer":0,"explanation":"The Eleventh Finance Commission recommended funds for about 1,700 Fast Track Courts, which began in 2000-01. The Malimath Committee reported only in 2003, and the Second ARC was set up in 2005.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सत्र मामलों के बकाया को निपटाने के लिए फास्ट ट्रैक न्यायालय सबसे पहले 2000-01 से किसकी सिफारिश पर स्थापित किए गए?","optionsHi":["ग्यारहवें वित्त आयोग","विधि आयोग, अपनी चौदहवीं रिपोर्ट में","आपराधिक न्याय पर मलिमथ समिति","द्वितीय प्रशासनिक सुधार आयोग"],"explanationHi":"ग्यारहवें वित्त आयोग ने लगभग 1,700 फास्ट ट्रैक न्यायालयों के लिए धन की सिफारिश की, जो 2000-01 में शुरू हुए। मलिमथ समिति ने 2003 में ही रिपोर्ट दी, और द्वितीय ARC 2005 में बना।"},
  {"id":"polity-judiciary-211","question":"The first Lok Adalat camp in India was held in 1982 in which State?","options":["Maharashtra","Gujarat","Tamil Nadu","Kerala"],"answer":1,"explanation":"The first Lok Adalat camp was organised in Gujarat in 1982, and the movement spread before the Legal Services Authorities Act, 1987 gave Lok Adalats statutory status.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"भारत में पहला लोक अदालत शिविर 1982 में किस राज्य में आयोजित हुआ?","optionsHi":["महाराष्ट्र","गुजरात","तमिलनाडु","केरल"],"explanationHi":"पहला लोक अदालत शिविर 1982 में गुजरात में आयोजित किया गया, और विधिक सेवा प्राधिकरण अधिनियम, 1987 द्वारा लोक अदालतों को वैधानिक दर्जा देने से पहले यह आंदोलन फैल गया।"},
  {"id":"polity-judiciary-212","question":"Under Article 147, a ‘substantial question of law as to the interpretation of this Constitution’ is to be read as including questions on the interpretation of:","options":["Any Act of Parliament that amends a law on a Concurrent List subject","The rules of procedure made by either House of Parliament","The Government of India Act, 1935 and Indian Independence Act, 1947","Any treaty that India has signed and ratified with another country"],"answer":2,"explanation":"Article 147 says that references to a substantial question of law on interpreting the Constitution include questions on interpreting the Government of India Act, 1935, the Indian Independence Act, 1947 and orders made under them.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 147 के अंतर्गत, ‘इस संविधान के निर्वचन के बारे में विधि का सारवान प्रश्न’ में किसके निर्वचन से संबंधित प्रश्न शामिल माने जाएंगे?","optionsHi":["संसद का कोई भी अधिनियम जो समवर्ती सूची के विषय पर किसी कानून में संशोधन करे","संसद के किसी सदन द्वारा बनाए गए प्रक्रिया के नियम","भारत शासन अधिनियम, 1935 और भारतीय स्वतंत्रता अधिनियम, 1947","कोई भी संधि जिस पर भारत ने किसी अन्य देश के साथ हस्ताक्षर और अनुसमर्थन किया हो"],"explanationHi":"अनुच्छेद 147 कहता है कि संविधान के निर्वचन पर विधि के सारवान प्रश्न के उल्लेख में भारत शासन अधिनियम, 1935, भारतीय स्वतंत्रता अधिनियम, 1947 और उनके अधीन बनाए गए आदेशों के निर्वचन के प्रश्न शामिल हैं।"},
  {"id":"polity-judiciary-213","question":"Under Article 134(1) itself, an appeal lies to the Supreme Court as of right in a criminal case where a High Court has: I. on appeal reversed an acquittal and sentenced the accused to death II. withdrawn a case from a subordinate court, tried it and sentenced the accused to death III. on appeal reversed an acquittal and sentenced the accused to imprisonment for life","options":["I, II and III","I and III only","II and III only","I and II only"],"answer":3,"explanation":"Article 134(1)(a) and (b) cover only death sentences, after reversing an acquittal or after withdrawing and trying a case, so I and II qualify. A life sentence (or ten years or more) imposed on reversal of an acquittal is appealable as of right only under the 1970 Act enlarging the Supreme Court's criminal appellate jurisdiction, made under Article 134(2), so III is not under Article 134(1) itself.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 134(1) के अंतर्गत ही, किसी आपराधिक मामले में सर्वोच्च न्यायालय में अपील अधिकार के रूप में तब होती है जब उच्च न्यायालय ने: I. अपील में दोषमुक्ति को पलटकर अभियुक्त को मृत्युदंड दिया हो II. किसी अधीनस्थ न्यायालय से मामला अपने पास मंगवाकर, उसका विचारण कर अभियुक्त को मृत्युदंड दिया हो III. अपील में दोषमुक्ति को पलटकर अभियुक्त को आजीवन कारावास दिया हो","optionsHi":["I, II और III","केवल I और III","केवल II और III","केवल I और II"],"explanationHi":"अनुच्छेद 134(1)(a) और (b) केवल मृत्युदंड को कवर करते हैं, जो दोषमुक्ति पलटने के बाद या मामला मंगवाकर विचारण करने के बाद दिया गया हो, इसलिए I और II सही हैं। दोषमुक्ति पलटने पर दिए गए आजीवन कारावास (या दस वर्ष या अधिक) के विरुद्ध अधिकार के रूप में अपील केवल अनुच्छेद 134(2) के अंतर्गत बने, सर्वोच्च न्यायालय का आपराधिक अपीलीय क्षेत्राधिकार बढ़ाने वाले 1970 के अधिनियम से होती है, इसलिए III स्वयं अनुच्छेद 134(1) के अंतर्गत नहीं है।"},
  {"id":"polity-judiciary-214","question":"In Whirlpool Corporation v. Registrar of Trade Marks (1998), the Supreme Court said that an alternative remedy does not bar a writ under Article 226 in certain situations. Which of these is NOT one of them?","options":["The petitioner prefers the High Court because a writ is quicker","The petition seeks to enforce one of the Fundamental Rights in Part III","The order was passed in violation of natural justice","The proceedings are wholly without jurisdiction"],"answer":0,"explanation":"Whirlpool listed enforcement of a Fundamental Right, violation of natural justice, action wholly without jurisdiction and a challenge to the vires of an Act as cases where the alternative remedy rule does not apply. Mere convenience or speed is not an exception.","difficulty":"hard","source":"UPSC Prelims","questionHi":"व्हर्लपूल कॉर्पोरेशन बनाम रजिस्ट्रार ऑफ ट्रेड मार्क्स (1998) में सर्वोच्च न्यायालय ने कहा कि कुछ स्थितियों में वैकल्पिक उपाय अनुच्छेद 226 के अंतर्गत रिट को नहीं रोकता। इनमें से कौन-सी उनमें से एक नहीं है?","optionsHi":["याचिकाकर्ता उच्च न्यायालय को इसलिए पसंद करता है क्योंकि रिट अधिक शीघ्र होती है","याचिका भाग III के किसी मौलिक अधिकार को लागू कराने के लिए है","आदेश प्राकृतिक न्याय के उल्लंघन में पारित किया गया था","कार्यवाही पूर्णतः क्षेत्राधिकार के बिना है"],"explanationHi":"व्हर्लपूल ने मौलिक अधिकार के प्रवर्तन, प्राकृतिक न्याय के उल्लंघन, पूर्णतः क्षेत्राधिकार-रहित कार्रवाई और किसी अधिनियम की वैधता को चुनौती को ऐसे मामले बताया जहां वैकल्पिक उपाय का नियम लागू नहीं होता। केवल सुविधा या शीघ्रता अपवाद नहीं है।"},
  {"id":"polity-judiciary-215","question":"In Om Kumar v. Union of India (2001), the Supreme Court explained how courts review administrative action. It held that where such action restricts the freedoms under Article 19 or the right under Article 21, courts apply:","options":["Wednesbury unreasonableness alone, with courts acting only as secondary reviewers","Proportionality, acting as primary reviewers of the action","Strict scrutiny as developed by the United States courts","No review at all, since such action is a matter of policy"],"answer":1,"explanation":"The Court held that administrative action affecting fundamental freedoms is tested for proportionality, with courts as primary reviewers, while action challenged only as arbitrary under Article 14 is tested on Wednesbury principles, with courts as secondary reviewers.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ओम कुमार बनाम भारत संघ (2001) में सर्वोच्च न्यायालय ने समझाया कि न्यायालय प्रशासनिक कार्रवाई की समीक्षा कैसे करते हैं। उसने माना कि जहां ऐसी कार्रवाई अनुच्छेद 19 की स्वतंत्रताओं या अनुच्छेद 21 के अधिकार को सीमित करती है, वहां न्यायालय क्या लागू करते हैं?","optionsHi":["केवल वेडनेसबरी अयुक्तियुक्तता, जिसमें न्यायालय केवल द्वितीयक समीक्षक होते हैं","आनुपातिकता, जिसमें न्यायालय कार्रवाई के प्राथमिक समीक्षक होते हैं","अमेरिकी न्यायालयों द्वारा विकसित कठोर संवीक्षा","कोई समीक्षा नहीं, क्योंकि ऐसी कार्रवाई नीति का विषय है"],"explanationHi":"न्यायालय ने माना कि मौलिक स्वतंत्रताओं को प्रभावित करने वाली प्रशासनिक कार्रवाई की आनुपातिकता की कसौटी पर जांच होती है, जिसमें न्यायालय प्राथमिक समीक्षक होते हैं, जबकि केवल अनुच्छेद 14 के अंतर्गत मनमानी के रूप में चुनौती दी गई कार्रवाई की जांच वेडनेसबरी सिद्धांतों पर होती है, जिसमें न्यायालय द्वितीयक समीक्षक होते हैं।"},
  {"id":"polity-judiciary-216","question":"From 1950 until it moved to its present building in 1958, the Supreme Court sat in:","options":["The Durbar Hall of Rashtrapati Bhavan","Hyderabad House on Ashoka Road in New Delhi","The Chamber of Princes in Parliament House","The Diwan-i-Aam of the Red Fort"],"answer":2,"explanation":"The Supreme Court, like the Federal Court before it, sat in the Chamber of Princes in the Parliament building until it moved to its own building on Tilak Marg in 1958.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"1950 से 1958 में अपने वर्तमान भवन में जाने तक सर्वोच्च न्यायालय कहां बैठता था?","optionsHi":["राष्ट्रपति भवन का दरबार हॉल","नई दिल्ली में अशोक रोड पर हैदराबाद हाउस","संसद भवन में नरेंद्र मंडल (चैंबर ऑफ प्रिंसेस)","लाल किले का दीवान-ए-आम"],"explanationHi":"सर्वोच्च न्यायालय, अपने से पहले के संघीय न्यायालय की तरह, 1958 में तिलक मार्ग पर अपने भवन में जाने तक संसद भवन के नरेंद्र मंडल (चैंबर ऑफ प्रिंसेस) में बैठता था।"},
  {"id":"polity-judiciary-217","question":"The motto on the emblem of the Supreme Court of India, ‘Yato Dharmastato Jayah’, means:","options":["Truth alone triumphs","Justice delayed is justice denied","Righteousness protects those who protect it","Where there is dharma, there is victory"],"answer":3,"explanation":"The phrase, from the Mahabharata, means that victory lies where dharma (righteousness) is. ‘Truth alone triumphs’ is Satyameva Jayate, the national motto.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"भारत के सर्वोच्च न्यायालय के प्रतीक चिह्न पर अंकित आदर्श वाक्य ‘यतो धर्मस्ततो जयः’ का अर्थ है:","optionsHi":["सत्य की ही जीत होती है","विलंबित न्याय, न्याय से इनकार है","धर्म उनकी रक्षा करता है जो उसकी रक्षा करते हैं","जहां धर्म है, वहां विजय है"],"explanationHi":"महाभारत का यह वाक्यांश बताता है कि विजय वहीं है जहां धर्म (नीतिपरायणता) है। ‘सत्य की ही जीत होती है’ सत्यमेव जयते है, जो राष्ट्रीय आदर्श वाक्य है।"},
  {"id":"polity-judiciary-218","question":"The Judges (Protection) Act, 1985 provides that:","options":["No court may hear a civil or criminal case against a judge over judicial acts","No judge can be transferred to another court without first giving his written consent","A judge's salary cannot be reduced even during a Financial Emergency","No judge can be arrested without the prior sanction of the President"],"answer":0,"explanation":"The Act bars courts from entertaining civil or criminal proceedings against a judge or magistrate for any act, thing or word done or spoken in the discharge of official or judicial duty, though the government's power to act against him otherwise is saved.","difficulty":"hard","source":"UPSC Prelims","questionHi":"न्यायाधीश (संरक्षण) अधिनियम, 1985 यह उपबंध करता है कि:","optionsHi":["कोई न्यायालय न्यायिक कृत्यों के संबंध में किसी न्यायाधीश के विरुद्ध दीवानी या आपराधिक मामले की सुनवाई नहीं कर सकता","किसी न्यायाधीश का स्थानांतरण उसकी लिखित सहमति के बिना किसी अन्य न्यायालय में नहीं हो सकता","वित्तीय आपातकाल में भी किसी न्यायाधीश का वेतन कम नहीं किया जा सकता","राष्ट्रपति की पूर्व स्वीकृति के बिना किसी न्यायाधीश को गिरफ्तार नहीं किया जा सकता"],"explanationHi":"अधिनियम न्यायालयों को किसी न्यायाधीश या मजिस्ट्रेट के विरुद्ध उसके आधिकारिक या न्यायिक कर्तव्य के निर्वहन में किए गए या कहे गए किसी कृत्य, बात या शब्द के लिए दीवानी या आपराधिक कार्यवाही स्वीकार करने से रोकता है, यद्यपि अन्यथा उसके विरुद्ध कार्रवाई करने की सरकार की शक्ति सुरक्षित है।"},
  {"id":"polity-judiciary-219","question":"Who became, in 2018, the first woman to be appointed a judge of the Supreme Court directly from the Bar?","options":["R. Banumathi","Indu Malhotra","Ruma Pal","Sujata Manohar"],"answer":1,"explanation":"Indu Malhotra, a senior advocate, was elevated directly from the Bar in April 2018. Ruma Pal, Sujata Manohar and R. Banumathi had come to the Supreme Court from High Courts.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"2018 में बार से सीधे सर्वोच्च न्यायालय की न्यायाधीश नियुक्त होने वाली प्रथम महिला कौन बनीं?","optionsHi":["आर. भानुमति","इंदु मल्होत्रा","रूमा पाल","सुजाता मनोहर"],"explanationHi":"वरिष्ठ अधिवक्ता इंदु मल्होत्रा अप्रैल 2018 में बार से सीधे पदोन्नत हुईं। रूमा पाल, सुजाता मनोहर और आर. भानुमति उच्च न्यायालयों से सर्वोच्च न्यायालय आई थीं।"},
  {"id":"polity-judiciary-220","question":"In October 2017 the Supreme Court collegium took a decision to improve the transparency of the appointment process. What did it decide?","options":["To hand over appointments to the National Judicial Appointments Commission","To include the Union Law Minister as a full member of the collegium","To hold all of its meetings in open court with the Bar present","To publish its recommendations and reasons on the Supreme Court website"],"answer":3,"explanation":"The collegium resolved to upload its decisions on appointments and elevations, with reasons, to the Supreme Court website. The NJAC had been struck down in 2015, and the collegium remains a body of judges only.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अक्टूबर 2017 में सर्वोच्च न्यायालय के कॉलेजियम ने नियुक्ति प्रक्रिया की पारदर्शिता बढ़ाने के लिए एक निर्णय लिया। उसने क्या तय किया?","optionsHi":["नियुक्तियां राष्ट्रीय न्यायिक नियुक्ति आयोग को सौंप देना","केंद्रीय विधि मंत्री को कॉलेजियम का पूर्ण सदस्य बनाना","अपनी सभी बैठकें बार की उपस्थिति में खुले न्यायालय में करना","अपनी सिफारिशें और उनके कारण सर्वोच्च न्यायालय की वेबसाइट पर प्रकाशित करना"],"explanationHi":"कॉलेजियम ने नियुक्तियों और पदोन्नतियों पर अपने निर्णय कारणों सहित सर्वोच्च न्यायालय की वेबसाइट पर अपलोड करने का संकल्प लिया। NJAC को 2015 में रद्द किया जा चुका था, और कॉलेजियम केवल न्यायाधीशों का निकाय बना हुआ है।"},
  {"id":"polity-judiciary-221","question":"The Committee on Reforms of the Criminal Justice System, which submitted its report in 2003, was headed by:","options":["V. S. Malimath","H. N. Sanyal","M. N. Venkatachaliah","B. N. Srikrishna"],"answer":0,"explanation":"Justice V. S. Malimath's committee recommended changes to criminal procedure and evidence. M. N. Venkatachaliah headed the National Commission to Review the Working of the Constitution, and H. N. Sanyal the earlier committee on contempt.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आपराधिक न्याय प्रणाली के सुधार पर समिति, जिसने 2003 में अपनी रिपोर्ट प्रस्तुत की, की अध्यक्षता किसने की?","optionsHi":["वी. एस. मलिमथ","एच. एन. सान्याल","एम. एन. वेंकटचलैया","बी. एन. श्रीकृष्ण"],"explanationHi":"न्यायमूर्ति वी. एस. मलिमथ की समिति ने आपराधिक प्रक्रिया और साक्ष्य में परिवर्तनों की सिफारिश की। एम. एन. वेंकटचलैया ने संविधान के कार्यकरण की समीक्षा के लिए राष्ट्रीय आयोग की अध्यक्षता की, और एच. एन. सान्याल ने अवमानना पर पहले की समिति की।"},
  {"id":"polity-judiciary-222","question":"Under the Contempt of Courts Act, 1971, which of these is civil contempt rather than criminal contempt?","options":["Publishing matter that scandalises or lowers the authority of a court","Publishing matter that interferes with the due course of a pending trial","Obstructing the administration of justice in any other manner","Wilful breach of an undertaking given to a court"],"answer":3,"explanation":"Civil contempt is wilful disobedience of a court's judgment, decree, order or writ, or wilful breach of an undertaking given to a court. Scandalising a court, prejudicing proceedings and obstructing justice are criminal contempt.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"न्यायालय अवमान अधिनियम, 1971 के अंतर्गत इनमें से कौन-सा आपराधिक अवमानना के बजाय सिविल अवमानना है?","optionsHi":["ऐसी सामग्री प्रकाशित करना जो न्यायालय की प्रतिष्ठा को ठेस पहुंचाए या उसके अधिकार को घटाए","ऐसी सामग्री प्रकाशित करना जो लंबित विचारण के उचित क्रम में हस्तक्षेप करे","किसी अन्य प्रकार से न्याय प्रशासन में बाधा डालना","न्यायालय को दिए गए वचन का जानबूझकर भंग करना"],"explanationHi":"सिविल अवमानना किसी न्यायालय के निर्णय, डिक्री, आदेश या रिट की जानबूझकर अवज्ञा, या न्यायालय को दिए गए वचन का जानबूझकर भंग है। न्यायालय की प्रतिष्ठा को ठेस पहुंचाना, कार्यवाही को प्रभावित करना और न्याय में बाधा डालना आपराधिक अवमानना हैं।"},
];

export default questions;
